WordHunterWoW_QuestEN[14177] = { title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Troll Spirit in Orgrimmar's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday." }
WordHunterWoW_QuestEN[14178] = { title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, <name>.  We cannot allow the Horde scum to secure the resources that are rightfully ours!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[14179] = { title = "Call to Arms: Eye of the Storm", description = "The fight against the Horde knows no boundaries, <name>.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[14180] = { title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[14181] = { title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, <class>, go to Arathi Basin and crush the enemy.  Victory to the Horde!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[14182] = { title = "Call to Arms: Eye of the Storm", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran,  or Shattrath." }
WordHunterWoW_QuestEN[14183] = { title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, <name>.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[14184] = { title = "My Time Has Passed", description = "<Weakly, Furien beckons you near and struggles to speak.>\n\nCareless... I was shot down by Alliance fire...\n\nYou must... inform my sister.\n\nTake my mount, {race}... he'll bring you to her...\n\n<Furien expires.>", objectives = "Furien at Tethris Aran wants you to ride his Dragonhawk to Furien's Post and inform his sister, Cerelia of his death.", completion = "What!?\n\nFurien!! My brother is no more?\n\nThey must pay! All of them!" }
WordHunterWoW_QuestEN[14185] = { title = "FLAG: Riding Trainer Advertisement (40)", description = "", objectives = "" }
WordHunterWoW_QuestEN[14186] = { title = "FLAG: Riding Trainer Advertisement (60)", description = "", objectives = "" }
WordHunterWoW_QuestEN[14187] = { title = "FLAG: Riding Trainer Advertisement (70)", description = "", objectives = "" }
WordHunterWoW_QuestEN[14188] = { title = "Avenge Furien!", description = "This cannot be!\n\nMy dear brother - slain by Alliance scum!\n\nThey must be made to suffer, {race}! Find a way to bring them pain! I shall not rest until it is so...\n\nFurien had been researching ancient artifacts in the eastern regions before his death. Speak to Sorrem. Perhaps he can direct you in my brother's footsteps.", objectives = "Cerelia wants you to speak with Sorrem at Furien's Post.", completion = "Furien's passing is... regrettable.\n\nI shall do all that I can to assist you in avenging his death." }
WordHunterWoW_QuestEN[14189] = { title = "Translation", description = "It is true that Furien dedicated his last days to a special research project. What that was, he would not share with me.\n\nFortunately, I was able to recover his journal, but it's written in a code that I cannot decipher.\n\nPerhaps there is a clue to its translation in the region to the east where he spent his time.\n\nTake the journal, {class}, and speak with Narimar when you are ready to investigate this mystery.", objectives = "Sorrem wants you to find the Ancient Tablets.\n\nSpeak to Narimar at Furien's Post to ride to where Furien was known to study.\n\nProvided item:", completion = "Comparing the characters on the ancient tablet to those in Furien's journal, it is clear that there is a distinct correlation." }
WordHunterWoW_QuestEN[14190] = { title = "The Perfect Prism", description = "There's got to be a way to reverse the basilisks' stonification. Those irritating night elf saboteurs who have been lurking around my mine must know something we don't. They seem to be immune to the gaze of the beast!\n\nI want you to find out their secret, {name}. Pick off a few of the Talrendis saboteurs skulking about in the rear of the strip mine and get a sample of whatever charm or ding-dong they're wearing to give them immunity. Radio me from the main forge building once you're successful.", objectives = "Acquire a Crystal Pendant from a Talrendis Saboteur in the Mountainfoot Strip Mine.", progress = "<Strange goblin speakers hiss and crackle.>", completion = "<Zignibble's voice squawks over the speakers.>\n\nIs that you, <name>? Still alive? You aren't trashing my explosive stockpiles are you?\n\nHmmm... you say you found a clear crystal pendant. That makes sense. A perfect prism would refract the gaze of the basilisk. Maybe we can use this to our advantage. Time to drop some science!" }
WordHunterWoW_QuestEN[14191] = { title = "Furien's Footsteps", description = "You can decipher bits and pieces of the text, but it will require extensive study before Furien's work becomes coherent.\n\nFor now, as you look off to the northeast, you think you can make out some of the ruins depicted in the journal.\n\nFrom what you can tell, these ruins seem to have been of some significance to Furien's research.", objectives = "The Ancient Tablets at the Shrine of Elune have directed you to visit three of the prominent ruins in Sargeron.", completion = "It is clear to you now that these ruins are those that Furien recorded in his journal.\n\nAfter examining the engravings upon the ruins themselves, you feel that you are able to decipher more of Furien's writings." }
WordHunterWoW_QuestEN[14192] = { title = "Prismbreak", description = "If that prism of yours is tuned to refract a basilisk's gaze, we can use its crystal properties to reverse the process. All we need is a source of power.\n\nIn the weapons cabinet to your right, you'll find our prototype laser mining drill. I loved that thing but the near daily dismemberments got to be a real bother. Grab the laser drill and swap out the lens with that crystal of yours...", objectives = "Take the Crystal Pendant to the Weapons Cabinet in the Mountainfoot Strip Mine Headquarters.", progress = "<The weapons cabinet is loaded with heinous and broken experimental devices, some of which still have goblin limbs attached. You discover the laser drill lovingly ensconced in a velvet-lined wooden case.>", completion = "<You pop out the lens assembly and slide the crystal into place. The weapon hums ominously.>" }
WordHunterWoW_QuestEN[14193] = { title = "Nothing a Couple of Melons Won't Fix", description = "The markings on the ruins here make one thing clear: There is something special about the old fountain in the Sanctuary of Elune.\n\nIt would seem that one could expect special power from washing their face in the fountain. First, of course, there would need to be something in the ancient fountain with which to wash.\n\nPondering this problem, you spot a melonfruit at the base of a nearby tree....", objectives = "Gather 8 Melonfruit.", completion = "After filling it with liquid from the melons, you proceed to wash your eyes from the ancient font.\n\nUpon opening your eyes, you are able to see the spirits of ancient elves, still faithfully carrying out rituals to their goddess." }
WordHunterWoW_QuestEN[14194] = { title = "Refleshification", description = "<The nearby radio calls out to you.>\n\nHey {name}, you got that gun? Good! Don't point it directly at your eye.\n\nAim that baby at my stonified workers and the refracted light should reverse the petrification process. Or it will melt them. Whatever. Return my workers to a state of profitability! And if the refleshification process makes them crazy-go-nuts, they should be killed for insurance purposes. Horzak OUT! ", objectives = "Use The Refleshifier to de-stonify eight Mountainfoot Miners within the Mountainfoot Strip Mine.", progress = "Hey look, all your limbs are intact.", completion = "Ah, good. Now we can get these slackers back to work. You've earned a cut of the profits though - minus the usual company fees. Take your pick!" }
WordHunterWoW_QuestEN[14195] = { title = "All Becoming Clearer", description = "Something has changed... perhaps a side-effect of Elune's cleansing ritual.\n\nWhile it's by no means perfect yet, your understanding of the ancient language in the journal has vastly improved.\n\nThe ruins in the northern mountains of Sargeron appear to be the main focus of Furien's enthusiasm. Something there, he felt, would aid him in driving the Alliance from this region.\n\nYou close the journal determined to find this ruin and discover its secrets.", objectives = "Furien's Journal has directed you to find the ruined Palace of Elune in northern Sargeron.", progress = "This appears to be the ruin depicted in Furien's Journal.", completion = "It is clear to you now why you were guided here.\n\nYou recognize this ancient runestone from Furien's final journal entry:\n\n\"The ancients revered the gems created by this mystical object, claiming that they were gifts from the goddess herself. It was believed that they were weapons capable of delivering them from any enemy.\"" }
WordHunterWoW_QuestEN[14196] = { title = "Firestarter", description = "You are now able to understand the script in which the journal was written.\n\nAlong the runestone, it is explained that the monument's gemstones were imbued with the power to summon a firestorm.\n\nThe storm could grow to be a mighty weapon either through sustained worship of Elune, or charged by spiritual energies of the fallen.\n\nLooking down upon the newly revealed ghosts of Elune's disciples, you reason that you have neither the time, nor the inclination to worship the goddess of your enemy....", objectives = "You are to create a Raging Vortex by defeating 7 Disciples of Elune in the presence of your firestorm.\n\nShould you lose your Vortex Gem, another can be obtained from the Ancient Vortex Runestone.", completion = "It is done! Furien's exhaustive research was not in vain.\n\nThe raging Vortex is ready to be unleashed upon your enemies at last!" }
WordHunterWoW_QuestEN[14197] = { title = "A Quota to Meet", description = "Mountainfoot iron is a brittle alloy, but with the right bribes it meets goblin safety standards. Zignibble here is having trouble on the production end of things, but that doesn't change any of my deadlines. I've got a quota to fill!\n\nHead down into the Mountainfoot Strip Mine and gather up any ingots of Mountainfoot iron you find. There should be piles of it smelted and ready for shipment.", objectives = "Gather 20 ingots of Mountainfoot Iron from the Mountainfoot Strip Mine in Azshara.", progress = "Did you get my shipment together?", completion = "Well done! When it comes to iron, always pick quantity over quality." }
WordHunterWoW_QuestEN[14198] = { title = "Rider on the Storm", description = "You cannot help but to feel a twinge of pride, having unlocked this long lost secret of the ancient worshippers of Elune.\n\nYou now possess the power to inflict great damage upon your enemy.\n\nAs it was Furien's tireless work that made this possible, it only seems right that the weapon should be unleashed upon those who took his life.\n\nThe Alliance scum at Nijel's Point shall pay for their offenses against the Horde!", objectives = "Use the Raging Vortex Gem at Nijel's Point Ruin. While commanding your firestorm, kill 40 Nijel's Point Defenders and burn 15 Nijel's Point Merchants.\n\nShould you lose your Raging Vortex Gem, you may acquire another from the Ancient Vortex Runestone.", completion = "Very impressive, <class>.\n\nYou completed Furien's work and rained vengeance down upon his killers.\n\nYou have brought peace to my brother's soul, and to my mind. Please accept this gift for your diligence." }
WordHunterWoW_QuestEN[14199] = { title = "Proof of Demise: The Black Knight", description = "My counterpart, Archmage Timear, has asked me to warn you of something dire. Soon, you will be participating in the Trial of the Champions at the Argent Coliseum in Icecrown. You must beware of interference from one known only as the Black Knight.\n\nBring me a fragment of his soul that the Kirin Tor will know he is dealt with. I am told that failing to do so will be your own undoing.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Archmage Lan'dalock in Dalaran wants you to return with a Fragment of the Black Knight's Soul.\n\nThis quest may only be completed on Heroic difficulty." }
WordHunterWoW_QuestEN[14200] = { title = "Kickoff Mail Marker", description = "", objectives = "" }
WordHunterWoW_QuestEN[14201] = { title = "A Thousand Stories in the Sand", description = "The ruins around Lake Mennar, to our east, have a tale to tell. The lesser races - like those clumsy dwarves - would go after the truth with picks and shovels. <Malynea wrinkles her nose.> We'll be using more elegant methods.\n\nMy scrying magic is somewhat rusty, but with the right trinket I should be able to peer through the shrouds of time. The bones of my forefathers have long since rotted away but some of their personal treasures may remain - bring me some.", objectives = "Collect 5 Recovered Artifacts from the ruins around Lake Mennar in Azshara.", progress = "Have you gotten your hands dirty for me?", completion = "<Malynea furrows her brow and begins sifting through the artifacts you brought her.>\n\nSo the spirits of the dead still haunt those old stones, hm? Well <name>, as it happens, I'm counting on their help. Let's see what the dead have to say..." }
WordHunterWoW_QuestEN[14202] = { title = "Survey the Lakeshore", description = "All these cruddy ancient ruins have to be bulldozed if we're ever to see Azshara's full potential. Look on my map here - you see Lake Mennar, to the East? I'll tell you what I see: a future rocket fuel depot!\n\nBut we need an accurate lay of the land before we can clearcut, bulldoze, landfill, and pave over that lake. All of my surveyors have been spooked off by the oogly-boogleys haunting that area. Escort one of my Jr. grade surveyors to the area and take readings from the equipment that's been set up.", objectives = "Escort a Goblin Surveyor to the three pieces of Surveyor's Equipment that surround Lake Mennar, and defend her while she takes readings. Another Surveyor can always be summoned with your Surveyor's Beacon.", progress = "No buncha dead elves can put a stop to progress. Not on my watch!", completion = "Beautiful work! Now that we know the area better, we can tear this lake a new one." }
WordHunterWoW_QuestEN[14203] = { title = "Waterlogged Recipe", description = "This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....", objectives = "Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.", progress = "Wine is only as fine as the person drinking it, I always say.", completion = "This is quite a find, <name>.  I can't have you selling this to anyone else, so I'm willing to offer generously." }
WordHunterWoW_QuestEN[14204] = { title = "From the Shadows", description = "He turned into one of them... didn't he?  How do we even begin to fight an enemy that can do this to us?\n\nMy father's arsenal's certainly a good start, I suppose.\n\nWorgen are hiding in the alleys ahead.  Take one of my mastiffs to find them more easily.\n\nWe're going to need to clear the way ahead if we're going to move these cannons above ground.", objectives = "Defeat 6 Bloodfang Lurkers.", progress = "Is it done yet, <name>?", completion = "Excellent.  I'll start rounding up some help to get these cannons positioned." }
WordHunterWoW_QuestEN[14209] = { title = "Gunk in the Trunk", description = "Those ancient ruins have survived ten thousand years of wind and weather, so I brought out my biggest and bestest bulldozer to flatten 'em. I call her \"Margene.\"\n\nBut my dozer's been letting me down lately, {name}. The moment I drove her into those haunted woods, her engine seized up with a spine-chilling howl. Now my engineers tell me something's clogging her valves. Go over there and inspect Margene's engine compartment, and bring me back a sample of whatever gunk has her stalled.", objectives = "Inspect Clubnik's Dozer and collect a sample of the Ectosplatter that's gumming up the engine.", progress = "Margene is one heck of a machine, isn't she?", completion = "Busted ball bearings! Look at this stuff - ugh, SMELL this stuff - my poor, poor dozer!\n\n<name>, I consider myself a goop expert and this here goop ain't natural. It's supernatural. This is ghost goop. We're going to need more than a mechanic..." }
WordHunterWoW_QuestEN[14212] = { title = "Sacrifices", description = "You don't have to do this, {name}.  You've done more than enough already.\n\nBut if you decide to stay... I'd be a fool to turn you away.\n\nMy men have fortified their position inside the cathedral and are ready for what comes next.\n\nI'm about to head there and take as many of these flea-ridden devils with me as I can.  You're welcome to come along for the ride.", objectives = "Ride with Lord Darius Crowley and round up 30 Bloodfang Stalkers.", progress = "Every <race> we keep inside the city is one less <race> going after our loved ones outside.", completion = "Brace yourself, <name>.\n\nHere they come." }
WordHunterWoW_QuestEN[14213] = { title = "Ten Pounds of Flesh", description = "According to Furien's Journal, this ancient brazier was placed here for the performing of sacrifices.\n\nAs far as you can make out from the entry, a blessing is bestowed upon the being who places the flesh of Elune's enemies on the brazier's burning embers.\n\nLooking around, you determine that the satyrs who now possess this region would likely qualify.", objectives = "You are to collect 10 pieces of Satyr Flesh from the various Satyrs in Sargeron, and place them on Elune's Brazier.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier indiscriminately endows you with a blessing." }
WordHunterWoW_QuestEN[14214] = { title = "Message to Greymane", description = "It's time, {name}.  We'll take it from here.\n\nTell King Greymane that my father's arsenal will be at his disposal.  There's more than enough firepower here to blow the worgen from here to the north sea.", objectives = "Speak to King Genn Greymane in the Military District.", completion = "I knew Crowley would come through.  His weapons will be more than useful to us." }
WordHunterWoW_QuestEN[14215] = { title = "Memories of the Dead", description = "The runes on this ring you found are still legible: it was given to \"Kalytha\" when she was granted admission to the Academy. With the right spell or two, this personal trinket of hers is the gateway to her soul.\n\nTake the ring back to Lake Mennar. Kalytha's spirit should now be visible to you on the shore of the lake. Touch her and the ring will allow you to see the world as she sees it, forever reliving her final hours. Probe her mind, {name}! Speak to the others and learn the secrets of Lake Mennar...", objectives = "Take Kalytha's Ring to the shores of Lake Mennar. Touch the Spirit of Kalytha to relive her memories. Speak to the other spirits until you've learned the secret of Lake Mennar.", completion = "You reel as the spirit's vision fades, relieved to once again feel the earth beneath your feet and the comforting rhythm of your own quickened heart." }
WordHunterWoW_QuestEN[14216] = { title = "Mystery of the Sarcen Stone", description = "Before she died, Kalytha was charged with burying something at the bottom of the lake, a powerful artifact that the archmages of Mennar spent their last moments creating. No doubt Malynea Skyreaver will want to see the artifact, presuming it still exists. You resolve to search the bottom of Lake Mennar for the Sarcen Stone. ", objectives = "Retrieve the Sarcen Stone from the bottom of Lake Mennar.", progress = "Did you discover anything at the lake? You're soaking wet.", completion = "A Sarcen stone? That's the stuff of legend - let me see that!\n\n<name>, Sarcen stones are used to redirect the ley lines of magical energy. You realize what this means? The mages of Mennar weren't staying behind out of misguided loyalty. They sacrificed their lives in order to create this artifact in an attempt to draw energy away from the portal through which the demons were flooding Azeroth. They were buying time for the rest of the world to fight back! History never recorded their deeds. What a discovery!" }
WordHunterWoW_QuestEN[14217] = { title = "Satyrical Offerings", description = "You find it most amusing to think that this ancient relic is bestowing upon you a blessing meant for your enemies.\n\nYou determine to make as much as you can of this unintentional gift.", objectives = "You are to collect 10 pieces of Satyr Flesh from the various Satyrs in Sargeron, and place them on Elune's Brazier.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier indiscriminately endows you with a blessing." }
WordHunterWoW_QuestEN[14218] = { title = "By Blood and Ash", description = "The time has come, {name}.  If we're going to put a dent in their numbers, the time is now.\n\nWe have the position.\n\nWe have the firepower.\n\nAll that remains to be seen is whether we have the courage... and I sure don't see a coward standing in front of me.", objectives = "Slay 80 Bloodfang Stalkers using the Rebel Cannons.", progress = "We must take out as many of them as we can, <name>.", completion = "You've done well, <name>.  You've done more than could be asked of any Gilnean.\n\nWe're running low on ammunition.  It's time to regroup inside now." }
WordHunterWoW_QuestEN[14219] = { title = "To the Hilt!", description = "You immediately recognize this statue from a sketch in Furien's Journal.\n\nThough the words associated with the entry elude you, the sketch seems self-explanatory. After battle, the enemies' weapons were to be cast upon the basin in exchange for a divine gift of some sort.\n\nAs you ponder this ritual, the glint of steel catches your eye from a nearby weapon rack....", objectives = "You are to collect 20 Satyr Sabers from the weapon racks and various satyrs in the region, then place them upon the statue, Elune's Handmaiden.", progress = "The statue stands expectantly.", completion = "With the ritual completed, you are awarded a divine gift.\n\nYou can't help but wonder what Elune would think of someone such as you receiving one of her boons." }
WordHunterWoW_QuestEN[14220] = { title = "This Is the End", description = "We've been able to hold them as they pour through the narrow entrance... but I think they're devising a change of tactics.\n\nThis I know.  Genn Greymane has led our people to safety by now.  We have succeeded.", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14221] = { title = "Never Surrender, Sometimes Retreat", description = "We had enough ammunition to carry on the civil war for another month.  Yet the worgen's numbers are such that we're nearly spent.\n\nWe don't want to be caught out here in the open when that happens.  Fall back inside the cathedral and report to the boss.  I'm sure old Crowley will know what to do next.", objectives = "Speak to Lord Darius Crowley inside the Light's Dawn Cathedral.", completion = "We've given them everything we have... yet still they come.  Do not worry, <name>.  We'll slay many more before today is over." }
WordHunterWoW_QuestEN[14222] = { title = "Last Stand", description = "We've got a good chokepoint here, {name}.  Feel free to say a prayer if that's your sort of thing.\n\nTake courage and let's kill these mutts.", objectives = "Kill 8 Frenzied Stalkers.", progress = "We can do this, <name>.", completion = "They... they've stopped coming.\n\nNo, <name>.  That's not a good thing." }
WordHunterWoW_QuestEN[14223] = { title = "Peace of Mind", description = "We are a forward post, charged with monitoring potential adversaries. Once the Horde launches its Desolace campaign, our work here will ensure that nothing takes us by surprise.\n\nRecently, one of our scouts was caught and sacrificed by the Burning Blade at their stronghold to the east. Since then, we've been assaulted with threats and taunts from a Burning Blade wretch named Kohor.\n\nTheir days here are numbered, but I will pay handsomely for that one to be silenced now!", objectives = "Sorrem at Furien's Post wants you to kill Kohor.", progress = "So, is it done, <class>?", completion = "It is done.\n\nSorrem should be able to sleep in peace now that Kohor's threats have been silenced." }
WordHunterWoW_QuestEN[14225] = { title = "You'll Know It When You See It", description = "With his dying breath, Kohor mentioned the summoning of a demon that could threaten the entire region.\n\nHe may have been bluffing, but that's not a chance worth taking.\n\nThis cannot wait for the Horde's invasion of Desolace to take shape. You must scour Thunder Axe Fortress for clues and bring an end to this potential threat.", objectives = "Sorrem at Furien's Post wants you to find the Ancient Summoning Ritual in Thunder Axe Fortress.", progress = "The Burning Blade must not be allowed to succeed with their plan!", completion = "It is most fortunate that you took the time to search for this.\n\nNo one would have expected the Burning Blade to be in possession of something so powerful!" }
WordHunterWoW_QuestEN[14226] = { title = "Trouble Under Foot", description = "Look at you. Doing errands. Quite responsible of you. You're moving up up up, you are... up up!\n\nThere be demons ahead! Demons of many unpleasant kinds. Demons that would quite like your innards! Legash demons of a southeasternly heading! But do not worry. No no, no reason to worry, for I shall provide you with a companion!\n\nPoint, bugify, squash. Point, bugify, squash! Quite efficient. Quite messy too... but again, worry not. No no, worry not, for afterwards, we don't have to clean up!", objectives = "Use your Personal Arcane Assistant to turn 12 Legash demons into insects and then squash them.", completion = "<Archmage Xylem appears to be doing some kind of dance as he turns to you.>\n\nDo not fret, and better yet, do not forget, to do not let the bug juice set or you will regret... well, you'll regret the smell of your boots really! It won't smell good today and it won't smell good even more tomorrow!" }
WordHunterWoW_QuestEN[14227] = { title = "Putting Their Heads Together", description = "So it's true....\n\nThe parchment you discovered in Thunder Axe Fortress details a powerful summoning ritual. One stronger than the Burning Blade have ever been known to possess.\n\nClearly, this rite must be stopped at all costs!\n\nPerhaps if this demon were summoned forth prematurely the crisis could be averted.", objectives = "Collect 100 Bleached Skulls from Thunder Axe Fortress, place them at the Burning Blade Summoning Circle, then kill Nazargen.", completion = "You diverted what would have been a serious crisis, <class>.\n\nIf that summoning was delayed just a bit longer, the demon would have become far too powerful for our small forces here to contend with.\n\nPlease accept this gift as our thanks for your service." }
WordHunterWoW_QuestEN[14230] = { title = "Manual Labor", description = "The local demons seem to get quite a kick out of stealing all of our arcane manuals. I highly doubt most of them can even read, so they're probably doing it just to spite us.\n\nI could care less about most of the books they've taken, but they took an Abjurer's Manual that I'm going to need if there's any hope of keeping apprentices like you alive amidst Xylem's \"trials.\" Find the demons at the Lagash Encampment to the southeast and retrieve the Abjurer's Manual.\n\nThat's all. Scoot.", objectives = "Retrieve the Abjurer's Manual from the Lagash Encampment.", progress = "And here you are... back... talking to me again. I assume this means that you have my book?", completion = "Peachy. Back to work then.\n\nThanks, snookums." }
WordHunterWoW_QuestEN[14231] = { title = "Useless quest record", description = "", objectives = "" }
WordHunterWoW_QuestEN[14232] = { title = "Ears Are Burning", description = "Sorrem has made no secret of his disdain for the Burning Blade at Thunder Axe Fortress.\n\nSurely, proof of their demise would be of value to him.", objectives = "You are to bring 25 Burning Blade Ears to Sorrem at Furien's Post.", progress = "What have you there, <class>?", completion = "Ears of the Burning Blade?\n\n<Sorrem smiles.>\n\nWell done, <class>. This is just a shadow of what will soon become of that vile cult!" }
WordHunterWoW_QuestEN[14233] = { title = "Orcs Can Write?", description = "Looking through the dead orc's belongings, you find a field journal. Though it is heavily water damaged, the writing is still legible, if barely.\n\nFlipping through the pages, an interesting story unfolds. Good thing you decided to study Orcish.\n\nLike the Trade Prince's yacht, the orcs were fired upon by Alliance warships. You do remember an orc warship that you passed right before the Alliance opened fire. Maybe they were firing on the orcs instead of your ship?\n\nStupid orcs! They got you sunk!", objectives = "Take the Field Journal to Sassy Hardwrench at Shipwreck Shore on the Lost Isles.", progress = "<name>, find anything interesting in the cavern?", completion = "Orcs?! They were sunk and stranded too?  And now the Alliance are on the island? Do you think they're going to kill us?\n\n<Sassy looks thoughtful.>\n\nI think it's time for a little sitdown with these orcs." }
WordHunterWoW_QuestEN[14234] = { title = "The Enemy of My Enemy", description = "I hate to ask you to do this, but I guess it's why they pay you the big bucks. Can you deliver that dead orc's field journal to whoever is in charge up at their camp?\n\nBased on the writing in the book, they should be located at the top of the island, up the incline past the Kaja'mite cavern to the southeast.\n\nGood luck, {name}. I always liked you.", objectives = "Deliver the Field Journal to Aggra at the Horde Base Camp on the Lost Isles.", progress = "<The orc narrows her eyes at you.>\n\nYou must have been on the <race> slave ship that was sunk. What's that you have in your hand?", completion = "<The orc makes a move to grab the field journal from you, but then stops herself, exhaling deeply.>\n\nI apologize. It has been a very rough couple of days for all of us.\n\nI am Aggra. All of us here are what remains of the crew of the Draka's Fury.\n\nPerhaps we can work together. We have a common enemy in the Alliance. Their SI:7 assassins are all over this island and they're not going to stop until we're all dead." }
WordHunterWoW_QuestEN[14235] = { title = "The Vicious Vale", description = "Our hunter, Kilag Gorefang, and a few scouts, traveled into the vale down the path to the west. They're ...searching for... 'precious cargo'... that we were guarding when the filthy Alliance sunk our ship.\n\nThe way is blocked by deadly plants and they have not been able to break through.\n\n{name}, prove your worth as a goblin and a {class}. Journey into the Vicious Vale to find Kilag.", objectives = "Find Kilag Gorefang in the Vicious Vale on the Lost Isles.", completion = "<race>, can you fight?\n\nFor your sake, I hope so. Otherwise, there may be no breaking through this hell of killer plants." }
WordHunterWoW_QuestEN[14236] = { title = "Weed Whacker", description = "<Kilag barely has time to acknowledge you between rifle shots, but his eye does linger a moment on your Goblin All-In-1-der Belt appreciatively.>\n\nNow is the time for creative solutions. Pull something out of that belt and get to work!\n\n<Thinking about the situation for a moment, an idea comes to your mind and it's just crazy enough to work!>", objectives = "Use the Weed Whacker within your Goblin All-In-1der Belt to mow down 100 of the plants within the Vicious Vale.", progress = "There are still too many for us to get through.\n\nHave faith in yourself, <name>. Let your true warrior heart shine through.", completion = "I saw it with my own eyes, and still I do not believe it!\n\nYou have our thanks and the debt of our lives, little <race>. I hope that soon we can repay you the honor.\n\nMay I ask a small favor of you while my scouts and I move on?" }
WordHunterWoW_QuestEN[14237] = { title = "Forward Movement", description = "Kilag should be in position by now. It is time for you to move forward to the Wild Overlook. The rest of us will pack up here and move out soon.\n\nJust follow the path northwest through the Vicious Vale. Not so vicious any longer thanks to you, eh?\n\nKilag and his scouts will be keeping themselves hidden just off the path, but the SI:7 assassins are sure to spot them soon, so hurry!", objectives = "Find Kilag Gorefang and his scouts at the Wild Overlook on the Lost Isles.", completion = "Throm-Ka, <name>. We have a problem." }
WordHunterWoW_QuestEN[14238] = { title = "Infrared = Infradead", description = "Keep your voice down. The glen north and west of here is crawling with Alliance assassins.\n\nUnfortunately, we haven't been able to spot them. The cowards! They hide and won't fight face-to-face.\n\nYou goblins are known for your wondrous goggles. Surely you have a pair that will allow you to see them?\n\nI need you to team up with one of my scouts and kill any of the SI:7 assassins that you spot.", objectives = "Kill 10 SI:7 Assassins.\n\nIf something happens to your Orc Scout, return to Kilag to see if he has another for you to team up with.", progress = "You got them all?", completion = "Well done, <name>, well done. We'll make an orc of you yet!\n\nTime to move on. We'd better hurry." }
WordHunterWoW_QuestEN[14239] = { title = "Don't Go Into the Light!", description = "", objectives = "It's up to you now. Are you going to come back to life and be the hero that your fellow survivors need you to be, or are you going to rest for eternity here?\n\nOnly you can decide.\n\nDon't go into the Light, <name>!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14240] = { title = "To the Cliffs", description = "I sent Scout Brax forward along the road to the cliffs overlooking the beach to the west.\n\nI am going to put you onto Bastia. Travel down the path and let Brax know that we are going to take a different route.\n\nWe'll see you at the attack on the Alliance beachhead!", objectives = "Speak with Scout Brax on the path down the cliffs north of the Savage Glen on the Lost Isles.", completion = "Hello, little <race>. Bastia is fast, no?\n\nWe have something very important that needs doing. Can you help us?" }
WordHunterWoW_QuestEN[14241] = { title = "Get to the Gyrochoppa!", description = "The Alliance have stolen something of vital importance to the Horde. It is being held out on their ships.\n\nAt the other end of the beach is a gyrochoppa. Our battlesworn will cover your approach.\n\nGo retrieve the keys to the flying machine from one of their operatives.\n\nFly out to their flagship, the Vengeance Wake, and retrieve our precious cargo!", objectives = "Retrieve the Gyrochoppa Keys.", progress = "Hmm, looks like overly-complicated gnomish engineering with lots of unnecessary instrumentation and safety precautions.", completion = "Hmm, where the heck is the ignition?\n\nIt'll be a wonder if it flies without doing something weird, like turning into a chicken or shrinking down to the size of an ant.\n\nHey look, someone left their loose change in the ashtray! What else is in there?" }
WordHunterWoW_QuestEN[14242] = { title = "Precious Cargo", description = "They said that their \"precious cargo\", whatever that is, is being held out on the Alliance ship, the Vengeance Wake.\n\nThere's only one thing to do... fly this thing out there and retrieve it!", objectives = "Locate the precious cargo below deck on the Alliance ship, Vengeance Wake, off the shore of the Lost Isles.", progress = "Perhaps you can help me to get out of this arcane cage?", completion = "If not for you, I would surely be on my way back to Stormwind to be paraded as a trophy and a slave.\n\nThe Alliance dogs found me unconscious on the shore and put me in this magical cage. It was keeping me from connecting with the elements.\n\nNo longer!" }
WordHunterWoW_QuestEN[14243] = { title = "Warchief's Revenge", description = "Brothers of Earth and Fire, hear me! Sisters of the Water and Air, heed my call!\n\nAzeroth stands on the brink, its existence near an end! Lend me your power as in times past with my ancient ancestors. Allow me to channel your will through this child of Kezan.\n\nLet us put an end to those who would keep us from healing the world!", objectives = "Use the powers of the Cyclone of the Elements to slay 50 Alliance Sailors.\n\nOnce this is done, you will be flown to the Wild Overlook.", completion = "You have done what few others could have, <name>. Our world owes you a debt larger than you can possibly understand." }
WordHunterWoW_QuestEN[14244] = { title = "Up, Up & Away!", description = "While you were rescuing the Warchief and saving us all from the Alliance, Foreman Dampwick built this rocket sling to shoot us over the shark-infested strait to the bigger island.\n\nLuckily for us, the foreman managed to salvage a Town-In-A-Box from the shipwreck. Once you get it set up, we'll have a town of our own. I can't wait to sleep in a bed again!\n\nDampwick's down there at the Landing Site, waiting for you. Why don't you take the next rocket over?", objectives = "Survive the Rocket Sling shot across the Dire Strait.", completion = "<name>, I sure am glad you survived the trip... not everyone did!" }
WordHunterWoW_QuestEN[14245] = { title = "It's a Town-In-A-Box", description = "The trade prince had an entire town-in-a-box in the ship's hold! I managed to recover it while you were out saving all of our skins.\n\nDo you want to do the honors? All you have to do is climb to the top of that huge pile of explosives and push the plunger, and whamo kablamo, instant town!", objectives = "Climb to the top of the mountain of explosives and use the Town-In-A-Box Plunger.", completion = "<cough, cough!>\n\nHey! Where's the dock?! Someone stole the dock and the oil refinery from our town-in-a-box!\n\nWho would do such a thing?\n\nWhere's the Trade Prince?" }
WordHunterWoW_QuestEN[14246] = { title = "Early Adoption", description = "As the region becomes more lush, the creatures of the desert are being forced into increasingly confined spaces.\n\nA particularly distressing result is the impending extinction of the local swoops. Predators feast on the birds and their eggs when they take nest.\n\nI have acquired some swoop eggs from Tanaris and coated them with an irresistible pheromone. Place one in each nest you find, then protect it until a swoop comes to carry it off.\n\nYou will be doing a service to the balance of this land.", objectives = "Place 3 Swoop Eggs in Swoop Nests and protect them until they are collected.", completion = "You have done well, <class>.\n\nThis land is in your debt." }
WordHunterWoW_QuestEN[14247] = { title = "Stubborn Lands", description = "By authority of the Cenarion Circle, I am charged with turning these harsh lands into lush prairie.\n\nThe lands south of here welcomed the growth, but something here is fighting back - resisting the replenishment.\n\nPerhaps your eyes can succeed where mine have failed.\n\nPlease, {race}. Scour these lands and discover the source of the desert's stubbornness. ", objectives = "Thunk at Thunk's Abode wants you to find the Unnatural Outcropping.", completion = "You look around, scanning the horizon for what might be responsible for placing this stone here...." }
WordHunterWoW_QuestEN[14248] = { title = "Help Wanted", description = "Great news! Foreman Dampwick has uncovered a cave full of kaja'mite on the island! What are the odds?\n\nOf course, there's a downside. He took some of the survivors with him to help mine the ore, but none of them have made it out.\n\nCrazy as it sounds, the foreman said that there are monkeys in the cave... with mining picks! They're mining the kaja'mite! How is that even possible?\n\nCan you head southeast to the cavern? The foreman is standing just outside the entrance.", objectives = "Speak with Foreman Dampwick outside of the Kaja'mite Cavern on the Lost Isles.", completion = "Boss! Er, well, I guess you're not the boss anymore, but still, good to see you!\n\nCan you believe it? We've got a cave full of intelligent killer monkeys mining Kaja'mite!" }
WordHunterWoW_QuestEN[14249] = { title = "Shear Will", description = "I'd be amazing! At archmagery. Amazing! He won't even talk to me because I don't have a stupid robe and hat. Pffft.\n\nThe most amazing archmage this land has ever seen can't just have any robe and hat. I need to show him that I'm something special, and I know just how to do it.\n\nGo out there and kill some of those hippogryph things. Bring me back a TON of feathers.\n\nYou heard me! A whole bunch of feathers! Go go, I'll have the robe ready for them by the time you get back.", objectives = "Obtain 80 Pristine Thunderhead Feathers from the Hippogryphs near the Ruins of Nordressa.", progress = "My robes looking pretty good. Did you bring those feathers?", completion = "Ha ha! Perfect! Let me toss this together really fast. The Archmage is sure to be taken in by my style!" }
WordHunterWoW_QuestEN[14250] = { title = "Renewable Resource", description = "We're going to need some more animate basalt. There's only one reliable source for that in the area, a mountain giant named Balboa. We can't be killing the mountain giant if we want to keep stocked in the stuff long term, so we've just been chipping off pieces at a time.\n\nYou'll be able to see his path northeast and east of here. Find him, place the charge ahead on the path, and then hide until it goes off. Once he's cleared the area, you should be able to retrieve the basalt and bring it back to me.", objectives = "Use the Arcane Charge to retrieve 5 Animate Basalt from Balboa near the Ruins of Nordressa.", progress = "I heard a few explosions. I can hardly tell if one of them was yours or not... these goblins can be quite a nuisance.", completion = "Good work. This should keep us for another few hours before we have to go back for more.\n\nHe doesn't seem to be the brightest of giants. I expect we'll be able to keep doing this for a while before he catches on." }
WordHunterWoW_QuestEN[14251] = { title = "New Beginnings", description = "There's never been danger of centaur attack this far north before. Someone put 'em up to it, I just know it!\n\nRegardless, I'm wiped out. I had everything invested in this haul.\n\nFortunately, there's one thing no centaur can take from me and that's goblin ingenuity! I'll start from scratch and build an empire!\n\n<Bizby spots a scorpion in the distance.>\n\nThere's always a market for poison. Whatdya say, friend?\n", objectives = "Collect 15 Scorpion Stingers.", progress = "Let's have a look at those scorpion tails, friend.", completion = "This is how I got my start, you know.\n\nSlingin' poison to the rogues in Orgrimmar. Ahh, those were the days...." }
WordHunterWoW_QuestEN[14252] = { title = "Good Gold For Bad Tail", description = "I need a crateload of tail, {class}! And not just any kind of tail. The tail I'm after needs to be old - ancient even. The more decrepit the better.\n\nThe scales of a basilisk's tail are unique in that they harden with age without becoming brittle. The hardened scales are ideal for the production of certain armors.\n\nIt's been many years since I've been reduced to peddling lizard scales, but who knows, maybe it'll build even more character in me! If that's even possible....", objectives = "Find 15 Aged Basilisk Tails.", progress = "How's the search for tail coming, <name>?", completion = "That'll do, <class>.\n\nA few more friends like you and I'll be back on my feet in no time!" }
WordHunterWoW_QuestEN[14253] = { title = "Fletch Me Some Plumage!", description = "Say, {class}, while you're out there exploring the desert wastes, do me a favor?\n\nKeep an eye out for Dread Swoops. Their oily feathers make for the best fletching, and to the right buyer they can fetch a handsome price.\n\nLucky for you, I know all of the right buyers!", objectives = "Collect 25 Dread Swoop Feathers.", progress = "How is the search for swoops coming?", completion = "Well now, that's quite a load of feathers, <class>.\n\nThey'll make for a good pillow 'til I get 'em to market!" }
WordHunterWoW_QuestEN[14254] = { title = "Heavy Metal", description = "You have a strong feeling that this stone is somehow responsible for the region's refusal to accept the encroaching regrowth.\n\nLooking off to the west, you notice a trail of smoldering debris that appears to be related to this mystery.\n\nYou surmise that clearing the debris might assist Thunk's efforts here.\n\nAnd who knows what this stuff might be good for?", objectives = "You are to collect 7 pieces of Element 116 and bring them to Bizby at Bizby's Caravan.", progress = "Whatcha got there, <class>?", completion = "What's this?\n\n<Bizby examines the ore.>\n\nWahoo! I know someone who will be most interested in acquiring these samples.\n\nMost generous in payment for them as well, I'll wager.\n\nHere, <class>. Take this as your finder's fee." }
WordHunterWoW_QuestEN[14255] = { title = "Ethel Rethor", description = "We have plenty of enemies in this region without raising the ire of the Cenarion Circle.\n\nWhen we established our post here, we were asked to keep a watch over one of their researchers.\n\nKorrah was last seen at the tower to the west. Do be a dear and pay her a visit. It's been some time since we've bothered to check on her.", objectives = "Cerelia at Furien's Post wants you to speak to Korrah at Ethel Rethor.", completion = "It is good that you have come.\n\nThere is grave danger looming here." }
WordHunterWoW_QuestEN[14256] = { title = "The Emerging Threat", description = "I am all that remains of my company, sent to monitor the many changes on this coast of Desolace.\n\nI have reported of the dramatic increase of naga here, but to no effect.\n\nMy peers are focused on other crises, so I must ask you, a stranger, to assist me in my research.\n\nFirst, though, allow me to show you the threat we face.", objectives = "Korrah wants you to speak to her when you are ready to be shown the Naga threat.", completion = "So now you see. These are not a simple band of displaced naga, but a well organized army, capable of great devastation.\n\nDo you agree to assist me in my investigation?" }
WordHunterWoW_QuestEN[14257] = { title = "Slitherblade Slaughter", description = "Time and again, the naga have proven to be enemies to the balance of nature. I have no qualms with the spilling of their blood.\n\nYour best efforts though, would barely put a dent in their forces here. Where one falls, two seem to rise in their place.\n\nI have a plan, {class}. Your objective is not merely to take the lives of the enemy, but to gather components necessary for the next stage of our investigation....", objectives = "Collect 10 Slitherblade Bones from Slitherblade Naga, 30 Slitherblade Scales from Slitherblade Sorceresses, and 4 Slitherblade Fins from Slitherblade Warriors.", progress = "Have you collected the components I require?", completion = "You have done well, <class>. But I'm afraid that your work here is just beginning." }
WordHunterWoW_QuestEN[14258] = { title = "Mortar the Point", description = "The Naga started making a move on the peninsula here after we finished building this rocketway terminal. But there's no problem in this world that can't be solved with gratuitous firepower! That's what my daddy used to say. Before the accident.\n\nI'm running short on supplies, though. Do me a favor and collect the mortar shells I left stockpiled in the Secret Lab just west of here. Keep me supplied and I'll let you call in the artillery strikes! ", objectives = "Collect 5 Goblin Mortar Shells from the Secret Lab complex in Azshara.", progress = "I hope you have more ammo for me. I've got nothing to shoot off over here but my mouth!", completion = "Sweet! Beautiful! Brilliant! Who loves you?\n\nWith my mortars re-supplied, I can help you as you assault the Naga east of here. Use these markers to call in an artillery strike anywhere on the cliffs, and I'll splatter the whole area with fiery hurt. Oh delicious, merciless, random destruction! I hope you're well-armored..." }
WordHunterWoW_QuestEN[14259] = { title = "More Mortars, More!", description = "Thanks for helping me restock my supplies, <name>.\n\nI'll tell you what, bring me more mortars from the lab, and I'll keep supplying you with artillery signals. With me on the trigger and you in the field, we'll blast these cliffs until they go crashing into the sea!You will receive:", objectives = "Collect 5 Goblin Mortar Shells from the Secret Lab complex in Azshara." }
WordHunterWoW_QuestEN[14260] = { title = "Going Deep", description = "I have fashioned a charm that will allow you to infiltrate the naga, giving you the appearance of one of their own.\n\nWith this disguise, you will be able to speak and understand their language. They will be unable to discern your true identity.\n\nBut beware! The sharks and other sea creatures here will expose you for all to see. Avoid them at all costs.\n\nNow go. Speak to the Priestess of Azshara and do what you must to learn of their purposes here.", objectives = "Use the Slitherblade Charm.", completion = "Don't just stand around, when there is so much to be done!\n\nMust I instruct everyone on each detail?" }
WordHunterWoW_QuestEN[14261] = { title = "Ice Cold", description = "I've got the perfect solution to our drake problem. My very own Cryomatic 16.\n\nI originally developed it to freeze my workers during transport and between shifts so that I wouldn't have to feed and entertain them, but there were... complications. It should be perfect for dropping these drakes out of the sky though!", objectives = "Use the Cryomatic 16 to freeze and kill 8 Sable Drakes.", completion = "What? So you didn't bring any of the drake pieces back? Disappointing.\n\nI knew I should have made you sign a contract before I sent you out..." }
WordHunterWoW_QuestEN[14262] = { title = "To Gut a Fish", description = "It tries my patience, defending against creatures who can disappear into the sea at will and emerge where they please. But I will not back down until their like has been wiped from Azshara.\n\nSpitelash Naga have slithered up the cliff walls and are besieging this post from the east. Destroy them, {name}. Gut them head to tail, so that they may know the full fury of my Horde.", objectives = "Slay 6 Spitelash Stormfuries and 6 Spitelash Seacallers.", completion = "<Torg scans the horizon.> And still they come! They are like a plague, <name>. But with strength like yours, we will crush them. Someday." }
WordHunterWoW_QuestEN[14263] = { title = "Waste of Thyme", description = "Living Ire Thyme. I must have more! Be quick about it, will you?", objectives = "Collect 8 bundles of Living Ire Thyme near the Ruins of Nordressa.", progress = "Do you have that thyme for me?", completion = "Perfect. It's quite interesting how useful the most random things end up being to incantations of this sort.\n\nSo much more to learn!" }
WordHunterWoW_QuestEN[14264] = { title = "Wetter Than Wet", description = "Neptulon's minions have arrived here and are doing all they can to thwart us. Clearly, they've discovered our motives.\n\nThis only confirms my suspicion that what we seek is indeed somewhere in these ruins!\n\nThese water elementals are no match for our forces! Take this trident and use it to destroy the worthless servants of the Tidehunter.\n\nWhen we find what we seek here, Neptulon himself shall fear for his life!", objectives = "Defeat 5 Servants of Neptulon. (You must be in naga form when you defeat them.)\n\nIf you lose your Slitherblade Trident, speak to Valishj.\n\nIf you lose your Slitherblade Charm, speak with Korrah at Ethel Rethor.", progress = "Tell me, minnow. Have you done as I asked?", completion = "The enemy's ranks are thinning, little minnow.\n\nPerhaps you are worthy of assisting in our search...." }
WordHunterWoW_QuestEN[14265] = { title = "Your Instructor", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A fellow by the name of Cleese said you were one of his students and wanted to make sure you were all right.", objectives = "Speak to Sergeant Cleese in the Military District.", completion = "<name>!  Where have you been?\n\nAnyway... it's great to see you in one piece." }
WordHunterWoW_QuestEN[14266] = { title = "Charge", description = "You're alive, <name>!  That must mean I did something right.\n\nIt's a shame our lessons were cut off a little short.  But, as you go and learn on your own, you'll start to discover new techniques.\n\nGo get some more experience, learn something new, and then try it out against the bloodfang worgen to our west.", objectives = "Reach level 3 to learn Charge. Practice using Charge against a Bloodfang Worgen.", completion = "Excellent work!" }
WordHunterWoW_QuestEN[14267] = { title = "Investigating the Sea Shrine", description = "The Naga invaders have set up a series of shrines along the cliffs. I don't know their purpose, {name}, but I believe they're strengthening our foes. I need someone to get in there and root out this threat.\n\nOne nearby shrine is lightly defended: Cross the first bridge east of here and then head north towards the bay. You'll find it on a small outcropping. Investigate that shrine and come back with some info I can use.", objectives = "Investigate the Naga shrine for Torg Twocrush.", completion = "The stone in the center of this shrine emits a faint glow and roars with the power of the angry sea." }
WordHunterWoW_QuestEN[14268] = { title = "Deep Impact", description = "Queen Azshara seeks entrance into the plane of water, for what I do not know.\n\nShe believes that the ancients held the keys to finding its location.\n\nI have personally been charged with scouring the ruins in this region, and none shall rest until we discover the secrets we seek!\n\nSubmerged just to the north are a concentration of ruins. Use this staff to search through the rubble.\n\nReturn to me only when you have located that which we seek!", objectives = "Priestess Valishj wants you to find the Ancient Engravings of Neptulon.", progress = "Could it be....?", completion = "Yes! You've found it!\n\nNeptulon's engravings... there can be no mistake!" }
WordHunterWoW_QuestEN[14269] = { title = "Someone's Looking for You", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A woman named Loren... she seemed a little disappointed when I told her you were all right.\n\nI think she mentioned she owes you money.", objectives = "Speak to Loren the Fence in the Military District.", completion = "Oh, hey!  There you are!" }
WordHunterWoW_QuestEN[14270] = { title = "The Keystone Shard", description = "The air around this strange stone crackles with energy. The stone itself is smooth and icy cold. It pulses periodically as you run your hands over it, like the crashing of surf.\n\nA wedge-shaped piece appears to be missing from the top surface of the artifact. This 'keystone shard' is likely the key to unlocking the secrets of the stone. Search the grounds near the temple and locate the keystone shard.", objectives = "Find the Keystone Shard nearby.", progress = "The Naga power stone pulses with an expectant hum.", completion = "The keystone shard slides into place and previously invisible runes suddenly erupt onto the surface of the stone, shimmering in blue and violet hues. Your knees buckle as powerful arcane currents suddenly race into your body..." }
WordHunterWoW_QuestEN[14271] = { title = "Report to Twocrush", description = "A magical barrier pulses around you, chilling your bones. You feel secure behind this enchanted wall.\n\nTorg Twocrush will want to know what you've discovered here!", objectives = "Return to Torg Twocrush at the Southern Rocketway Terminus in Azshara with news of your discovery.", completion = "An energy barrier, you say? This explains a great deal! I've seen firsthand how Naga leaders have been able to turn aside the blades of some of my best warriors.\n\nNow we know the source of their power, <name>. Let's finish this!" }
WordHunterWoW_QuestEN[14272] = { title = "Eviscerate", description = "Good to see you alive!\n\nNo, of course I don't have that gold I owe you.  Now's not really the time to bring that up is it?\n\nListen, maybe I can show you the ropes, save your skin with all the carnage going on. \n\nAs you learn how to fight, you'll start to learn new things. Go get some more experience, and then when you figure out something new, try it on the Bloodfang Worgen. I'll be watching", objectives = "Reach Level 3 to Learn Eviscerate, then practice using Eviscerate against a Bloodfang Worgen.", completion = "Don't get ahead of yourself now.  Just remember who taught you everything you know.\n\nAnd now let's see if we can get out of this city with our skins attached." }
WordHunterWoW_QuestEN[14273] = { title = "Shady Associates", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A strange fellow named Vitus... he was really giving me the creeps.\n\nHe kept talking about some \"forbidden knowledge\" he'd uncovered.", objectives = "Speak to Vitus Darkwalker in the Military District.", completion = "A darkness has descended over our lands.  And not our kind of darkness, if you know what I mean." }
WordHunterWoW_QuestEN[14274] = { title = "Corruption", description = "It is true then!  You live!\n\nI never got a chance to share my greatest discovery with you.  After I began my training, and began to become accomplished, I heard the voice Balcephoth of the felshadows in my head... he taught me the forbidden secrets of...\n\nCorruption!\n\nGo now, gain some more experience, maybe you'll learn a new spell, too. You can go use it against the Bloodfang Worgen to our west.", objectives = "Reach level 3 to learn Corruption. Practice casting it on a Bloodfang Worgen.", completion = "Yes!  You can feel the power, can't you?" }
WordHunterWoW_QuestEN[14275] = { title = "Someone's Keeping Track of You", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A man named Blake.  Said something about a plan to escape into the woods.", objectives = "Speak to Huntsman Blake in the Military District.", completion = "<name>!  I knew you had to be around here." }
WordHunterWoW_QuestEN[14276] = { title = "Steady Shot", description = "So I've got good news and bad news.\n\nThe bad news is that there are more worgen in the woods than in here... so we really have no safe place to go to.\n\nThe good news is that you're starting to get the hang of this. As you get more experience, you'll start to learn how to do new things.\n\nOnce you learn your first new ability, try your hand at it against the bloodfang worgen to our west.", objectives = "Reach level 3 to learn Steady Shot. Practice using Steady Shot 2 times against a Bloodfang Worgen.", completion = "Excellent work, <name>.  These <race> will regret ever setting foot in our lands." }
WordHunterWoW_QuestEN[14277] = { title = "Arcane Inquiries", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  It was a mage named Myriam.  She mentioned something about you being \"ready.\"", objectives = "Speak to Myriam Spellwaker in the Military District.", completion = "A disciple of the arcane always finds a way forward.  I'm glad to see you, <name>." }
WordHunterWoW_QuestEN[14278] = { title = "Seek the Sister", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A member of the clergy, Sister Almyra, said that you were in great peril and needed the Light's protection.\n\nYou should go talk to her.  She seemed very concerned.", objectives = "Speak to Sister Almyra in the Military District.", completion = "The Light is with you, <name>.  It's still quite a relief to see you." }
WordHunterWoW_QuestEN[14279] = { title = "Learning the Word", description = "You have much to learn, <name>.  And I've much to teach you.\n\nThese are perilous times, however, and I fear that you may need to learn much on your own\n\nHave no fear, <brother/sister>.  The Light will guide us through this.\n\nGo, get more experience, and learn a new skill. Use it against the bloodfang worgen nearby.", objectives = "Reach level 3 to learn Shadow Word: Pain. Use it 2 times on a bloodfang worgen.", completion = "You are blessed, <name>.  The Light shines upon you, even in these dark times." }
WordHunterWoW_QuestEN[14280] = { title = "The Winds Know Your Name... Apparently", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  It was that harvest-witch, Celestine; she said the winds spoke your name.\n\nYou'd best hurry, {name}.  We're going to need you to get back to the worgen-smashing once you're done conversing with nature.", objectives = "Speak to Celestine of the Harvest in the Military District.", completion = "We have been blessed today!  You are alive and well!" }
WordHunterWoW_QuestEN[14281] = { title = "Frost Nova", description = "The path ahead is difficult, <name>.  We must devote the entirety of our mental power to the task at hand.\n\nAs you begin to grow in power, new pathways to the arcane will begin to materialize in your mind. You'll begin to develop spells you did not know before.\n\nGo, get more experience, and then use what you learn against the Bloodfang Worgen.", objectives = "Reach level 3 to learn Frost Nova. Use it against a Bloodfang Worgen.", completion = "You've learned with such speed and ease.  Soon you'll be the one doing the teaching." }
WordHunterWoW_QuestEN[14282] = { title = "Mystery Solved", description = "Your efforts have paid off. The great risks you have taken have proven worthwhile.\n\nYou have discovered the object of the nagas' desire and their reason for overrunning the coast of Desolace.\n\nAs for the engravings you've discovered, your duty is clear...", objectives = "You are to bring the Ancient Engravings of Neptulon to Cenarion Researcher Korrah.", progress = "What have you learned, <class>?", completion = "The vision was true!\n\nYou have singlehandedly succeeded where others have failed.\n\nThe Circle will have no choice but to pay attention to these findings." }
WordHunterWoW_QuestEN[14283] = { title = "Moonfire", description = "We were driven to the edge of extinction once before, <name>.  But we druids, keepers of the old ways, saved our people from famine.\n\nWhen we cut ourselves off from the outside world and our crops failed, it was our order who called upon the earth's blessings and restored the harvest.\n\nJust as our powers restored the crops, your growth in power will develop your connection to our ancient arts.\n\nGo, develop your powers, and use what you learn against the Bloodfang Worgen.", objectives = "Reach level 3 to learn Moonfire, then use it against a Bloodfang Worgen.", completion = "Not bad at all.  Perhaps there is still hope for the old ways." }
WordHunterWoW_QuestEN[14284] = { title = "A Revenant's Vengeance", description = "I am Hydronis, a servant of Neptulon the Tidehunter, Lord over all waters.\n\nAzshara and her sinister naga have arrayed themselves against my master, and seek a war with him. This is the first battle in what shall surely be a long struggle.\n\nI have fought bitterly, {race}, and have grown weary.\n\nIt seems that my actions here have attracted the attention of their priestess.\n\nAlone, I haven't the strength to overcome her. but perhaps together, we may prevail.", objectives = "Hydronis wants you to mount him and defeat Priestess Valishj.", completion = "The priestess is no more..." }
WordHunterWoW_QuestEN[14285] = { title = "Safety in Numbers", description = "There's only so much I can teach right now with all these worgen trying to dismember us.\n\nWe really should think about heading south with the other survivors.  We've been told that King Greymane is there.\n\nIf we stick together our chances of survival will increase... especially if you choose someone nutritious-looking to stand next to.", objectives = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy." }
WordHunterWoW_QuestEN[14286] = { title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", objectives = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy." }
WordHunterWoW_QuestEN[14287] = { title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", objectives = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy." }
WordHunterWoW_QuestEN[14288] = { title = "Safety in Numbers", description = "There's only so much I can teach right now with all these worgen trying to dismember us.\n\nWe really should think about heading south with the other survivors.  We've been told that King Greymane is there.\n\nIf we stick together our chances of survival will increase... especially if you choose someone nutritious-looking to stand next to.", objectives = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy." }
WordHunterWoW_QuestEN[14289] = { title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nThe others are going to need the aid of the Light in these troubling times.", objectives = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy." }
WordHunterWoW_QuestEN[14290] = { title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", objectives = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy." }
WordHunterWoW_QuestEN[14291] = { title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", objectives = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy." }
WordHunterWoW_QuestEN[14292] = { title = "The Enemy of Our Enemy", description = "You have done us a great service, {class}.\n\nWhile they remain an imposing force, your efforts have kept an important artifact from the naga.\n\nI shall write to my peers of your findings. Meanwhile, the water revenant on Ranazjar Isle has stood alone against a steady onslaught of naga.\n\nI would have you find him and determine if there is some way we can assist him.", objectives = "Cenarion Researcher Korrah wants you to speak with Lord Hydronis.", completion = "I have witnessed your actions here, <race>.\n\nYour presence here is both welcome and timely." }
WordHunterWoW_QuestEN[14293] = { title = "Save Krennan Aranas", description = "All these years after the war and Crowley was still hiding enough firepower in that cellar to level half of the district.\n\nIt might have to come to that, unfortunately.\n\nWe can't open fire just yet, there is a civilian trapped on the other side of the prison.\n\nNot just any civilian, either.  Krennan Aranas is one of the most brilliant alchemists this world has known.\n\nOne of his potions saved my daughter, Tess, from dying soon after being born.\n\nTake my horse and rescue him.  Krennan must live.", objectives = "Rescue Krennan Aranas.", completion = "Well done, <name>.  We'll make sure Krennan makes it out of the city alive." }
WordHunterWoW_QuestEN[14294] = { title = "Time to Regroup", description = "We've done all we can here.  Let King Greymane know we've bought some time.\n\nI've a feeling it won't be long 'til the worgen are back in force.\n\nWe'll need to fall back to Greymane Court to the west, if that's the case.  It's the last place we can hold out without being trapped like fish in a barrel.", objectives = "Speak to King Genn Greymane at Greymane Court in Gilneas City.", completion = "We're left with very few choices, <name>.  What we do next will be a critical decision." }
WordHunterWoW_QuestEN[14295] = { title = "Sisters of the Sea", description = "Two Naga witches have been masterminding the assault on this outpost. They've repelled direct attacks from some of my best grunts, but you can finish the job where others have failed.\n\nSeek out and slay Lady Silisthra and Lady Vesthra at the eastern edge of the cliffs, around the ruins of the ancient night elven colossus. You will first need to destroy the powerstones that give them their strength. Do not disappoint me, {class}!", objectives = "Kill Lady Silisthra and Lady Vesthra by disabling their power stones.", completion = "Now THAT is how we used to handle serpents back in Durotar - we crushed them under our boots! You have done the Horde proud, <name>. As soon as my reinforcements arrive we'll mop up the rest of those vermin and claim this peninsula once and for all." }
WordHunterWoW_QuestEN[14296] = { title = "Watch Your Step", description = "This is somewhat simple and somewhat not simple. All the way up there are Energy Conduits. Rather like this one right here one might say! Indeed, I do say.\n\nNow for you. You must use my jump pads to ascend the pinnacle, and you must touch all of the conduits you see along the way. When you get to me at the top, you should be all juicy with energy, because really that's the only way to be.\n\nAnd be sure to keep moving or you're likely to be sent for quite a trip!", objectives = "Receive 6 Energized charges from the Energy Conduits as you ascend to the top of the Arcane Pinnacle.", progress = "No no no, you've got it all wrong. You were supposed to gather Energy from the Conduits before you came up here, remember?\n\nOne more time, with style!", completion = "It is in this moment that most of my apprentices wonder if there was a logical purpose to storing the energy for my portal in those conduits so that it has to be collected in such a fashion.\n\nOf course there's a purpose! I wish to study your behavior... your strategies, your mistakes, your frustrations, your triumphs. Those are the entire point of these trials.\n\nNow, more. More trials! Doesn't that sound exciting?! Of course it does." }
WordHunterWoW_QuestEN[14297] = { title = "Pro-liberation", description = "I knew these guys would be trouble as soon as we started building this tower. Scoffing our bribes. Stealing our workers.\n\nLabor isn't cheap with all the construction in Azshara. I need those men back!", objectives = "Use Ironwrought Keys from cultists and dragonkin to free 4 Goblin Workers in Sable Ridge.", progress = "There's no way I'm paying them for time in captivity. Greedy little punks.", completion = "Thanks there, pal. Here's your commission.\n\nIf you'll excuse me, I've gotta get these slackers back to work." }
WordHunterWoW_QuestEN[14298] = { title = "Kill Cultists/Dragonflight", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14299] = { title = "Xylem's Asylum", description = "Quite marvelous of you! A pleasure to observe. Much to study.\n\nOff you go now, retire to my tower. Joanna will get you situated. I shall open a portal for you.", objectives = "Take the portal to Archmage Xylem's tower and seek out Joanna inside.", completion = "Welcome! You seem to have survived the trials relatively unscathed. Good for you, love.\n\nYou look to have come with a purpose in mind as well. A question. Your thoughts are very loud, it's hard for me to not hear them.\n\nGo ahead then, hon. Ask away." }
WordHunterWoW_QuestEN[14300] = { title = "The Trial of Fire", description = "The Trial of Fire... oooh... sounds intimidating, doesn't it? No? Hm. Well I kind of thought so. Firsts are first, you touch the fire crystal and the portal to the trial opens.\n\nTo beat this trial, you have to hop around in the fire runes without getting hit by the fire. If you stay unflamed long enough, you win!\n\nThere are little signs to help you - fire hopping to its new rune, fizzles when a rune goes cold. You can figure that stuff out if you want. Or just guess! That's what most people do.", objectives = "Complete the Trial of Fire by standing in the fire runes without getting hit by flame for 10 consecutive bursts.", progress = "Um, no. You're not done. Get back in there and get toasty!", completion = "Woo! Good for you! That trial really put a fire under your bottom." }
WordHunterWoW_QuestEN[14301] = { title = "Return and Report", description = "It is done! Together we were able to bring down a dangerous adversary.\n\nNeptulon himself shall hear of your exploits here, {class}. Allow me to extend you his thanks...\n\nYou should leave now. This place will not remain safe for long. Soon, the naga will seek vengeance for their priestess.", objectives = "You are to return to Cenarion Researcher Korrah at Ethel Rethor.", completion = "Please accept this reward for your heroic accomplishments, <name>.\n\nYou have bought us precious time!" }
WordHunterWoW_QuestEN[14302] = { title = "Official Assessment", description = "You have accomplished much in your efforts against the naga, {name}. But I fear it is not nearly enough....\n\nThis is my official assessment of the naga presence.\n\nI'm confident that my peers in the wildlands will take the necessary action.\n\nBring this to Karnum at the glade in the center of the Cenarion Wildlands to the southeast. He will know what to do.\n\nThank you, {name}. And farewell.", objectives = "Cenarion Researcher Korrah wants you to take Korrah's Report to Karnum at Karnum's Glade.\n\nProvided item:", completion = "<Karnum opens and reads Korrah's Report.>\n\nThis is alarming news, indeeed, <race> - something we have no shortage of here.\n\nI shall call a council regarding the issue. You will be summoned if you are needed." }
WordHunterWoW_QuestEN[14303] = { title = "Back to Aggra", description = "Return to the Horde Base Camp and let Aggra know that we still live, {name}.\n\nTell her that I am moving on to the Wild Overlook and that we will all meet up on the northwest side of the island. I expect to see you there.\n\nWe will track down the Alliance and slay them to the last!", objectives = "Inform Aggra at the Horde Base Camp on the Lost Isles of all that has transpired.", completion = "<Aggra gives you the eye as if she doesn't quite believe what you are telling her.>\n\nI am not easily impressed, but if what you are telling me is true, then I have never before heard of such a thing.\n\nYou have my thanks, <name>." }
WordHunterWoW_QuestEN[14304] = { title = "Blood Theory", description = "The land is not all that has changed in Desolace. Here, the wildlife has responded to their new environment in strange and sometimes exciting ways.\n\nI am particularly interested in the Rejuvenated Thunder Lizards that roam just to the west.\n\nI need a sample of their blood.\n\nYou may begin helping me by using this jar of leeches on a few of them.\n\nOnce they've filled on the blood of those beasts, return them to me.", objectives = "Collect 10 Blood-filled Leeches.", progress = "Were you able to recover the samples I require?", completion = "This should be enough.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[14305] = { title = "A Time to Reap", description = "No one knows better than the Cenarion Circle that this lush oasis could dry up as quickly as it appeared.\n\nWe must take care not to interfere with the processes taking place here, but to support and preserve them,\n\nA new species of plant, very plentiful in the surrounding region, has appeared since the great change.\n\nCollect samples of these for me, that I might study them and learn what they have to teach us, ", objectives = "Collect 10 Aloe Thistles.", progress = "Have you collected the samples I require?", completion = "These are fine specimens, <race>.\n\nI shall commence my studies immediately." }
WordHunterWoW_QuestEN[14306] = { title = "Pulling Weeds", description = "With such an abrupt change to the ecology, it is to be expected that some of the flora and fauna don't react as well as we'd hope.\n\nThe uprooted lashers are a troublesome example of this. Roaming the fields to the east and south they are a detriment to the region and must be disposed of.\n\nWhile you're about, please deal with any of these pests that you find.", objectives = "Kill 7 Uprooted Lashers.", progress = "Have you helped to deal with the lasher problem, <class>?", completion = "On behalf of Desolace herself, I thank you, <race>.\n\nPlease accept our deepest gratitude." }
WordHunterWoW_QuestEN[14307] = { title = "Stubborn Winds", description = "The winds of change are blowing, {race}. Of that there can be no doubt.\n\nThere are many pressing issues vying for our attention and action. Chief among them is the spreading of our growing oasis.\n\nIts growth has surpassed our hopes as well as our understanding, yet now it faces opposition.\n\nTo the west, where the grass meets the sand, whirlwinds prevent its penetration into the desert.\n\nGo and eliminate this hostile obstacle to life!", objectives = "Destroy 5 Whirlwind Stormwalkers.", progress = "How goes our plight to the west?", completion = "You have done well, <class>.\n\nWe will doubtlessly call upon you for assistance with more significant matters in the future." }
WordHunterWoW_QuestEN[14308] = { title = "When Science Attacks", description = "Did you see the explosions on the way in? The Secret Lab is engulfed in flames! Again! If we don't stamp out those flames we're going to hit critical temperatacity and resonate into a meltdown cascade.\n\nHere, I'm entrusting you with a canister of experimental hypercooled pressurized liquigel: The most volatile fire retardant known to science! (Keep that canister away from open flame.) Put out the fires and hose down my interns, then contact me via the squawkbox in central control.", objectives = "Use the Fireliminator X-21 to extinguish 8 fires and to rescue 6 Research Interns from the inferno at the Secret Lab.\n\nSee Assistant Greely at the Southern Rocketway Terminus if you lose your Fireliminator.", progress = "<Greely's squeaky voice peels through a set of speakers.>\n\nRocketway to Secret Lab! Rocketway to Secret Lab! Come in, Secret Lab...", completion = "Nice work, <name>! Now, we need to decouple the reaction core matrix from the fuel sumps, or that whole place is gonna blow itself to Outland..." }
WordHunterWoW_QuestEN[14309] = { title = "Calming the Kodo", description = "As you have by now witnessed, the rapid changes to this region can have both positive and negative effects on the native creatures.\n\nTo the south and east of here, enraged kodo are a constant threat to anyone nearby.\n\nIt's time to put my theory to the test. I've used the rejuvenated thunder lizard's blood in the making of this concoction. I'm hoping it will soothe the kodo when they eat it.\n\nPlace it near an enraged kodo and make sure you do it from a safe distance!", objectives = "Use the Kodo Concoction near 5 Enraged Kodos.", completion = "Wonderful! Karnum will be so pleased!\n\nPlease, accept this as my thanks." }
WordHunterWoW_QuestEN[14310] = { title = "Segmentation Fault: Core Dumped", description = "Once we flush the central reactor, I need you to return the core to me. It's 100% refined azsharite crystal, which is both powerful and dangerous. And lovely. Oh precious azsharite, the shaper of worlds to come!\n\nThe giant lever to your left will dump the core and send it to me via the rail system. The core will be superheated, so you'll need to periodically douse it with the Fireliminator on the way here... don't let it reach critical temperature!", objectives = "Activate the Reactor Control Console and escort the Azsharite Core back to the Southern Rocketway Terminus. Use the Fireliminator X-21 on the Core if it starts to overheat.", progress = "Don't worry about the residual effects of all those burning chemicals in the lab. Hair grows back!", completion = "Whew, the sample is secure. And it's still steaming! Thank you, <name>.\n\nAzsharite is a complex mystery wrapped in a velvety enigma of danger. Grapplehammer insists that we learn more about this strange substance." }
WordHunterWoW_QuestEN[14311] = { title = "Taking Part", description = "What a glorious time we live in!\n\nThe former wastelands of Desolace are blooming, bursting with life. Imagine, {class}, if all of Azeroth's wastelands awoke in such a fashion! Perhaps someday...\n\nIt's true that there are weighty issues at hand here, but why not take a moment to appreciate the wondrous miracle we are witnessing?\n\nIn fact, why not take part in it? Here are some Cenarion Seeds. Use them at the more fertile spots of the wildlands.\n\nPerfect medicine for lifting a weary soul!", objectives = "Use the Cenarion Seeds next to 5 of the Fertile Mounds around the Cenarion Wildlands.", completion = "The rejuvenation is so invigorating! Don't you think?" }
WordHunterWoW_QuestEN[14312] = { title = "An Introduction Is In Order", description = "I have heard of your exploits here in Desolace, {name}. We are in your debt.\n\nI'm afraid I must involve you in yet another crisis, one more pressing than the rest.\n\nThe landscape is not all that has changed here of late. Old conflicts have made way for new, more dire ones. I should allow our guest to explain further....\n\nKhan Leh'prah is among the last of the Kolkar tribe that once possessed all of eastern Desolace. We found him near death on our borders. Listen to his words.", objectives = "Garren Darkwind at Karnum's Glade wants you to speak to Khan Leh'prah.", completion = "Be not afraid, <race>. I mean you no harm." }
WordHunterWoW_QuestEN[14313] = { title = "Among Humans Again", description = "So Krennan's potion did not kill you?  Well, I suppose that means the human inside of you is in control then.\n\nI guess I won't be shooting you after all.  At least not yet.\n\nGo speak to Krennan Aranas and give him the good news.  He's in charge of the house where we keep... your kind.\n\nJust remember, {name}.  I've got my eye on you.  You so much as try anything funny and you'll get a bullet between the eyes.", objectives = "Speak to Krennan Aranas in Duskhaven.", completion = "It worked!  By the Light, it worked!" }
WordHunterWoW_QuestEN[14314] = { title = "Breakout!", description = "It began with a dream that repeatedly warned me of the danger to come. I saw the demonic legions bearing down upon our kind, overrunning our lands.\n\nThe dream has become real. The Burning Blade and their demon masters have pushed the Magram out of their lands in the south. In turn, the Magram have defeated my people and taken over our homes.\n\nThe fight was ferocious. Only a handful of the Kolkar still live. I would ask that you visit what was once my land in the east, and free them from their prison.", objectives = "Kill the Magram Warden at the Magram Village.", completion = "I thank you, <race>.\n\nOur tribe may not have survived without your aid." }
WordHunterWoW_QuestEN[14315] = { title = "Liam's Stupor", description = "Go away!  You're just inside my head... You're not real.... you're dead!\n\nYou died in Gilneas City... the worgen... they got you...\n\nIt should've been me... it should've been me...\n\nAughhh... first the earth won't stop moving... and now I'm seeing things...  too much rye...\n\n<The prince seems out of it.  Perhaps you can find someone else to speak to.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Gwen Armstead in Duskhaven.Go away!  You're just inside my head... You're not real.... you're dead!\n\nYou died in Gilneas City... the worgen... they got you...\n\nIt should've been me... it should've been me...\n\nAughhh... first the earth won't stop moving... and now I'm seeing things... too much rye...\n\n<The prince seems out of it. Perhaps you can find someone else to speak to.>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14316] = { title = "Cenarion Property", description = "Since the demons have invaded their lands, the Magram have broken all ties with any outsiders.\n\nThey are untrusting and hostile and have taken to stealing from others instead of providing for themselves.\n\nMany of our needed supplies have gone missing of late and we suspect that the Magram are to blame.\n\nPlease, {name}, go to their lands in the east and search for our belongings.", objectives = "Collect 7 Cenarion Supply Crates from the Magram Lands.", progress = "Were you able to find our belongings, <name>?", completion = "As we suspected, the Magram have been stealing our supplies.\n\nWe shall guard them more closely." }
WordHunterWoW_QuestEN[14317] = { title = "Tremors", description = "<name>!  We thought we wouldn't see you again!\n\nListen -- we need your help. A huge earthquake hit us and the aftershocks haven't stopped.  Prince Liam isn't going to be of much use either.\n\nWe need to make sure our defenses are still holding up.  The Queen's Gate is the only thing standing between us and a mess of frothing-at-the-mouth rabid worgen from the Blackwald.\n\nJust follow the road east, out of town.  Let me know if the gate has held up.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gwen Armstead wants you to investigate the Queen's Gate." }
WordHunterWoW_QuestEN[14318] = { title = "Delicate Negotiations", description = "There is but one way to win the trust and loyalty of the Magram.\n\nIt must be beaten out of them.\n\nThey have suffered many losses in their war against my clan. They now possess an unfamiliar land, where they struggle just to feed themselves.\n\nNow is the time to strike.\n\nSpeak to me when you are ready, then ride in and plant my spear in the Fatherstone. If we can kill enough of them, their Khan will submit to our will.", objectives = "Khan Leh'prah wants you to place the Spear of the Kolkar Khan in the Fatherstone and defend it from the Magram until Khan Kammah appears.\n\nSpeak to Khan Leh'prah when you are ready to ride to the battle site.", progress = "What do you want?", completion = "Why is it that you meddle in centaur affairs, <race>?" }
WordHunterWoW_QuestEN[14319] = { title = "Further Treatment", description = "Listen, {name}.  I'm not going to beat around the bush.\n\nThere's a good chance the potion Krennan made for you wasn't a complete success.  Or perhaps you need more of it.\n\nEither way, he's probably better equipped to advise you than I am.  Go see him.", objectives = "Speak to Krennan Aranas in Duskhaven.Listen, <name>. I'm not going to beat around the bush.\n\nThere's a good chance the potion Krennan made for you wasn't a complete success. Or perhaps you need more of it.\n\nEither way, he's probably better equipped to advise you than I am. Go see him.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14320] = { title = "In Need of Ingredients", description = "Ah, yes.  The effects of the Curse cannot ever be fully cured as far as we know.\n\nWith treatment, however, your mind will remain yours... and not that of a wild animal.\n\nWe are fortunate that the treatment worked on you.  Normally, I can only treat recent infections.\n\nWe'll need to continue your medication if we're to have you reverse the Curse.\n\nI will need mandrake essence to brew another batch of my serum for you.  You will find a crate stashed beneath a shed southwest of town.", objectives = "Find the Crate of Mandrake Essence.", completion = "The crate has been smashed and the vials inside of it appear to have been broken." }
WordHunterWoW_QuestEN[14321] = { title = "Invasion", description = "<A long knife with a skull ornament on its hilt sticks out of the militiaman's ribs.  As you look around for clues, you spot a pair of savage-looking warships at the shore.>\n\n<Gilneas is being invaded.  Bring word back to Duskhaven's Mayor, Gwen Armstead.>", objectives = "Speak to Gwen Armstead in Duskhaven.", completion = "Forsaken!  Quick, <name>!  We must mount a defense." }
WordHunterWoW_QuestEN[14322] = { title = "Bad Science! Bad!", description = "I was trying to domesticate the indigenous hippogryphs here using a series of debilitating electrical shocks, when for some reason they went berserk! Now my test subjects are tearing up this place for no good reason! {class}, go slaughter my failed experiments before they find me.", objectives = "Kill 8 Static-Charged Hippogryphs.", completion = "So the world is safe for science again? Excellent! Next time I'll try heated needles or something." }
WordHunterWoW_QuestEN[14323] = { title = "Absorbent", description = "One other thing I need. Hot water.\n\nNot easy around here. Not hot springs, no friends to share. One good way though. Have this sponge... it's ultra absorbent! Use it to go soak Vile Splashes at the sandbar eastish.\n\nWith enough, go squeeze them out over near the tower to summon jumbo elemental. He has hot water.", objectives = "Collect 20 Simmering Water Droplets from the Vile Splashes east of the Ruins of Arkkoran.", progress = "The Azshari Sea Sponge undulates with living water.", completion = "You've collected all of the simmering water droplets that Ergll requested. Now it's just a matter of summoning the \"jumbo\" elemental." }
WordHunterWoW_QuestEN[14324] = { title = "Full of Hot Water", description = "Ergll indicated that you should be able to use the Engorged Azshara Sea Sponge to summon a \"jumbo\" elemental near the Tower of Eldara to the northeast.", objectives = "Obtain a Globe of Boiling Water from a Scalding Water Lord at the Tower of Eldara.", progress = "You're back!", completion = "Convenient, no? Who needs hot springs anyway. This is perfect." }
WordHunterWoW_QuestEN[14325] = { title = "Will Work For Food", description = "<Khan Kammah listens as you explain the demonic threat, and Khan Leh'prah's visions.>\n\nNo one need lecture us about the demons, {race}. It is they who drove our clan from our ancestral lands.\n\nIt is they who forced us to take over the Kolkar wastelands, where we struggle just to exist.\n\nThe war against the Kolkar took a heavy toll on my people. What few of us remain are weary and hungry.\n\nBring food for my people and then we shall discuss the demons.", objectives = "Collect 5 Basilisk Flanks.", progress = "Have you brought food for my clan, <race>?", completion = "Very good, <race>.\n\nThis will sustain us for now." }
WordHunterWoW_QuestEN[14326] = { title = "Meet Me Up Top", description = "I never thought that I would be a prisoner of the Alliance again. I cannot begin to express my gratitude to you... {name}, is it?\n\nI will meet you up top and from there we will deal with them.", objectives = "Make your way up top on the upper deck of the Vengeance Wake off the shore of the Lost Isles and speak with Thrall.", completion = "My mission is too critical to let these meddlers continue to dog us. It's up to you and I to put an end to this once and for all!" }
WordHunterWoW_QuestEN[14327] = { title = "My Word is My Bond", description = "It would seem that we have no choice.\n\nAs reluctant as I am to cooperate with the Kolkar, there is wisdom in the words of their Khan.\n\nYou may give him my word that we shall lend our spears to the battle.", objectives = "Khan Kammah wants you to speak to Khan Leh'prah.", completion = "You have done well, <class>.\n\nNow we must convince the Gelkis..." }
WordHunterWoW_QuestEN[14328] = { title = "Three Princes", description = "The Gelkis reside in southwest Desolace. They are just as stubborn as the Magram, and since they have not suffered war and relocation, they are considerably stronger.\n\nHumbling the Gelkis will require an extreme show of force.\n\nKhan Shodo and his three sons rule the clan. Shodo is aging, and suffers from old war wounds. He never leaves the depths of his cave. The strength of his rule lies in his sons.\n\nSlay them, and persuade the Khan to commit to our cause.", objectives = "Slay Rhoho, Sherik, and Jorreth.", completion = "My sons all slain... my clan in ruins....\n\nWere I in my youth, I would tear you limb from limb!\n\nGo now... kill me or leave me to mourn alone, <race>." }
WordHunterWoW_QuestEN[14329] = { title = "Not So Fast!", description = "<The Khan of the Gelkis clan stares at you with an empty gaze as you detail the demon threat and Leh'prah's visions.>\n\nIt matters not to me what becomes of this land now. I have failed my clan and my forefathers....\n\nThere is but one thing left in this world that might bring my old soul hope, and she's likely dead as well.\n\nMy precious daughter, Kherrah, was taken from me by the Maraudine clan. If you can bring her back to me alive, I shall consider your proposal.", objectives = "Khan Shodo wants you to kill 10 Maraudine Maulers in the Valley of Spears.\n\nYou are to search their corpses for clues to Kherrah's whereabouts.", completion = "As you slaughter their enemy, the Gelkis clan cannot help but to acknowledge your prowess." }
WordHunterWoW_QuestEN[14330] = { title = "Behind Closed Doors", description = "You've discovered the location of Khan Shodo's daughter, Kherrah. She is being held behind the doors to Maraudon!\n\nThe rescue attempt is certain to be risky, but if you seek the Gelkis clan's cooperation, you must free the Khan's daughter.", objectives = "You are to find Kherrah somewhere behind the doors to Maraudon.\n\nProvided item:", completion = "Is it safe for me to leave, <race>?" }
WordHunterWoW_QuestEN[14332] = { title = "Time For Change", description = "<Kherrah listens to you as you explain recent events.>\n\nI agree with the words of the Kolkar Khan. The time for ancient grudges is over. It is a shame that it has taken a demonic crisis to unite the tribes.\n\nI shall return to my father and convince him to join your cause. You have my word that he will comply.\n\nReturn to Khan Leh'prah and inform him that the Gelkis will be ready when called upon.", objectives = "Kherrah wants you to speak with Khan Leh'prah.", completion = "You have done well, <race>.\n\nAnd not a moment too soon...." }
WordHunterWoW_QuestEN[14333] = { title = "While You're Here", description = "The Maraudine have raided the Gelkis camps for many years, stealing anything they could get their hands on.\n\nOne of their favorite torments is to take these relics of power which the Gelkis hold sacred, and bring them here to be defiled.\n\nThe Gelkis clan would certainly be grateful if you were to find and destroy these defiled artifacts.", objectives = "You are to scour the Valley of Spears to find 6 Defiled Relics.", completion = "The destruction of those defiled relics will ease the minds of the Gelkis, and will strengthen their resolve.\n\nYou have done well." }
WordHunterWoW_QuestEN[14334] = { title = "Blubbergut", description = "Ahoy, mon!\n\nYou think you be able ta do something for da village here?\n\nMost whales we can handle fine, but there be a special whale out there that be too big for our spears.\n\nBlubbergut been gettin' bigger an' bigger - eatin' up the fish we use to live on!\n\nGet out there and find the thing, then make him pay for his gluttony!", objectives = "Mai'Lahii wants you to kill Blubbergut.", completion = "Oy, mon! Ya did it!\n\nWe soon be havin' fish to eat, thanks be to you." }
WordHunterWoW_QuestEN[14335] = { title = "Chipping In", description = "As you have no doubt noticed by now, the recent changes to the land have had many side-effects. Some of these are beneficial, while others pose serious problems.\n\nJust south of the village the local lobstrok are emerging from the sea and choking off the road to the village.\n\nPlease, {class}, go and thin the numbers of this pest.", objectives = "Kill 5 Drysnap Crawlers and 5 Drysnap Pincers.", progress = "Has our lobstrok problem been dealt with, <class>?", completion = "On behalf of us all at Shadowprey Village, I thank you, <race>." }
WordHunterWoW_QuestEN[14336] = { title = "Kill or Be Killed", description = "The reefs have always protected us from a coastal attack.  The earthquakes must've opened a passage for the Forsaken ships.\n\nQuick, {name}.  Slow down the attackers while I get the rest of the militia ready.\n\nI think I can hear the Prince and some of our men engaging the Forsaken even as we speak.  Speak to Liam and see how you can be of use.\n\nOh... and make sure he doesn't get himself killed.  I'm afraid he might be a little reckless in his current state.", objectives = "Speak to Prince Liam Greymane outside of Duskhaven.", completion = "<name>!!!  You ARE alive!\n\nI thought I was having dreams about the old days when I heard your voice..." }
WordHunterWoW_QuestEN[14337] = { title = "Shadowprey Village", description = "Hello again, {class}.\n\nI have received news that Shadowprey Village is in need of some assistance. Our hands are more than full here, so I must call upon you to travel there and be of assistance to them.\n\nThe village lies on the coast to the southwest of here. When you arrive, seek out the one named Mai'Lahii.", objectives = "Karnum Marshweaver wants you to speak with Mai'Lahii.", completion = "Welcome to Shadowprey Village, <race>.\n\nI was not sure the Cenarion Circle would send anyone." }
WordHunterWoW_QuestEN[14338] = { title = "Ghost Walker Post", description = "Greetings, {class}.\n\nIt is good to see that you still draw breath. The time has come for me to call upon your services.\n\nJust southwest of this glade stands Ghost Walker Post. There you will find a forsaken by the name of Maurin Bonesplitter.\n\nHe may have a solution for one of the problems we face here.\n\nSpeak with him and do what you can to assist him.", objectives = "Karnum Marshweaver wants you to speak with Maurin Bonesplitter.", completion = "Greetings, <class>.\n\nIt is good that you have finally arrived...." }
WordHunterWoW_QuestEN[14339] = { title = "Delivery Device", description = "As fate would have it, there's a special deed that needs doing - one that will benefit the Cenarion Circle as well as myself.\n\nYou see, {class}, I am under pressure to create a special... concoction, shall we say. I believe my work to be complete, but I need to have it tested to be certain.\n\nThe target of this test is to be the naga, who threaten this region from the west. Their demise would surely aid the Circle.\n\nFirst though, I need a delivery device. Hollow horns from the dying kodo should do nicely.", objectives = "Maurin Bonesplitter wants you to collect 3 Hollow Kodo Horns from Dying Kodo.", progress = "Back so soon, <class>?", completion = "Yes, yes.\n\nThese will do nicely...." }
WordHunterWoW_QuestEN[14340] = { title = "Dressed to Impress", description = "Every man's got to learn his own lessons I suppose.\n\nHere, take my wizard hat. I have no doubt that he'll take you on as an apprentice if you look the role... you just might have to jump through some hoops first. Tiny flaming hoops, suspended over spikes, with spinning blades on the other side.\n\nYou should be able to find an image of Xylem on top of that hill to the northeast.", objectives = "Put on your new wizard hat and then speak to the Image of Archmage Xylem just northeast of the Northern Rocketway Exchange.", progress = "Hello.", completion = "Well look at you, aren't you just a marvel of modern Magery! Quite a fancy hat, I must say.\n\nApprentices. Apprentici? I do think that I might have quite a few already, but I suppose one can never have too many appren..tici." }
WordHunterWoW_QuestEN[14341] = { title = "Smeed's Harnesses", description = "Pardon me, young {race}.\n\nI'm in need of a little help. I've just finished filling an order for harnesses that must be delivered right away.\n\nI'm a bit old for the trip, especially considering how dangerous things have become lately.\n\nWould you mind?\n\nThey need to go to Smeed, a goblin who lives just southeast of here.", objectives = "Nataka at Ghost Walker Post wants you to deliver Smeed's Harnesses to Smeed.\n\nProvided item:", completion = "Ahh, my harnesses!\n\nThanks, friend!" }
WordHunterWoW_QuestEN[14342] = { title = "Infernal Encroachment", description = "The demons are on the move, {race}!\n\nIf nothing is done, we'll be overrun in a matter of weeks. I've just returned from Mannoroc Coven, where the infernals there are falling from the sky!\n\nWe need to at least buy ourselves some time. Get down there and pick up where I left off!", objectives = "Felgur Twocuts wants you to destroy 10 Lesser Infernals.", completion = "Well done, <race>!\n\nThe danger persists, but you have bought us some time." }
WordHunterWoW_QuestEN[14343] = { title = "Maurin's Concoction", description = "<Maurin carefully seals his concoction into the hollow kodo horns.>\n\nHere you are, {class}.\n\nBring these to Karnum. It's up to him how he wants to use them on the naga. \n\nI'll be watching to gauge the effectiveness of my formula!", objectives = "Maurin wants you to deliver Maurin's Concoction to Karnum at Karnum's Grove.\n\nProvided item:", completion = "I hate to use such unnatural measures, but I fear we simply have no choice...." }
WordHunterWoW_QuestEN[14344] = { title = "Jugkar's Undoing", description = "You recognize this as the essence of a summoned demon.\n\nDangerous and rarely understood energies weave in and out of its surface.\n\nAs you gaze upon it, a vision fills your mind - an image of yourself controlling demonic minions. A rush of excitement flows through you as you imagine wielding such power.\n\nLooking at your surroundings, you wonder how this treasure might be used against this demonic enemy....", objectives = "You are to use the Infernal Power Core to take control of Lord Azrethoc at Jugkar's Altar, and use its powers to slay Jugkar Grim'rod.", completion = "You should be proud of how you manipulated the enemy's power and used it against them.\n\nYou've dealt the demons of Mannoroc a severe blow...." }
WordHunterWoW_QuestEN[14345] = { title = "Wash Out", description = "Delicious!\n\nAzy always trying to get his hands on magic artifacts. Said he was trying to make friends with that archmage person. Xylem!\n\nXylem has LOTS of apprentices. Takes in all kinds, burns'm out, leaves them wandering all over. High turnover.\n\nLast one was last night. Headed over towards that big goblin tower construction thing, way west. Maybe he'll help you meet Xylem? Maybe Xylem knows where Azy is?\n\nPlay nice!", objectives = "Speak to Sorata Firespinner at the Northern Rocketway Exchange.", completion = "Look buddy, I was in your shoes not a week ago. Big powerful Archmage actually takes on apprentices! Who could pass up an opportunity like that?!\n\nSometimes, things really are just too good to be true." }
WordHunterWoW_QuestEN[14346] = { title = "Cleansing Our Crevasse", description = "As you of course know, {name}, the naga remain a serious threat to the region. The time has come for us to drive them back into the sea!\n\nWhen you are ready, Grimfeather will take you to the crevasse where they are preparing a violent assault. Once there, use Maurin's Concoction to teach them a lesson they shall not soon forget.", objectives = "Karnum Marshweaver wants you to use Maurin's Concoction to kill 10 Slitherblade Invaders, 10 Slitherblade Sirens, and 3 Sea Giants.", progress = "Have you dealt with the naga in our crevasse, <name>?", completion = "Your deeds continue to impress me, <name>.\n\nPlease accept this gift on behalf of the Cenarion Circle." }
WordHunterWoW_QuestEN[14347] = { title = "Hold the Line", description = "{name}!  I'm still not sure if you're alive or dead... human or worgen...\n\nI'm not even sure if I'm really awake.  But THIS I am sure of...\n\nWe're going to kill a great many of these motherless Forsaken.", objectives = "Kill 10 Forsaken Invaders.", completion = "Yes, <name>!  Just like old times...\n\nI'm going to have to work hard at not shooting you, but Krennan explained everything to us." }
WordHunterWoW_QuestEN[14348] = { title = "You Can't Take 'Em Alone", description = "Look here, {name}.  The big fat ones -- abominations, they're called -- they don't go down easy, so don't tackle them on your own.\n\nBut I have an idea so crazy it might just work.  Or it might get you killed, if we're not careful, I suppose.\n\nThere's barrels of gunpowder beneath the sheds and by the windmills.  Grab them and toss 'em right on the abominations' heads.  I'll take care of the rest with this trusty old blunderbuss.", objectives = "Use the Black Gunpowder Kegs to blow up 4 Horrid Abominations.", progress = "They just keep coming, don't they?", completion = "You and me, <name>.  We make a great team...\n\nIt's good to have you back." }
WordHunterWoW_QuestEN[14349] = { title = "The Call to Command", description = "The order has come down, <class>. Sylvanas herself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation.\n\nUnfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff.\n\n<Nathanos stares coldly at you.>\n\nTravel to the Undercity at once and report to the Dark Lady. Do not embarrass me, <class>!", objectives = "Travel to the Undercity and speak with Lady Sylvanas Windrunner.The order has come down, <class>. Sylvanas herself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation.\n\nUnfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff.\n\n<Nathanos stares coldly at you.>\n\nTravel to the Undercity at once and report to the Dark Lady. Do not embarrass me, <class>!", completion = "The Grand Crusader sits safely in the Scarlet Bastion while his forces pour into our lands, desecrate our structures and monuments and murder our people.\n\nThe time has come to deal with this pest. You will become the instrument of our reckoning." }
WordHunterWoW_QuestEN[14350] = { title = "The Crimson Courier", description = "We cannot attack the Scarlet Crusade's command directly; they are too well defended. But there's more than one way to skin a cat. They'll be nothing without their main force.\n\nThe Deathstalkers have been collecting data on the activity of the Crusade outside of Stratholme. Each day, a report is sent from their central command to Tyr's Hand. This report is the key, <race>! Find the Crimson Courier and recover that report. Bring it to Nathanos.", objectives = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.\n\nTake the command to Nathanos Blightcaller for further instruction.", progress = "Succeed now and you will have almost earned my respect, <class>.", completion = "<Nathanos laughs.>\n\nExcellent! Finally! An opportunity to destroy the Scarlet Oracle!" }
WordHunterWoW_QuestEN[14351] = { title = "Battle of Hillsbrad", description = "Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.\n\nTake this sealed commendation to Bragor Bloodfist in the Undercity.  Go with pride, <class>.", objectives = "Take Darthalia's Sealed Commendation to Bragor Bloodfist in the Undercity.", progress = "Why aren't you out on the battlefield, <class>?", completion = "So you're the <class> who tore through the Alliance forces in the Hillsbrad Foothills? I've heard your name already. Word travels fast.\n\nThe Horde can use someone like you if you keep this up, <name>.\n\nWe need to keep our eyes on all threats around us, but with that king leading them, the humans will continue to be a problem. You've confirmed that there's strength enough in the Horde to end that threat in time." }
WordHunterWoW_QuestEN[14352] = { title = "An Unholy Alliance", description = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin", objectives = "Take the Small Scroll to Bragor Bloodfist in the Undercity.", progress = "What do you want, <name>? This had better be important.", completion = "I've seen the insignia on this scroll before during my time in Northrend. You say this was on that crone who leads the pigs in Razorfen Kraul?\n\nI'll be damned if I'm going to let the Scourge get a foothold here. The one who wrote this - this Malcin - is one of the Lich King's servants, obviously, and that makes him a target. Your target.\n\nThey're not going to take Kalimdor." }
WordHunterWoW_QuestEN[14353] = { title = "An Unholy Alliance", description = "Supposedly this Malcin is outside Razorfen Downs. There's no question - he has to die.\n\nMy contacts in Orgrimmar tell me their scouts have found signs of the Plague down there. The quilboar are showing signs of being plagued, too; they're much more powerful. Whatever the Scourge are doing down there needs to end. Now.\n\nFind this Malcin and kill him. Report back here when he's dead.", objectives = "Bring Ambassador Malcin's Head to Bragor Bloodfist in the Undercity.", progress = "Did you find the Ambassador, <name>? Did you kill him?\n\nI will not have the Scourge gain a foothold in Kalimdor. We've fought too hard to allow them easy access to our cities.\n\nAt least their crone still numbers among the living. She might be stupid enough to allow the Scourge in her home, but she must have sense enough to know she'd lose everything if she took the 'power' they offer.", completion = "Good work, <class>!\n\nYou've done the Horde proud by stopping the Scourge from setting down roots on our soil. An act like that deserves a reward, and the Forsaken have enough lying around that I'm sure they can spare a few things.\n\nWe may not know everything they've done in the Downs, but we'll find out. They can't slink around in the dark forever." }
WordHunterWoW_QuestEN[14354] = { title = "Elune's Gifts", description = "Simply intolerable!\n\nSatyrs of all things, desecrating our sacred lands...\n\nTheir days are numbered, {race}. I can assure you of that. As soon as we have the numbers, I shall lead a charge that will rid this land of the wicked creatures.\n\nFor now, though, perhaps you could put my mind at ease?\n\nTravel just east of here to Sargeron and scour the ruins. Find the relics of Elune and ensure that they are in good condition.\n\nI'll pay you well for this favor.", objectives = "Visit Elune's Relics in Sargeron.", completion = "The relics are intact! Well, indeed, that is something.\n\nYou have put my mind at ease, <race>. Please accept this as my gift to you." }
WordHunterWoW_QuestEN[14355] = { title = "Into The Scarlet Monastery", description = "One of my duties while I'm stationed here is to help the Forsaken take care of their borders, and that, <class>, is exactly what you're going to do for me.\n\nI might live and breathe, but the Scarlet Crusade will cut down my people as quickly as they will one of the undead. They're a problem here, a big one, and you're going to do something about it.\n\nGo to the Monastery and slay High Inquisitor Whitemane and her lieutenants.", objectives = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Bragor Bloodfist in the Undercity.", completion = "I'm sure Sylvanas will be glad to have that problem taken care of, <name>. The task I gave you wasn't easy, but here you stand, victorious. That commands respect, and what you've done won't be forgotten." }
WordHunterWoW_QuestEN[14356] = { title = "The Power to Destroy...", description = "Listen up, <class>.\n\nYou may not know this, but Orgrimmar's got a problem. Deep in Ragefire Chasm, a sect of the Shadow Council called the Searing Blade performs their sinister work. They're mainly orcs, and I can't trust sensitive information in the hands of the grunts there. That's where you come in.\n\nThey should have two books in their possession. I want them kept out of the hands of the Searing Blade and the Forsaken alike. Bring them to me directly.", objectives = "Bring the books Spells of Shadow and Incantations from the Nether to Bragor Bloodfist in Undercity.", progress = "Did you secure the books? They need to be kept out of the wrong hands.", completion = "Good, <class>. You've done well. I'll keep these safe from prying eyes; the last thing we need is a strong Shadow Council rising up again.\n\nCheck back with me in the future; there's always something that needs doing around here, apparently, and I might need another able body." }
WordHunterWoW_QuestEN[14357] = { title = "To the Hilt!", description = "The handmaiden of Elune! It's even more glorious than the stories tell.\n\nThe legends surrounding this relic come to your mind as you draw near it:\n\nIn ancient time, after battle, the enemies' weapons were to be cast upon the basin in exchange for a divine gift of some sort.\n\nAs you ponder this ritual, the glint of steel catches your eye from a nearby weapon rack....", objectives = "Collect 20 Satyr Sabers from the weapon racks and various satyrs in the region.", progress = "The statue stands expectantly.", completion = "With the ritual completed, you are awarded a divine gift.\n\nYou can't help but to feel a great sense of honor as you receive one of Elune's boons." }
WordHunterWoW_QuestEN[14358] = { title = "Ten Pounds of Flesh", description = "According to ancient legend, this ancient brazier was placed here for the performing of sacrifices.\n\nFrom what little you remember of the stories, a blessing is bestowed upon the being who places the flesh of Elune's enemies on the brazier's burning embers.\n\nLooking around, you determine that the satyrs who now possess this region would likely qualify.", objectives = "Collect 10 pieces of Satyr Flesh from the various satyrs in Sargeron.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier graciously endows you with a blessing." }
WordHunterWoW_QuestEN[14359] = { title = "Blessings From Above", description = "You feel a deep connection to the distant past having partaken of the ancient blessing granted by this relic.\n\nYou determine to make as much as you can of this divine gift.", objectives = "You are to collect 10 pieces of Satyr Flesh from the various Satyrs in Sargeron, and place them on Elune's Brazier.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier graciously endows you with a blessing." }
WordHunterWoW_QuestEN[14360] = { title = "Nothing a Couple of Melons Won't Fix", description = "The markings on the Sargeron ruins, combined with what you've gleaned from Furien's text make one thing clear:\n\nThere is something special about the old fountain in the Sanctuary of Elune.\n\nIt would seem that one could expect special power from washing their face in the fountain. First, of course, there would need to be something in the ancient fountain with which to wash.\n\nPondering this problem, you spot a melonfruit at the base of a nearby tree....", objectives = "You must gather 8 Melonfruit and squeeze their juices into the Cup of Elune at Sargeron.", completion = "After filling it with liquid from the melons, you proceed to wash your eyes from the ancient font.\n\nUpon opening your eyes, you are able to see the spirits of ancient elves, still faithfully carrying out rituals to their goddess.\n\nYou ponder the significance of this revelation and determine to study Furien's research for more clues...." }
WordHunterWoW_QuestEN[14361] = { title = "Peace of Mind", description = "We are a forward post, charged with monitoring potential adversaries. Once the Alliance launches its Desolace campaign, our work here will ensure that there are no surprises.\n\nRecently, one of our scouts was caught and sacrificed by the Burning Blade at their stronghold to the west. Since then, we've been assaulted with threats and taunts from a Burning Blade wretch named Kohor.\n\nTheir days here are numbered, but I will pay handsomely for that one to be silenced now!", objectives = "Kill Kohor.", completion = "It is done.\n\nCaptain Pentigast should be able to sleep in peace now that Kohor's threats have been silenced." }
WordHunterWoW_QuestEN[14362] = { title = "Ears Are Burning", description = "Captain Pentigast has made no secret of his disdain for the Burning Blade at Thunder Axe Fortress.\n\nSurely, proof of their demise would be of value to him.", objectives = "Collect 25 Burning Blade Ears.", progress = "What have you there, <class>?", completion = "Ears of the Burning Blade?\n\n<Captain Pentigast smiles.>\n\nWell done, <class>. This is just a shadow of what will soon become of that vile cult!" }
WordHunterWoW_QuestEN[14363] = { title = "You'll Know It When You See It", description = "With his dying breath, Kohor mentioned the summoning of a demon that could threaten the entire region.\n\nHe may have been bluffing, but that's not a chance worth taking.\n\nThis cannot wait for the Alliance's invasion of Desolace to take shape. You must scour Thunder Axe Fortress for clues and bring an end to this potential threat.", objectives = "Find the Ancient Summoning Ritual in Thunder Axe Fortress.", progress = "The Burning Blade must not be allowed to succeed with their plan!", completion = "It is most fortunate that you took the time to search for this.\n\nNo one would have expected the Burning Blade to be in possession of something so powerful!" }
WordHunterWoW_QuestEN[14364] = { title = "Putting Their Heads Together", description = "So it's true....\n\nThe parchment you discovered in Thunder Axe Fortress details a powerful summoning ritual. One stronger than the Burning Blade have ever been known to possess.\n\nClearly, this rite must be stopped at all costs!\n\nPerhaps if this demon were summoned forth prematurely the crisis could be averted.", objectives = "Collect 100 Bleached Skulls from Thunder Axe Fortress, then place them at the Burning Blade Summoning Circle, then kill Nazargen.", completion = "You diverted what would have been a serious crisis, <class>.\n\nIf that summoning was delayed just a bit longer, the demon would have become far too powerful for our small forces here to contend with.\n\nPlease accept this gift as our thanks for your service." }
WordHunterWoW_QuestEN[14365] = { title = "Ethel Rethor", description = "We have recently received a plea for help from a researcher of the Cenarion Circle.\n\nWe have no one we can spare to send, so I ask that you pay her a visit on our behalf.\n\nKorrah is posted near the ruined tower of Ethel Rethor, on the coast to the west.", objectives = "Corporal Melkins wants you to speak to Korrah at Ethel Rethor.", completion = "It is good that you have come.\n\nThere is grave danger looming here." }
WordHunterWoW_QuestEN[14366] = { title = "Holding Steady", description = "We can take it from here, {name}.  Check in with Mayor Armstead.\n\nThese are only a small part of the Forsaken's forces.  If we don't move quickly we're going to have bigger problems on our hands.\n\nSee what you can do to engage the Forsaken army at their landing location.", objectives = "Speak to Gwen Armstead in Duskhaven.", completion = "Great news, <name>.  I've sent the remaining militia to the shore to meet the Forsaken force head on." }
WordHunterWoW_QuestEN[14367] = { title = "The Allens' Storm Cellar", description = "Lord Godfrey is leading the attack near the Forsaken's landing area.  See what you can do to help us keep the Forsaken back.\n\nI've been told Godfrey has commandeered the storm cellar in the Allen Farmstead, far to the west.  Seek him there.", objectives = "Speak to Lord Godfrey inside the storm cellar of the Allen Farmstead in Gilneas.", completion = "The Forsaken are here in full strength, <name>.  We barely have enough men to hold them back." }
WordHunterWoW_QuestEN[14368] = { title = "Save the Children!", description = "The military will not allow me outside the cellar, but my children are still in my farm!  Please, you must go find them.\n\nThe Forsaken have no regard for innocent life -- my kids are in great danger!\n\nTheir names are Cynthia, Ashley and James.  If you find them, bring them back here.  I'll be forever in your debt.", objectives = "Rescue Cynthia, Ashley and James in the Hammond Farmstead.", progress = "I... I don't know if I can go on without them.", completion = "My children are safe!  You've done a wonderful thing, <name>.  I don't know how to thank you!" }
WordHunterWoW_QuestEN[14369] = { title = "Unleash the Beast", description = "I'm not going to lie, {name}.  I don't like the idea of having worgen among our ranks.\n\nWho knows how long 'til Krennan's concoction wears off and you're trying to chomp one of our heads off.\n\nUntil that time, however, we can make ample use of your ferocity.\n\nI want you to go out in the battlefield and kill as many of those Forsaken as you can, in as brutal a way as you can.\n\nWe're going to put the fear of the worgen in them, {name}.", objectives = "Kill 8 Forsaken Footsoldiers or Sailors.", completion = "Not bad, <name>.  It's a good thing you're on our side." }
WordHunterWoW_QuestEN[14370] = { title = "Mysterious Azsharite", description = "Azsharite! This mysterious crystalline substance has been used to forge weapons of fel power, but in our hands, we've discovered that it's capable of focusing enormous amounts of energy. It may be the biggest goblin discovery since kaja'mite.\n\nBut what is it? Where does it come from? Why is it located only here? Science demands an answer! I need more samples to study. Search out Azsharite deposits all along the nearby cliffs. ", objectives = "Collect 5 Azsharite Samples from the nearby cliffs.", progress = "Have you got more samples? Careless adventurers have been looting this stuff for years - they don't know how precious it is!", completion = "Ah, excellent. Some of these samples look fresh. I'm going to be up to my neck in this stuff trying to solve this mystery!" }
WordHunterWoW_QuestEN[14371] = { title = "A Gigantic Snack", description = "While you're here running around the cliffs, perhaps you can help me with another line of investigation. The giants who walk these cliffs have been here since these mountains formed. Maybe they know where the Azsharite comes from? It's in our best interest to befriend these giants and find out.\n\nGather up a gigantic meal for me as a peace offering! Kill the mistwing cliffdwellers that have been such a nuisance to our studies and collect their carcasses for me.", objectives = "Collect 8 Mutilated Mistwing Carcasses from Mistwing Cliffdwellers.", progress = "I probably should've warned you that mistwing chimaeras can shoot lightning.", completion = "Phew! The stench! Well, hopefully that massive heap of carcasses smells more appetizing to a giant." }
WordHunterWoW_QuestEN[14372] = { title = "Thargad's Camp", description = "It pleases me to see that you still draw breath, {class}. I have been sent word that the demon activity in the south has been intensifying.\n\nThere is a camp on the borderlands there that is in danger of being cut off if the demons move northward.\n\nPerhaps you could lend them a hand?\n\nI know the leader of the camp there is Thargad. He will be able to direct you wisely.\n\nThank you, friend. Be well.", objectives = "Karnum Marshweaver wants you to speak to Thargad.", completion = "Demons?\n\nOh, there be lots I can tell yeh 'bout demons!" }
WordHunterWoW_QuestEN[14373] = { title = "Infernal Encroachment", description = "Listen up, now. An' lookie here.\n\n<Thargad points off to the east.>\n\nYeh see them big green glowin' balls that be fallin' from the sky?\n\nThose be a nasty buncha demons roamin' the lands unchecked. Well, almost unchecked... I've been keepin' 'em on their toes, givin' 'em sumthin' ta think about.\n\nHow 'bout you get over there an' pick up where I left off?", objectives = "Destroy 10 Lesser Infernals.", completion = "Well, lad!\n\nDon't hesitate to knock a few more down for good measure!" }
WordHunterWoW_QuestEN[14374] = { title = "Portals of the Legion", description = "Here it is - the Hand of Iruxos.\n\nGot it from one o' them Burning Blade leaders myself.\n\nPowerful thing! See, yeh use it on demon portals and they just disappear! Spooky magic, but these be desperate times...\n\nThe demons keep comin' at this rate, and my camp will get overrun before ya know it.\n\nHere ya go, now. Get on with it.", objectives = "Banish 6 Portals at Mannoroc Coven.", completion = "Aye, that'll buy us some time, <class>.\n\nThank yeh." }
WordHunterWoW_QuestEN[14375] = { title = "Last Chance at Humanity", description = "", objectives = "I need you to pull through, <name>.  This dosage is strong enough to kill a horse.\n\nBut I know you.  I know what you're made of.  You will be fine.\n\nTrust me.  I know what you're going through.\n\nNow drink up and close your eyes." }
WordHunterWoW_QuestEN[14376] = { title = "Jugkar's Undoing", description = "You recognize this as the essence of a summoned demon.\n\nDangerous and rarely understood energies weave in and out of its surface.\n\nAs you gaze upon it, a vision fills your mind - an image of yourself controlling demonic minions. A rush of excitement flows through you as you imagine wielding such power.\n\nLooking at your surroundings, you wonder how this treasure might be used against this demonic enemy....", objectives = "You are to use the Infernal Power Core to take control of Lord Azrethoc at Jugkar's Altar, and use its powers to slay Jugkar Grim'rod.", completion = "You should be proud of how you manipulated the enemy's power and used it against them.\n\nYou've dealt the demons of Mannoroc a severe blow...." }
WordHunterWoW_QuestEN[14377] = { title = "Befriending Giants", description = "A cursory study of the azsharite you brought me reveals that it's not biological in nature, nor is it naturally formed. There's another creature in Azshara with similar properties: the cliff giants that lumber around these cliffs.\n\nOne of the giants seems willing to help our research along. Take the meat you collected to Gormungan, the giant standing just west of here. Befriend him, then grill him - find out if he knows the secret of azsharite!", objectives = "Talk to Gormungan outside of the Southern Rocketway Terminus and discover the secret of azsharite.", progress = "What did you discover? You look pale, <class>!", completion = "Speak slower - what are you saying? Am I hearing you right? Those formations of azsharite are actually where the giants have - oh my. Groady!! Let's not tell Dr. Grapplehammer, he's made this stuff his life's work.\n\nWell, at least now we know where azsharite comes from, and why it's so rare. We've got to figure out a way to speed up, uh, \"production!\"" }
WordHunterWoW_QuestEN[14378] = { title = "Hunting Brendol", description = "I'm too busy collectin' artifacts to busy myself with much else, but there is a bit of an issue here I wouldn't mind sortin' out.\n\nThere's a forsaken apothecary who's been pokin' around these parts for a while now. Normally, I'd ignore him, but three times now he's snuck into my camp and pilfered my supplies.... enough's enough!\n\nFind the thief and bring me whatever's left o' my things!", objectives = "Recover Brendol's Satchel.", progress = "Well, <class>? Did yeh find the cretin?", completion = "Justice is done!\n\nNow let's have a peek at what's left of my goods...." }
WordHunterWoW_QuestEN[14379] = { title = "Rock Lobstrock!", description = "Thargad works practically nonstop chasing after ancient Titan relics. He stays so busy that if it weren't for me, he'd probably forget to eat!\n\nSpeaking of eating, I'd like to prepare him something special - perhaps you could help me out?\n\nLobstrock roam all over the coast to the west. I'd never last in a fight with them myself, but I could make a great meal if you were to bring me some of their tails!", objectives = "Get 7 Tender Lobstrock Tails.", progress = "Were you able to collect some lobstrock tails, <race>?", completion = "Ohhh, these will do nicely!\n\nThargad will be so surprised!" }
WordHunterWoW_QuestEN[14380] = { title = "An Impactful Discovery", description = "<Thargad rummages through the satchel and pulls out a curious object.>\n\nWell now, this is odd... it's a hollow kodo horn with some sort of potion inside.\n\n<Thargad sniffs the potion.>\n\nWHEW! Definitely not any kind of healthy elixir. This mess is meant for one thing... killin'.\n\nHow 'bout yeh run it back up to Karnum and see if there's anything he can do with it...", objectives = "Take the Mysterious Concoction to Karnum at Karnum's Glade.\n\nProvided item:", completion = "<Karnum examines the concoction.>\n\nYes, <class>. Not only do I know what this is, I know just how you should use it...." }
WordHunterWoW_QuestEN[14381] = { title = "Cleansing Our Crevasse", description = "I recognize this foul creation. It's a terrible disease that kills almost instantly, and in a most violent manner. Loathe as I am to employ such devices, I fear we have no choice here.\n\nAs you of course know, the naga remain a serious threat to the region. The time has come for us to drive them back into the sea!\n\nWhen you are ready, Grimfeather will take you to the crevasse where they are preparing a violent assault.\n\nUse the concoction on the naga and their allies to make Desolace safe!", objectives = "Use Maurin's Concoction to kill 10 Slitherblade Invaders, 10 Slitherblade Sirens, and 3 Sea Giants.", progress = "Have you dealt with the naga in our crevasse, <name>?", completion = "Your deeds continue to impress me, <name>.\n\nPlease accept this gift on behalf of the Cenarion Circle." }
WordHunterWoW_QuestEN[14382] = { title = "Two By Sea", description = "The Forsaken catapults are kicking the snot out of us, {name}.  And even if we do take care of them, they've two ships with rows of cannons at the ready.\n\nI've a plan to kill two birds with one stone.  You're the stone in this plan.\n\nTake out the machinists manning the catapults.  After this, use the catapults to launch yourself aboard the Forsaken ships.\n\nIf your aim isn't terrible, you should be able to land safely.  Once onboard, go below decks and take care of each ship's captain.  Good luck, {class}.", objectives = "Use the Forsaken Catapults to board the Forsaken ships and slay Captain Morris and Captain Anson.", completion = "Well done, <name>.  You might be a bloody beast, but you're our beast." }
WordHunterWoW_QuestEN[14383] = { title = "The Terrible Tinkers of the Ruined Reaches", description = "Scoundrels! Infidels! Ever since I started my operation here in Azshara the Gadgetspring family has hampered my studies and sabotaged my research. And now a mob of middling, second-rate tinkers have rallied to their aid! I have pressing business to attend to: see to it that those gnomes are finished for good.\n\nHead to the Ruined Reaches on the coast, south of my Secret Lab, and start rolling some of their disproportionately enormous heads for me.", objectives = "Slay Bingham Gadgetspring in the Ruined Reaches, along with 4 Netgun Gnomes and 6 Zapper Gnomes.", progress = "I trust you've dug a significant number of tiny graves along the coast, yes?", completion = "Oh - marvelous. Tell me more. And that precocious young Gadgetspring? Dead as well? Ah, wonderful. My work here is important but at times I do miss the carnage of demolishing my enemies on a more personal level. Here, perhaps you can make use of some of my discarded equipment." }
WordHunterWoW_QuestEN[14384] = { title = "Rerouted!", description = "Halt!\n\nOn behalf of the Nijel's Point Guard, I am under orders to send all able-bodied allies to report directly to Corporal Melkins.\n\nI am not authorized to offer any other information.\n\nWhat I can offer is transportation. You are free to use my mount. It will deliver you directly.\n\nDismissed.", objectives = "Officer Jankie wants you to ride her mount to Nijel's Point and speak to Corporal Melkins.", completion = "Welcome to Nijel's Point, <race>.\n\nNow, let's see about getting you briefed on our situation here." }
WordHunterWoW_QuestEN[14385] = { title = "Azsharite Experiment Number One", description = "Well, I can think of one surefire way to send a giant running to the bathroom, but you're not going to like it. What we need is a ... massive ... laxative. Oh hey! Would you believe the gnomes have something of the sort? That can't be a coincidence. I wonder what they're trying to push through over there?\n\nOur intelligence reports that the laxative was delivered to Gadgetspring's tower, down on the shoreline south of the Secret Lab. Retrieve that laxative and feed it to Gormungan!", objectives = "Grab a giant-sized laxative from the gnomish tower in the Ruined Reaches. Try to feed the laxative to Gormungan the giant.", progress = "Once you have the laxative, try to feed it to Gormungan. And maybe give him a magazine or something. Do it for science!", completion = "So it was a no-go? Literally? Well, Grapplehammer won't take no for an answer. We'll have to try something else.\n\nMaybe I'll have my interns smuggle this laxative into the night elf encampment. That'll be good for a laugh, at least." }
WordHunterWoW_QuestEN[14386] = { title = "Leader of the Pack", description = "Excellent work so far, {name}.  Our scouts have identified the leader of the Forsaken ground assault.\n\nOne of Sylvanas' handpicked dark rangers is overseeing the battlefront from the Walden house near the shore.  Take this whistle and use it when you're close to her.\n\nI'll have my men let loose our attack mastiffs to take her down.  Be careful, {name}.  You don't want to engage her alone.", objectives = "Use the Mastiff Whistle to help you slay Dark Ranger Thyala.", progress = "Is it done yet, <name>?", completion = "You did it, <name>.  That should take the wind out of their sails." }
WordHunterWoW_QuestEN[14387] = { title = "Lay of the Land", description = "Yes, yes. Welcome to Desolace, {race}.\n\nSorry we had to be so insistent, but we're a small outpost, and there are big problems in this region - most of them quite urgent.\n\nBottom line: We need all the help we can muster.\n\nTo start with, our friend Vahlarriel over there has been getting pretty antsy, insisting that we send a contingent to visit the ruins to the east.\n\nWhy don't you go introduce yourself....", objectives = "Captain Pentigast wants you to speak to Vahlarriel in Nijel's Point.", completion = "A pleasure to meet you, <class>." }
WordHunterWoW_QuestEN[14388] = { title = "Azsharite Experiment Number Two", description = "Okay, new plan. We'll SCARE it out of 'em! In my experience most large creatures are terrified of tiny ones - like rats. Hmm. This place is crawling with rats, but how do we coax them over to the giant?\n\nHey! You don't mind having your cellular matrix broken down and reassembled do you? It's only painful while it's happening. I can shrink you down to rat-sized and you can ride one of these brutes over there like a horse. It's so crazy it's got to work! Speak with me when you're ready for shrinkage...", objectives = "Speak with Assistant Greely to be shrunken down to rat-size. Mount a Rocketway Rat and use it to terrify Gormungan the giant.", progress = "Hey <name>, you look shaken up. Did you scare the giant into going to the bathroom? Or yourself?", completion = "So scaring him didn't work, either? Double-nertz! I'll have to break the news to Grapplehammer: Azsharite's going to remain the rarest substance on the planet. We'll have to use it sparingly." }
WordHunterWoW_QuestEN[14389] = { title = "Wasn't It Obvious?", description = "Azuregos! Yes, of course. Troubled old dragon, but lovely heart. I don't think all the years of vagabonds assaulting him have done him much good. He's a mite strange these days.\n\nNot long ago, when returning yet again to our local Spirit Healer, Anara, I couldn't help but notice that her and Azuregos seemed to be hitting it off. I imagine he's still keeping her company.\n\nThe portal behind me is probably the quickest way to reach her. It might sting a little though.", objectives = "Use the portal behind Joanna at Xylem's tower to find Anara the Spirit Healer and--hopefully--Azuregos.", completion = "Azuregos! At last you've found him!" }
WordHunterWoW_QuestEN[14390] = { title = "Easy is Boring", description = "After a long search with some questionable turns, you've finally found Azuregos.\n\nNow it's just a matter of convincing him to meet up with Kalecgos and put an end to the threat of the black dragonflight in Azshara.", objectives = "Convince Azuregos to return to the world of the living and rendezvous with Kalecgos.", progress = "<Azuregos glares at you.>", completion = "Azuregos has agreed to rendezvous with Kalecgos. Success!" }
WordHunterWoW_QuestEN[14391] = { title = "Turning the Tables", description = "Azuregos and Kalecgos are due to meet up at the Northern Rocketway Terminus. You should meet with them there to make sure that Kalecgos doesn't require any additional help.\n\nShould you prefer to not be dead, Anara will likely be able to help.", objectives = "Speak to Anara to return to the world of the living, then meet with Kalecgos at the Northern Rocketway Terminus.", completion = "Great to see you again! Thank you for finding Azuregos and sending him to me.\n\nI do feel I owe you an apology - I may have undersold how difficult it would be to accomplish the task I gave you. You performed quite admirably, <name>." }
WordHunterWoW_QuestEN[14392] = { title = "Farewell, Minnow", description = "Thank you, little one.\n\nSometimes it's easy to get lost in the throes of love and lose sight of things, even as a dragon. I plan to rededicate myself entirely to making sure Kalec never steps up to take Malygos' place. It's the most noble cause I can think of.\n\nYou should head back to the harbor. I believe someone's waiting for you there.\n\nTry not to get squashed or eaten by anything.", objectives = "Speak to Sorata Firespinner in Bilgewater Harbor.", completion = "Hey there... again.\n\nLook, I gave you my hat. It was a gift. I thought you'd make some use of it. More specifically though, I thought you'd get it the heck away from me.\n\nCan you imagine my surprise when Xylem comes by himself to give it back to me? \"Want to be more like my other apprentices, Sorata? Give your hat another try.\"  Not one of my proudest moments.\n\nSo what... you just tossed it aside for him to find? No. I don't think so. You're going to take this hat and you're going to like it. Really." }
WordHunterWoW_QuestEN[14393] = { title = "Into the Fray!", description = "For untold generations, the centaur clans have fought against one another, but no more.\n\nBecause of your deeds, we stand here together fighting a common foe. We shall win our ancestral lands back from these demons, or we shall die as brothers.\n\nWhat of you, {name}?\n\nYou have earned the right to fight alongside us. I have a group of my best centaurs for you to lead into battle.\n\nWill you take up the spear?", objectives = "Khan Leh'prah wants you to defeat 15 Burning Blade Warlocks, 3 Doomguard Invaders, and Priestess Than'darissa.\n\nSpeak to Khan Leh'prah to ride into battle.", completion = "Well done, <name>!\n\nLet us finish this!" }
WordHunterWoW_QuestEN[14394] = { title = "Death to Agogridon", description = "Our goal is within sight, {name}!\n\nWe can break the will of this demon army by bringing down the one who leads them. If we can succeed, Desolace will be ours!\n\nWhen you are ready, lead a group of centaurs through the pass to the south, into Shadowbreak Ravine. Find where Agogridon hides!\n\nI will gather the other khans and meet you there to face him in battle.", objectives = "Defeat Agogridon.", completion = "Agogridon is no more.\n\nThe demons shall never again take hold in our lands!" }
WordHunterWoW_QuestEN[14395] = { title = "Gasping for Breath", description = "{name}!  I was on my way when it happened.\n\nNo time to waste.  A good half of the town watch was in the area that collapsed.  Get in there and save as many as you can.\n\nMake sure to get them out of the water and onto shore.  I'll make sure they get any aid they need.", objectives = "Rescue 4 Drowning Watchmen.", progress = "There aren't many of us left, <name>.  We have to look out for those remaining Gilneans.", completion = "You did what you could, <name>.  With any luck a few others will find their way to shore." }
WordHunterWoW_QuestEN[14396] = { title = "As the Land Shatters", description = "What in the world was that, {name}?\n\nThose were not cannons or catapults, that is for sure.\n\nGo outside and see what is going on.", objectives = "Speak to Prince Liam Greymane at the Allen Farmstead.", completion = "The ocean, <name>.  It swallowed everything... the land... the Forsaken... our men!" }
WordHunterWoW_QuestEN[14397] = { title = "Evacuation", description = "We've escaped death through dumb luck, {name}.  But luck is running out.\n\nThe coast is becoming flooded even as we speak.  And from the look of it, the landmass beneath us hasn't quite settled yet.\n\nI hate to say this, but we have to leave.  Curses, {name}.... I cannot lose my homeland twice in one lifetime.  Yet these earthquakes are not an enemy we can defeat.\n\nTell Gwen Armstead to start the evacuation.", objectives = "Speak to Gwen Armstead in Duskhaven.", completion = "Liam is right.  We must get everyone to higher ground.\n\nYou must help me spread the word while I manage the logistics of the evacuation." }
WordHunterWoW_QuestEN[14398] = { title = "Grandma Wahl", description = "It's not going to be easy to get Grandma Wahl to come with us.  You must do whatever you can to convince her, though.\n\nYou'll find her at the Wahl Cottage.  Please, {name}.  Do not lose your patience with her.  Her mind is old and she's not entirely lucid.", objectives = "Find Grandma Wahl at the Wahl Cottage.", completion = "A visitor!  Are you staying for tea, sweetheart?" }
WordHunterWoW_QuestEN[14399] = { title = "Grandma's Lost It Alright", description = "Leave?  Now?\n\nWell, if I must, then I must.  But will you be a sweetheart and find something for me?\n\nI've lost my favorite book and won't leave without it.\n\n<After you explain the gravity of the situation, Grandma Wahl shakes her head condescendingly.>\n\nDear, just find the book will you?", objectives = "Find the Linen-Wrapped Book.", progress = "How goes it, dear?  Will you be staying for tea?", completion = "Why thank you, <name>.  I hope you didn't peek!\n\nWhere are your manners, dear?" }
WordHunterWoW_QuestEN[14400] = { title = "I Can't Wear This", description = "What was it you wanted again?\n\nOh, right.  The evacuation orders.\n\nWell I can't be expected to go out in public like this, can I?\n\nGo get me my good clothes.  They're on the clothesline right outside.\n\n<You struggle in vain to convince Grandma Wahl that what she's wearing will do.>\n\nYou young people truly have no manners.  Were you raised by ogres?  Now go get my clothes, sweetie.", objectives = "Get Grandma's Good Clothes.", progress = "Did you find everything okay, dear?", completion = "You're a peach, <name>.  Thanks!" }
WordHunterWoW_QuestEN[14401] = { title = "Grandma's Cat", description = "Right!  About the evacuation, dear.\n\nI just cannot leave without my cat.  He's an adorable orange tabby.\n\nChance's favorite spot to play is a broken down cart near an arbor northeast of here.\n\nBring him here and we'll be on our way.", objectives = "Retrieve Chance the cat.", progress = "You're such a charming young man, <name>.", completion = "There he is!  Grandma's special boy!\n\nThank you so much for finding him.  I hope it wasn't too much trouble.\n\nMy... what manner of dirt found its way underneath my fingernails!" }
WordHunterWoW_QuestEN[14402] = { title = "Ready to Go", description = "I suppose now is as good a time to leave as any.\n\nI have my best outfit, my favorite book and my loving cat.\n\nI hope I'm not forgetting anything.\n\nTell that mayor of yours that I'll be on my way.  I suppose I'll see you in town with the others!", objectives = "Speak to Gwen Armstead in Duskhaven.", completion = "You did the impossible, <name>.  You convinced Grandma Wahl to leave her home.\n\nYou are something else, let me tell you." }
WordHunterWoW_QuestEN[14403] = { title = "The Hayward Brothers", description = "The Hayward Fishery can be found far to the south.  The Hayward brothers have been running it for years.\n\nThey don't make it to town very often, except to trade their fish.  Send word to them that the evacuation is underway.", objectives = "Speak to Sebastian Hayward at the Hayward Fishery.", completion = "You here to give us a hand?" }
WordHunterWoW_QuestEN[14404] = { title = "Not Quite Shipshape", description = "Evacuation, you say?  Well, we had that very same idea all on our own after these Forsaken started showing up.\n\nWe were thinking the water would be the safest way out of here.\n\nUnfortunately our boats didn't come out from that last earthquake unscathed.\n\nI need some additional supplies to finish my repairs: wood, tar and my tools.  Get them for me so that my brothers and I can make it out of here.", objectives = "Obtain Planks of Wood, Coal Tar and Shipwright's Tools.", progress = "Do you have my supplies, <name>?", completion = "This is great, <name>.  I should be able to finish the repairs in no time." }
WordHunterWoW_QuestEN[14405] = { title = "Escape By Sea", description = "Thanks for your help, {name}.  This ship is ready to sail.\n\nNow you go and tell Miss Armstead that we're not going to be part of the land evacuation.\n\nWe Haywards have been men of the sea for generations.  If we're to leave our home, then we'll do so by sea.", objectives = "Return to Gwen Armstead in Duskhaven.", completion = "It's just as well, <name>.  Maybe the Haywards will fare better than us." }
WordHunterWoW_QuestEN[14406] = { title = "The Crowley Orchard", description = "Of course you remember Lord Darius Crowley's daughter, Lorna.\n\nShe never quite recovered after losing her father in Gilneas City.  She's basically led the life of a hermit.  The only visitor she's allowed into her house has been Krennan... and he won't say a word about the whole thing.\n\nSend word to her about the evacuation.", objectives = "Speak to Lorna Crowley at the Crowley Orchard.", completion = "Stay back! Don't make me...\n\nIs it you?  By the Light!  It's you, <name>!" }
WordHunterWoW_QuestEN[14407] = { title = "Azshara Blues", description = "Hey! I'm glad I caught you.\n\nI come on behalf of my master, Kalec. He requires your aid. Find him under the bridge in the slums as soon as you can!", objectives = "Meet with Kalec in Bilgewater Harbor.", completion = "Thank you for coming. I apologize for the discretion, but it's extremely important that I not be seen by certain individuals.\n\nI'm in quite a bind and I've taken notice of some of your recent deeds. Hear me out, help me, and I'll see to it that you're rewarded in kind." }
WordHunterWoW_QuestEN[14408] = { title = "Nine's Plan", description = "My benefactors used their diminutive intellect to construct an interplanetary transport. As designed, this so-called \"Rocket\" is a death trap. But I suspect a simple re-engineering of the fuel catalyst semifold would render a stable mixture, providing a breathable oxygen byproduct. To implement such changes, I require the original engineering plans.\n\nLocate the Laboratory Archives and ring the doorbell to gain entry. The plans will be held by the lab director himself, presuming he still lives.\n", objectives = "Acquire the Secret Rocket Plans from the Laboratory Archives building at the eastern end of the Secret Lab. Ring the door buzzer outside and kill the lab director when he emerges.", progress = "I suspect the archives are close, <name>. Locate those plans!", completion = "<The raptor snatches the paperwork in her prehensile claws and holds the schematics up to her face, clucking her pointed teeth dismissively.>\n\nThese are like the scrawling of children. Common sense precludes the routing of control hydraulics so near to the secondary stage burners! Still, this is salvageable.\n\nDo you know how to refactor fuel matrixes for pressure variations at a fixed acceleration? No? Very well, perhaps you can do something else for me while I reconfigure the rocket..." }
WordHunterWoW_QuestEN[14409] = { title = "A Cautious Return", description = "A moment of your time, <class>.\n\nChange is coming. It has drawn us out of the ruins of Eldre'Thalas and into the wide world once more. I have come to research this city and cannot stray from it, but if you are inclined, I have an errand for you.\n\nMy colleague set out for Darnassus to speak with the High Priestess there, that we might come to an understanding. Take this journal to Mordent Evenshade in the temple. It may help in his diplomacy mission.", objectives = "Bring Daros' Journal to Mordent Evenshade in Darnassus.", progress = "It seems I have time to talk. What is this regarding?", completion = "Ah, the writings of Daros. He always was meticulous about tracking progress. His words may aid in explaining how far we've come.\n\nYou have my thanks for bringing this to me, <race>. Perhaps we will see more of each other once it is understood we mean no harm." }
WordHunterWoW_QuestEN[14410] = { title = "The Wilds of Feralas", description = "You are truly brave to help us protect these lands, hero. If you wish to do more for the wilds, there are others in need of your aid.\n\nThe verdant forests of Feralas lie to the south. There, in the shade of the mighty Twin Colossals, you must seek out Telaron Windflight. At Dreamer's Rest, he and his fellow druids of the talon have found signs of a disturbing illness.\n\nThey will need your help, {class}. Go in peace.", objectives = "Travel to Feralas and speak with Telaron Windflight at Dreamer's Rest.", completion = "Welcome to Feralas, <class>. I thank you for coming to assist us." }
WordHunterWoW_QuestEN[14411] = { title = "Feralas Breadcrumb [PH]", description = "One day I will grow up to be a real breadcrumb! To Feralas!!!!1", objectives = "One day I will grow up to be a real breadcrumb! To Feralas!!!!1" }
WordHunterWoW_QuestEN[14412] = { title = "Washed Up", description = "Those Forsaken ships sank way too close to our Fishery.  All the survivors are making their way here and, as you can see, we're a bit outnumbered.\n\nHelp us hold them back while I finish making repairs to the boats.", objectives = "Kill 6 Forsaken Castaways.", progress = "Bloody Forsaken!  Not even the ocean wants them!", completion = "Excellent!  I'm almost done here." }
WordHunterWoW_QuestEN[14413] = { title = "The Pinnacle of Learning", description = "This is so exciting! What's exciting you might ask? Well THIS is of course!\n\nTime to trial... time for YOU to trial. So many challenges to overcome, so much learning to be done. You learning about trials. Me learning about you.\n\nSo now, off you go. To my Arcane Pinnacle. I will meet you there of course, because I'm quite everywhere.", objectives = "Speak to the Image of Archmage Xylem at the base of the Arcane Pinnacle.", completion = "Here so soon! Lovely trip I hope. Not too nauseous or anything?\n\nThere will be much running and much jumping, so a settled stomach is of great practicality." }
WordHunterWoW_QuestEN[14414] = { title = "Feralas Breadcrumb [PH]", description = "One day I will grow up to be a real breadcrumb! To Feralas!!!!1", objectives = "One day I will grow up to be a real breadcrumb! To Feralas!!!!1" }
WordHunterWoW_QuestEN[14415] = { title = "Apparitions in the Orchard", description = "Listen, <name>.  I heard about what happened to you and I trust you regardless of your... affliction.  After all, you were with my father until the end.\n\nBut I'm not going to go out there.  It's not safe.\n\nThe earthquake opened a passage from the mountains and an ettin has decided to pay us a visit.\n\nNot only that, but after I holed up in the house, I started seeing ghostly wolf forms in the orchard.\n\nI can't come out until we at least have some idea about what's going on.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Investigate the Crowley Orchard.Listen, <name>. I heard about what happened to you and I trust you regardless of your... affliction. After all, you were with my father until the end.\n\nBut I'm not going to go out there. It's not safe.\n\nThe earthquake opened a passage from the mountains and an ettin has decided to pay us a visit.\n\nNot only that, but after I holed up in the house, I started seeing ghostly wolf forms in the orchard.\n\nI can't come out until we at least have some idea about what's going on.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14416] = { title = "The Hungry Ettin", description = "Listen, {name}.  We're not going to make it very far without transportation, are we?\n\nIf we just hightail it out of here, the forsaken will catch up to us in no time at all.\n\nRounding up some horses from the stable grounds southeast of here would normally be a breeze, but there's one snag.\n\nThat last quake must've spooked Koroth, the ettin, down from the mountains.  If we don't get our horses soon, I fear that he will.", objectives = "Bring 5 Mountain Horses to Lorna Crowley at the Crowley Orchard.", progress = "You're back, <name>.", completion = "We've got the horses, I'll make sure Duskhaven gets them." }
WordHunterWoW_QuestEN[14418] = { title = "The Deathstalkers", description = "The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.\n\nHawkins will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.\n\nAh, and how could I forget?\n\nWelcome to the Deathstalkers.You will receive:", objectives = "Deliver Andron's Ledger to Aleric Hawkins in the Hall of the Dark Lady in the Undercity." }
WordHunterWoW_QuestEN[14419] = { title = "The Deathstalkers", description = "The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.\n\nOur leader suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.\n\nI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.Upon completion of this quest you will gain:", objectives = "Speak with Andron Gant in the Undercity." }
WordHunterWoW_QuestEN[14420] = { title = "The Deathstalkers", description = "If you wish to join the Deathstalkers, the Dark Lady's elite guard, you will have to prove your worth.\n\nI will not lie to you, <name>, this task could mean your death.\n\nI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.\n\nIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.Upon completion of this quest you will gain:", objectives = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter." }
WordHunterWoW_QuestEN[14421] = { title = "The Deathstalkers", description = "You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.Upon completion of this quest you will gain:", objectives = "Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity." }
WordHunterWoW_QuestEN[14422] = { title = "Raptor Raptor Rocket", description = "Shortly after my intellect was augmented, I bred with Subject Four in order to create a unique race of cognitively superior raptors. Subsequently, Subject Four neither called nor wrote: I have determined to disembowel him upon our next encounter.\n\nNonetheless, there are enough raptor children imprisoned in this lab to provide adequate genetic stock for repopulating my race. Please release them from their cages and carry them to the rocket.", objectives = "Release five Experimental Raptors from their cages in the Secret Lab and deliver them to the rocket beside Subject Nine.", progress = "My beautiful children may attempt to bite you upon release, but at their stage of physical development, it is unlikely that their attacks will be fatal.", completion = "Wonderful! Exemplary work, <name>! As you have no doubt surmised, my objective with regard to this rocket is to utilize it as a sort of astral cradle, an ark if you will, allowing my newly-forged race to slip the surly bonds of this ravaged planet and colonize a world to our own liking. You have been instrumental to our cause. Please accept this currency as I will be minting my own monetary units upon arrival. Farewell, <name>!" }
WordHunterWoW_QuestEN[14423] = { title = "Dozercism", description = "...what we need is a priest!\n\nFortunately I have a small budget set aside for the blessing of machinery. Take this flare gun and head over to Margene, my poor sweet busted bulldozer. Fire off the signal and one of our finest airborne priests should airdrop in to get a handle on the situation. Come back when my bulldozer is taken care of!", objectives = "Use the Blessed Flare Gun near Clubnik's Dozer to summon in help, then 'Exorcise' the bulldozer.", progress = "How is Margene doin'? Running like her sweet self again?", completion = "What? ...What?\n\nMargene! Oh my sweet Margene!!" }
WordHunterWoW_QuestEN[14424] = { title = "Need More Science", description = "<Clubnik wipes away a tear, then juts his chin out with determination.>\n\nNever again, {name}! No bulldozer deserves the fate of my Margene. We're going to need some industrial ghostproofing. This is a job for our top scientists, and I know just the woman for the job! Look for Assistant Greely at the Southern Rocketway Terminus. She's the administrator for Azshara's world-famous Secret Lab, and she owes me a favor.", objectives = "Locate Assistant Greely at the Southern Rocketway Terminus. The Goblin Rocketway can be used to quickly move around Azshara.", completion = "What is Clubnik talking about? Haunted construction equipment? Does it look like I have time for ghost stories?\n\nI've got a laboratory in the middle of a meltdown, fires burning, animals mutated, and worst of all - projects falling behind schedule. Help!" }
WordHunterWoW_QuestEN[14425] = { title = "The First Quest", description = "Greetings, <name>, this is a test.  Accept and kill stuffYou will receive:", objectives = "Test Thrall wants you to kill something." }
WordHunterWoW_QuestEN[14426] = { title = "The Second Quest", description = "This is the second quest!  This time you won't have to kill stuff.You will receive:", objectives = "Santa Thrall wants you to collect 5 boozles, whatever those are." }
WordHunterWoW_QuestEN[14427] = { title = "Item Quest", description = "Item collection quest", objectives = "Get the items" }
WordHunterWoW_QuestEN[14428] = { title = "Amberwind's Journal", description = "If my sources are trustworthy, Lorekeeper Amberwind is overseeing the Alliance investigation of the ruins to the east. I have not yet probed the extent of her abilities: I'm hoping you can give me a full report by engaging her in combat and destroying her.\n\nWith a title like 'Lorekeeper,' I'm guessing Amberwind will have a journal on her that'll tell us exactly what those night elves are up to. Fetch that journal for me. No need to run back; use their own scrying stones to contact me remotely.", objectives = "Slay Lorekeeper Amberwind at the Darnassian Base Camp and retrieve her journal.", progress = "<Andorel's distorted face appears within the scrying stone.>\n\n<name>, have you made contact? What can you tell me?", completion = "Amberwind was making use of an Arcane Construct? Hah! How delightfully inexperienced. It's like watching children play with firearms.\n\nLet's take a look at that journal, <name>. Hold it up to the scrying stone... keep it still ..." }
WordHunterWoW_QuestEN[14429] = { title = "Arcane De-Construction", description = "Arcane constructs are creatures spawned of pure mana and intellect. In the right hands, a construct allows its user to quickly assimilate vast riches of arcane knowledge. But they're dangerous, {name}. So intelligent! So powerful! So very vulnerable to external tampering...\n\nLet's teach these amateurs a lesson and use their own magic against them. Slay Apprentices and collect their runestones for me. Contact me via the lower scrying stone when you're done.", objectives = "Slay Apprentice Investigators and Apprentice Illuminators to collect 10 Attuned Runestones.", progress = "<Andorel's image is blurry and indistinct. He squints at you and taps against the glass of the scrying stone.>\n\n<name>, is that you? The resolution on this stone is terrible. What kind of hardware are they using?", completion = "Good work getting those runestones. To be honest, I only needed one, but the thought of so many night elves slain for such useless baubles fills me with a dark, giddy joy.\n\nPlease hold one of those runes up to the scrying stone to let me see. Hmmm. As I suspected, an amateur effort at best." }
WordHunterWoW_QuestEN[14430] = { title = "Hacking the Construct", description = "Now we will hack their arcane construct and use it to wreak havoc. Have you done this type of magic before, {name}? No? Hah! That makes my plan all the more delicious. Nearby you should see a formidable arcane construct they've summoned. Thanks to the runestones you gathered, we know how to communicate with it. Talk to the construct and say \"Al'teth la c'tolgar.\" Got that? Repeat it? Close enough. Report back to me and let me know what happens! ", objectives = "Speak with the Arcane Construct at the Darnassian Base Camp and utter the words of arcane power.", completion = "Haha! Hah - HA! Night elf \"mages\" fleeing their own arcane creation. Your actions have made my month, <name>. That's why we blood elves don't use arcane constructs anymore - they've been outlawed for, oh, 1500 years. It's amusing to me to watch our foes repeat the mistakes of the past. \"Mages.\" Indeed." }
WordHunterWoW_QuestEN[14431] = { title = "The Blackmaw Scar", description = "The Blackmaw furbolg that live in this area have broken rank with their Timbermaw brethren as we began to aggressively settle Azshara. They've gone wild, {class}, and harass our forces at every turn. Worse, we have seen them engaging the night elves from Talrendis on friendly terms. We cannot allow the two to ally!\n\nJust southwest of here you will find a great scar across the earth where my scouts report night elven activity. Slay them and gather any intelligence you find. ", objectives = "Slay 8 Talrendis Biologists and gather up Blackmaw Intelligence from one of the bodies.", progress = "The Blackmaw are ferocious. Were they ever to organize, they would prove to be an immense disruption to our work here.", completion = "I see... This definitely looks like a working draft of some sort of treaty. That's a worst-case scenario for us, <name>: Night elves coordinating attacks with entrenched furbolg allies.\n\nMy initial instinct - a full-out frontal assault - would only drive them into the arms of the Alliance. We will have to take a different approach..." }
WordHunterWoW_QuestEN[14432] = { title = "A Pale Brew", description = "It looks like our Alliance foes have been making headway with their Blackmaw talks by conducting negotiations in the furbolg tongue. If we're to sabotage the treaty, we're going to have to do the same.\n\nIt's not as hard as it sounds, {name}. The Blackmaw make a potent herbal tea, the fumes of which will place one in a trance-like state where you'll start speaking in tongues. The Blackmaw tongue, specifically. Go to Blackmaw Hold southwest of here and get me some samples of that briaroot brew!", objectives = "Gather up 10 samples of Briaroot Brew from outside Blackmaw Hold.", progress = "How goes the hunt? I sampled that briaroot stuff myself once, but it was too bitter, even for an old gravel-eater like myself.", completion = "Ah good, that's plenty. We'll boil this stuff up and you can bask in the fumes for a while - you'll be speaking like a furbolg in no time. Our plan is beginning to take shape..." }
WordHunterWoW_QuestEN[14433] = { title = "Diplomacy by Another Means", description = "In order to infiltrate and disrupt the Blackmaw negotiations, we'll need to know where they're happening. In Blackmaw Hold to the southwest, I suspect you'll find night elven ambassadors milling around, making preparations.\n\n<Haggrum spits on the ground.>\n\nKill them at your leisure, and search the area for important documents. Oh, and grab a set of their ambassador's robes, we'll need them.", objectives = "Gather a Blackmaw Meeting Agenda at Blackmaw Hold, and kill a Talrendis Ambassador to collect her Ambassador's Robes.", progress = "Do you have the robes? Andorel here has been whipping up some magic for us to use.", completion = "Excellent work! Let me see those documents. Hmm. Now we know exactly when and where the final negotiations will happen. Don't worry if those robes don't fit you - I've got it all worked out." }
WordHunterWoW_QuestEN[14434] = { title = "Rut'theran Village", description = "", objectives = "Are you ready to set sail, <name>?  Your people have been granted shelter in the lands of the kaldorei.\n\nDo not worry, <race>.  Your people will get a chance to fight for Gilneas again.  This time, with the full strength of the Alliance." }
WordHunterWoW_QuestEN[14435] = { title = "The Blackmaw Doublecross", description = "Andorel here has crafted a little bit of magic for me. Come, stand next to my fire, and steep yourself in the fumes from the tea. Drape the robes around you and you'll take on the appearance of a night elven ambassador to the Blackmaw.\n\nDon your disguise and speak to Andorel here in camp. He'll teleport you to the heart of Blackmaw hold, where the negotiations are to take place. Speak with Chieftain Ungarl and sabotage the treaty. Then, kill as many Blackmaw as you can on the way back!", objectives = "Wear the Ambassador Disguise and talk to Andorel Sunsworn to teleport into Blackmaw Hold. Speak with Ungarl to wreck the negotiations, then kill 4 Blackmaw Warriors and 4 Blackmaw Shaman on your way out.", progress = "If our ruse pays off, <name>, we will forever drive a wedge between the Alliance and the Blackmaw.", completion = "Victory! The Blackmaw won't know who to trust anymore.\n\nWith that delicate bit of business complete, I can orchestrate a full-on assault against those beasts without worrying about them siding with the Alliance.\n\nYou do good work, <name>. Perhaps we should place you in the Horde diplomatic corps? Hah-har!" }
WordHunterWoW_QuestEN[14436] = { title = "Dwarven Digging", description = "There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings.\n\nCollect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools.\n\nYou can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.", objectives = "Collect 5 Prospector's Picks.\n\nAt a forge, smash the Prospector's Picks to create Broken Tools.\n\nBring 5 Broken Tools to Ahmo Thunderhorn in Bloodhoof Village." }
WordHunterWoW_QuestEN[14437] = { title = "Rites of the Earthmother", description = "For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, <name>.\n\nTravel to Bloodhoof Village and seek out the Ahmo Thunderhorn. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff.\n\nTake this totem to Ahmo. He will recognize my carvings and help you on your path.\n\nFollow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.Upon completion of this quest you will gain:", objectives = "Take the Totem of Hawkwind to Ahmo Thunderhorn in Bloodhoof Village. Follow the road out of Camp Narache." }
WordHunterWoW_QuestEN[14438] = { title = "Sharing the Land", description = "{name}, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as our elders have. Yet there is one that I would ask you to seek. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land.\n\nPalemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled.\n\nWords are no longer the answer.", objectives = "Kill 15 Palemane Gnolls then return to Ahmo Thunderhorn in Bloodhoof Village.", progress = "If the Palemanes had respected the land and its inhabitants more, this conflict would have never occurred.", completion = "<name>, it is good you've taken the task seriously. Respect of the land and its creatures is important. Death and life are a circle... a necessity. One cannot exist without the other. Take time to ponder this and do well to never forget it." }
WordHunterWoW_QuestEN[14439] = { title = "Journey into Thunder Bluff", description = "You will now be revered within our great city. Any {race} worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our young leader, Baine Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.", objectives = "Speak with Baine Bloodhoof in Thunder Bluff.You will now be revered within our great city. Any <race> worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our young leader, Baine Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14440] = { title = "Rites of the Earthmother", description = "You have passed the Rites of the Earthmother and earned your place in Thunder Bluff.\n\nBut in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people.\n\nWe are hunters, <name>. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.You will receive:", objectives = "Baine Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea." }
WordHunterWoW_QuestEN[14441] = { title = "Garrosh's Autograph", description = "They say that Garrosh Hellscream is one of the greatest heroes in the Horde! When I grow up, I want to be a hero of the Horde too!\n\nDo you know Garrosh, <name>? Could you do me a favor, please? Could you get his autograph for me? I dunno how to ask him, and he probably wouldn't listen to someone like me... but you! You're an adventurer, like him! I bet he'd give you his autograph easy!\n\nPlease?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Travel to Grommash Hold in the heart of Orgrimmar's Valley of Strength to see about getting Garrosh Hellscream's autograph for your ward." }
WordHunterWoW_QuestEN[14442] = { title = "My Favorite Subject", description = "I don't know if you've noticed {name}, but this whole lab complex has gone south of cheese! I don't mind writing off all those hippogryphs, but my most prized experiment has gone missing: Subject Nine!\n\nSubject Nine is a raptor we imported from the Barrens. I wonder - is she still alive? Try checking above the main complex west of here, near the giant top secret rocket. You can't miss it.", objectives = "Locate Subject Nine somewhere near the Secret Lab complex in Azshara.", completion = "Have you come to assist me with my work? My claws are quite dexterous, but I must reluctantly confess that my arms are debilitatingly short." }
WordHunterWoW_QuestEN[14443] = { title = "The Battered Hilt", description = "This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art.\n\nThe graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Silver Covenant members would be interested in hearing about the recovery of such an artifact. Seek out their representative at Quel'Delar's Rest, south of the Argent Tournament Grounds.", objectives = "Bring the Battered Hilt to Caladis Brightspear at Quel'Delar's rest, south of the Argent Tournament Grounds.", progress = "What is it that you have there?", completion = "<Caladis takes the hilt from you and slowly turns it over in his hands.>\n\nThis seems somehow familiar, as though I should know its origins. You say you recovered this in the citadel? Most intriguing.\n\nThere are few who possess the ability to make such a blade. Perhaps they can tell us something about your find." }
WordHunterWoW_QuestEN[14444] = { title = "What The Dragons Know", description = "There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recall seeing or hearing of a sword with these markings, but that doesn't mean that all is lost.\n\nKorialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Arcanist Tybalin inside the Silver Enclave in Dalaran.", objectives = "Speak to Krasus at the top of Wyrmrest Temple.", completion = "We can't let that book remain in Sunreaver hands. If we hope to identify the sword and use it to our advantage, we have to find a way to capture the book Krasus lent them." }
WordHunterWoW_QuestEN[14445] = { title = "Farewell, For Now", description = "Our destinies are forever intertwined. There are events taking place that are reshaping our world and ultimately will destroy it. We must put an end to them before it is too late.\n\nKnow that you can always count on me, brother! We will meet again on the larger island. May you find peace until then, {name}.", objectives = "Speak with Sassy Hardwrench at the Wild Overlook on the Lost Isles.", completion = "Wow, oh wow! Is that who I think it is?\n\nYou rescued Thrall, Warchief of the Horde?!!!\n\n<Sassy gives you an appraising look.>\n\nWell, let's see about getting over to that larger island. I sure as heck don't want to swim the strait with all of those sharks down there." }
WordHunterWoW_QuestEN[14446] = { title = "Cataclysm!", description = "Hear my words, {class}!\n\nThe winds of change have gathered into a violent storm that sweeps across Azeroth.\n\nHave you the courage to face the true cause of our plight?\n\nMuster your resolve, {race}, and pray for the strength and fortune to see you through the trials that await.\n\nAn unexpected ally has issued a call for all that would hear. Peer into the Waters of Farseeing and behold the fate of the world!", objectives = "Nambria wants you to peer into the Waters of Farseeing." }
WordHunterWoW_QuestEN[14447] = { title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.\n", objectives = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14448] = { title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.\n", objectives = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14449] = { title = "The First Step", description = "What you see here is the work of the quilboar, young one. Year after year they have encroached on our village. The great cataclysm finally drove them from their dens to spread like locusts across the land, and now you see the result; my own mother, dead from their savagery.\n\nToday, you are of age. Today, you will take up your weapon and fight for the tribe, and avenge the Greatmother. Follow the path to the east, and find my son, Grull. He will lead you in our strike against the quilboar.", objectives = "Follow the path East out of Camp Narache and find Grull Hawkwind.", completion = "Welcome to your first true test as a <race>." }
WordHunterWoW_QuestEN[14450] = { title = "Random Drop Test Progressive", description = "This quest tests random drops with progressive drop percentage.", objectives = "Get 10 Progressive Widgets." }
WordHunterWoW_QuestEN[14451] = { title = "Random Drop Flat Rate", description = "This quest tests random drops with flat rate drop percentage.", objectives = "Get 10 Flat Widgets." }
WordHunterWoW_QuestEN[14452] = { title = "Rite of Strength", description = "Behold, {name}. The very presence of the Bristleback is a blight. Nothing is left in their wake but corpses and barren land. Camp Narache could become what we see here in but a few days, unless we stand and fight.\n\nThis will be your Rite of Strength; the first ceremony of a tauren brave. Go into the heart of the thornsnarl and kill Bristleback quilboar, then return to me.", objectives = "Kill 6 Bristleback Invaders.", progress = "Get in there, <name>! We won't let any past. I want you in the midst of them, scattering them left and right!", completion = "You've fought well, <name>. We may yet be saved." }
WordHunterWoW_QuestEN[14453] = { title = "A Humble Task", description = "All members of the tribe share in the harmony of life. We live together and work together.\n\nOur commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task.\n\nMy mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.All members of the tribe share in the harmony of life. We live together and work together.\n\nOur commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task.\n\nMy mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14454] = { title = "The Captured Warrior", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Brave Sharphorn, a young warrior trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save him!", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Brave Sharphorn." }
WordHunterWoW_QuestEN[14455] = { title = "Stop the Thorncallers", description = "Knowing the ways of your prey is another aspect of the hunt. In the lands they come from, quilboar live in the shade and protection of huge thorned roots. When they move, their shamans seed and grow new roots for them to live in.\n\nThese thorns mar the land and choke out other life, turning the earth around them barren.  Go to the south and stop these thorncallers before they have a chance to continue, {name}.", objectives = "Kill 7 Bristleback Thorncallers.", completion = "With the corruptors slain, the Earth Mother will mend her own wounds in due time.  The roots are not meant to thrive here, and will wither.  Balance will return." }
WordHunterWoW_QuestEN[14456] = { title = "Rite of Courage", description = "One of the first lessons you should learn, {name}, is to never underestimate your prey.\n\nWhile we were distracted by the attack on Camp Narache, more of the Bristleback swept in unnoticed and stole a cache of our rifles. You can see them to the south now, filling the air with lead.\n\nThis is your Rite of Courage: brave the hail of gunfire, hunt the Bristleback gun thieves, and bring back our rifles.", objectives = "Recover 7 Stolen Rifles from Bristleback Gun Thieves.", progress = "How many have you brought me, initiate?", completion = "Well done, <name>. Respect your prey, and the danger it carries, but never fear it. In fear, you become prey yourself." }
WordHunterWoW_QuestEN[14457] = { title = "The Sunreaver Plan", description = "One of my contacts in the Underbelly caught sight of a Sunreaver agent buying reagents from a dealer in the Black Market area. The Sunreavers normally aren't known for their interest in what goes on in the sewers, so that's a big indication they're planning something.\n\nHead into the Underbelly, find this Sunreaver agent, and take care of them. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let them get it back to Icecrown first.", objectives = "Obtain the Sunreaver Orders.", progress = "Did you find anything of use on that agent?", completion = "<Arcanist Tybalin examines the captured orders.>\n\nThe agent you intercepted was supposed to transport the Wyrmrest Tome to Icecrown, after meeting with one Magister Hathorel in Sunreaver's Sanctuary. We have to get that book, <name>, and this is our chance. It's not going to be easy, though." }
WordHunterWoW_QuestEN[14458] = { title = "Go to Adana", description = "We've struck a great blow against the quilboar here. I will stay here, and hold the line, but you need to move on.\n\nSeek Adana Thunderhorn; she has taken a few braves to the southwest to root out the rest of the Bristleback.", objectives = "Go to Adana Thunderhorn to the Southwest.", completion = "More trials lay ahead, <name>. I hope you're prepared." }
WordHunterWoW_QuestEN[14459] = { title = "The Battleboars", description = "There are more threats to be dealt with here.  The Bristleback are taming wild boars to be used against us.\n\nThese armored battleboars have been abused beyond hope of recovery; they must be put down, for our safety and their peace.  Go to the pens to the south and slay them, {name}. Return to me afterwards.", objectives = "Kill 10 Armored Battleboars.", completion = "Good work, <name>.  Those beasts could have been a greater threat than the quilboar themselves, if we had not taken action now." }
WordHunterWoW_QuestEN[14460] = { title = "Rite of Honor", description = "Chief Squealer Thornmantle leads these quilboar. It was he that set upon Greatmother Hawkwind and took her life, leading the attack on Camp Narache. He fled and hid afterwards, but we've found him. He lurks to the west within his foul den of thorns, fending off any braves we send in after him.\n\nYou've proven yourself as a brave defender of our people, {name}. Kill Thornmantle and bring his mane back to Chief Hawkwind, in honor of our Greatmother!", objectives = "Kill Chief Squealer Thornmantle.", progress = "Have you completed your trials, young one?", completion = "<Chief Hawkwind holds the mane of Thornmantle over his head.>\n\nThe Chief of the Bristleback is slain. Greatmother Hawkwind's spirit has been avenged!" }
WordHunterWoW_QuestEN[14461] = { title = "Feed of Evil", description = "We must do more than simply hunt boars here. The eyesore that has been left upon the land must be purged.\n\nTo give them a wild thirst for blood, the battleboars are force-fed raw flesh. Take this torch, and use it to burn the troughs of meat and gore to cinders.", objectives = "Use Adana's Torch to set fire to all 3 Troughs in the Battleboar Pens.", progress = "Have all the troughs been burned?", completion = "You've not only wiped the boar pens clean, but put a stop to a horrible desecration.  Well done." }
WordHunterWoW_QuestEN[14462] = { title = "Where's My Head?", description = "He's here, {name}! Captain Grunwald is a high-ranking Alliance officer from Northwatch Hold, no doubt here to coordinate an assault on Orgrimmar with his night elven allies. We have observed him entering the tower southwest of here. I want his head, {class}. I want to send it back to Northwatch to drive a wedge between our enemies!\n\nI've sent a goblin assassin, Slinky Sharpshiv, to the tower but she hasn't returned. Go find her. And get me that head!", objectives = "You've been sent to meet with the goblin assassin Slinky Sharpshiv at the base of the northern tower of Talrendis Point.", completion = "You're just in time, <class>. I'm about to launch a lightning-strike precision assassination. Let's see...\n\nExplosives? Check.\nPneumatic grapplestabber? Check.\nPortable parachute? Check.\nCrippling nerve toxin?\n\n\n\nCheck. Let's do this thing." }
WordHunterWoW_QuestEN[14463] = { title = "Horses for Duskhaven", description = "Saving the horses might've saved the rest of the town.  They have plenty of carriages in Duskhaven, but not enough horses to pull them.\n\nGo tell Mayor Armstead that the horses you saved are at her disposal.\n\nI'll get things ready and join you in a bit.", objectives = "Speak to Gwen Armstead in Duskhaven.", completion = "Excellent work, <name>.  I think I speak for everyone when I say the sooner we get out of here, the better." }
WordHunterWoW_QuestEN[14464] = { title = "Lightning Strike Assassination", description = "The base of the tower is patrolled by the Captain's elite guards. So here's what we're going to do: we're going to grapple straight up to the top, slice-and-dice the VIPs, and bail out using my portable low-altitude parachute. I'll rig the tower to explode behind us. You be sure to grab Captain Grunwald's head for Chawg. Got it?\n\nDo NOT accept this mission unless you are prepared for UNMITIGATED BADASSERY. Is that clear? ", objectives = "Talk to Slinky Sharpshiv to ascend the tower and assassinate Captain Grunwald. Collect Captain Grunwald's head.", progress = "I trust you've got good news, <name>?", completion = "I'm impressed by the cleverness of our new goblin allies, but I'm even more impressed by you, <name>. Look at the gaze of terror frozen onto the Captain's face! He never saw your attack coming. Imagine the fear this will cause in Northwatch when they see what happened to one of their precious officers in night elf lands.\n\nWell done, <class>. Our assault proceeds..." }
WordHunterWoW_QuestEN[14465] = { title = "To Greymane Manor", description = "It's time for everyone to head to safety.  That includes you, {name}.  Head to Greymane Manor, the others will be there shortly.\n\nDon't worry about me, I'll make sure that everyone makes it out of here in one piece.  Yes, even the few ferals we have in the pens.\n\nOnce you get there, speak to Queen Greymane about the gravity of the situation.", objectives = "Speak to Queen Mia Greymane inside Greymane Manor.", completion = "<name>.  I've heard much about you.\n\nI understand you were crucial in my family's survival during the outbreak in Gilneas City." }
WordHunterWoW_QuestEN[14466] = { title = "The King's Observatory", description = "You ought to speak to Genn.  He's been locked up in his observatory ever since this ordeal started.\n\nI'm sure he's working on a plan for his people.  He's a very stubborn individual.", objectives = "Speak to King Genn Greymane in the observatory inside Greymane Manor.", completion = "There you are, <name>.  I've been expecting you.\n\nI got word of your recovery and... wait -- do you feel that?" }
WordHunterWoW_QuestEN[14467] = { title = "Alas, Gilneas!", description = "", objectives = "Look, <name>!  Look at what's become of Duskhaven!\n\nLook at what's become of the last safe place in Gilneas!" }
WordHunterWoW_QuestEN[14468] = { title = "Another Warm Body", description = "Oh have I got a deal for you! Immerse yourself in foreign cultures, go on epic adventures, blow things up, and get paid to do it! Sound too good to be true? Well it's not - this is what we do!\n\nIf you're interested, head over to Gallywix Defense Post on Forlorn Ridge to the north and look for Commander Molotov.", objectives = "Report to Commander Molotov on Forlorn Ridge.", completion = "Latest recruit, eh?\n\nI'll make this short and sweet. We're under contract to keep the naga in the ruins from reaching Gallywix or his property. You handle whatever we ask of you, and I'll see to it that you get paid when all of your rounds are complete.\n\nWelcome to the Bilgewater Battalion." }
WordHunterWoW_QuestEN[14469] = { title = "Hand-me-downs", description = "First things first - we need more supplies for you and the other new recruits. There are some perfectly good standard issue packs on the bodies of our last round of recruits, in the minefield to the north.\n\nTaking their lessons to heart, I'd recommend you avoid stepping on mines yourself.", objectives = "Retrieve 12 Military Supply Packs from the central minefield.", progress = "Nothing wrong with recycled goods.", completion = "You're a light-footed bugger, aren't ya? Good work.\n\nHere are a few of the supplies to keep you lively." }
WordHunterWoW_QuestEN[14470] = { title = "Military Breakthrough", description = "We've lost contact with Sergeant Dynamo, stationed at the next ridge to the north of the central minefield. They were probably overrun.\n\nHe had our last SFG. Go over there and get it back. Clear out any naga that have broken through while you're there.", objectives = "Kill Warlord Krellian and recover the SFG.", progress = "Where's my rocket launcher, recruit?", completion = "Quick work there, recruit.\n\nShe's a beaut, isn't she? Assembled her myself. I've got special plans for this baby." }
WordHunterWoW_QuestEN[14471] = { title = "First Degree Mortar", description = "Hey bud! Like explosions? Of course you do. Who doesn't like explosions?!\n\nI've got mortars set up on the ridge to the east to hold the naga back. Go forth, recruit. Mortar them... mortar them all! Ahahahah.", objectives = "Use a Goblin Mortar to slaughter 60 Spitelash Attackers.", progress = "KABOOM!", completion = "Can you believe they PAY us to do this?" }
WordHunterWoW_QuestEN[14472] = { title = "In The Face!", description = "The naga are using those giants to stamp paths through our minefields. Time to put that SFG to use!\n\nHead over to the entrance to the southern minefield - I think you can figure out the rest.", objectives = "Use an SFG to kill an Enslaved Son of Arkkoroc in the southern minefield.", completion = "BAM! In the face! Nice shot, kid." }
WordHunterWoW_QuestEN[14473] = { title = "It's Our Problem Now", description = "Looks like those monkeys will steal anything! Those thieving little monsters have driven the teraptor matriarch into a frenzy by stealing her eggs. Worse yet, the eggs have started to hatch! We've got hungry teraptor hatchlings running around all over the place, looking to make a quick meal out of us!\n\nWe didn't start this, but it's our problem now. You'll have to head into the jungle and kill those hungry teraptor hatchlings before they kill us all.\n", objectives = "Slay 6 Teraptor Hatchlings.", completion = "Let's just hope we don't have to deal with their mommy later. That would be very bad." }
WordHunterWoW_QuestEN[14474] = { title = "Goblin Escape Pods", description = "{name}, I'm sorry, I thought you were dead!\n\nThis is just crazy. We sailed into a fight between the Alliance and Horde!\n\nYou know, our brothers and sisters still need to be rescued.\n\n<He points out all of the escape pods in the water around you.>\n\nI think I'm going to sit here a while longer and catch my breath. Can you swim around and let them out? Take my pair of thermohydratic flippers so you can get around faster.\n\nLet Sassy know that I'll swim in shortly.", objectives = "Rescue 6 Goblin Survivors.", completion = "Oh, thank heavens that you survived, <name>! I thought for sure that you'd drowned when I saw you go over the side!\n\n\n\nLook at all of these folks you saved!" }
WordHunterWoW_QuestEN[14475] = { title = "Grounded!", description = "Do you see a problem with these wind riders, {name}? They're not riding the wind! Every flight I send aloft gets peppered by night elf snipers.\n\nTalrendis sharpshooters are holed up in the southern-most tower, against the mountains. I sent one of these little goblin scrubs to take care of the tower, but I haven't heard a word from him. Go find Bombardier Captain Smooks and beat him with the hurry stick!", objectives = "Find Bombardier Captain Smooks at the southernmost night elf tower at Talrendis Point.", completion = "Reinforcements, at last!" }
WordHunterWoW_QuestEN[14476] = { title = "Rigged to Blow", description = "This tower was out of cannon range, so I thought we'd blow it up the old-fashioned way - in person. We set all the main charges but the guards fought us back before we could arm the detonators.\n\n{name}! Get up there and arm the three detonators we placed around the base of the tower. Those things are wired into a pack of thermals I set up along the spine... It'll be some show!", objectives = "Arm the three Explosive Charges located around the base of the southern-most tower at Talrendis Point.", progress = "Did you get 'em? Did you get all three?", completion = "Sweet. Let's torch this banana stand!" }
WordHunterWoW_QuestEN[14477] = { title = "Push the Button!", description = "Lemme check the connections... and we're set. You do the honors, {name}. Push it. Push the button!\n\nPush the button, {name}!\n\nAfter the fireworks, go tell Kroum back at Valormok that his skies are clear.\n\nPush the button!", objectives = "Detonate the explosives!", completion = "Yes, let them burn! Let them burn through the night, so that their flaming tower will light the battlefield beneath us as we rain terror upon their heads.\n\nThank you, <name>. Stay close: the invasion is about to begin..." }
WordHunterWoW_QuestEN[14478] = { title = "Operation Fishgut", description = "The Bilgewater Battalion are now accepting recruits for OPERATION FISHGUT.\n\nWages will consist of 1 gold piece at the time of operation completion for all active soldiers in good standing. All wages will be forfeited in the event of death. A fee of 20 silver will be charged for any resurrections performed in the line of duty.\n\nAll recruits are to report for duty directly to Commander Molotov under the main cannon.", objectives = "Report for active duty to Commander Molotov under the main cannon in Bilgewater Harbor.", completion = "Welcome back to duty soldier. Good to have you back." }
WordHunterWoW_QuestEN[14479] = { title = "There Are Many Like It", description = "Enough small talk. Get off your butt and onto a rocket, soldier.\n\nAnd remember, you don't get paid if you're dead.", objectives = "Use a rocket to reach the Shattered Strand, and then report for duty to Lieutenant Drex.", completion = "Bumpy ride?" }
WordHunterWoW_QuestEN[14480] = { title = "Extermination", description = "We're sending you in there to clean up this naga infestation. Lethal force has been authorized.\n\nGob Squad will be backing you up on this one, so it should be a cakewalk.", objectives = "Kill 30 Spitelash Naga in the Ruins of Eldarath.", completion = "Your name's getting around... nearly Gob Squad status some would say. You're a vicious one." }
WordHunterWoW_QuestEN[14481] = { title = "Into The Abyss", description = "The Horde and Alliance are locked in battle with one another in the seas to the west.\n\nBelow them, a great host of enemies prepares to carry out a plan that could be the undoing of us all.\n\nI am sending you to speak with the admiral of the alliance forces. Share with him the vision you have seen. Convince him to focus his attention on the true threat below, before it grows too late...\n\nTo gain audience with the admiral, you must first enlist with the recruiter at the harbor.", objectives = "Nambria wants you to speak to Recruiter Burns at Stormwind Harbor.The Horde and Alliance are locked in battle with one another in the seas to the west.\n\nBelow them, a great host of enemies prepares to carry out a plan that could be the undoing of us all.\n\nI am sending you to speak with the admiral of the alliance forces. Share with him the vision you have seen. Convince him to focus his attention on the true threat below, before it grows too late...\n\nTo gain audience with the admiral, you must first enlist with the recruiter at the harbor.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[14482] = { title = "Call of Duty", description = "Citizen!\n\nAs you may have heard, the Horde's attacking just offshore. The fighting's been fierce and relentless.\n\nWe need every able body out there repelling the enemy!\n\nReport to the northernmost dock at once for transport to the battle.\n\nOh, and our official warships are... err, a bit late in their scheduled return. Don't worry though, we've commissioned mercenary vessels to serve in the meantime.\n\nHurry along now, {class}. Stormwind needs you!", objectives = "Ride the mercenary ship to battle.", completion = "Not exactly the battle you had anticipated, I'll wager. But a battle nonetheless, as you shall soon see...." }
WordHunterWoW_QuestEN[14483] = { title = "Something is in the Air (and it Ain't Love)", description = "The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!", objectives = "Bring the Faded Lovely Greeting Card to Detective Snap Snagglebolt in Orgrimmar.", progress = "Did you take care of those no-good scheming villains?", completion = "What've you got there?\n\nOh hey, this is big. Real big. Most of the crazy details in one little package. Thanks - you really helped us reel this all in. Good working with ya." }
WordHunterWoW_QuestEN[14484] = { title = "Head of the Snake", description = "They taught us at officers camp to always cut off the head of the snake. Seemed dumb considering we never fought any snakes, but I guess it kind of makes sense now.\n\nTake your men in there and kill Lord Kassarus.", objectives = "Kill Lord Kassarus in the Temple of Zin-Malor.", completion = "Glad you're on our side, soldier." }
WordHunterWoW_QuestEN[14485] = { title = "Ticker Required", description = "Our best demo-man, Ticker, is on assignment with the Gob Squad. He's got WAY more than enough explosives for all the runestones in the ruins.\n\nAll you have to do is get him there and keep him covered - he'll handle the rest.", objectives = "Bring Ticker into the ruins and cover him as he sets up bombs at 3 of the Spitelash Runestones.", progress = "Ticker's a man after my own heart. Couldn't be prouder.", completion = "The hope is that that cuts off a major source of their magic. The truth is, we don't really have a clue. Who can pass up an opportunity to blow some stuff up though." }
WordHunterWoW_QuestEN[14486] = { title = "Handling the Goods", description = "Hey there, buddy. Want to make a quick buck?\n\nBring me back any highborne tablets you find in the ruins.", objectives = "Collect 12 Highborne Tablets from the Ruins of Eldarath.", progress = "The blood elves eat those tablets up. Top dollar.", completion = "Excellent. Here's your cut.\n\nGood doing business with you." }
WordHunterWoW_QuestEN[14487] = { title = "Still Beating Heart", description = "Commander Molotov found a party at the Secret Lab willing to act as buyer for the artifact that you scouted out earlier.\n\nUndoubtedly, it's still in the center of the ruins with the High Priestess, where you initially spotted it. Get it back here undamaged, soldier.", objectives = "Recover the Heart of Arkkoroc from the center of the Ruins of Eldarath.", progress = "I love it when people leave priceless artifacts just lying around.", completion = "Hahah! It's HUGE!\n\nWe'll have you take it back to Uncle Bedlam as soon as everything's cleaned up here and you're ready to go." }
WordHunterWoW_QuestEN[14488] = { title = "You've Been Served", description = "You made it, huh? Good. I've been waiting for help. No time like the present to act, right?\n\nTake this kit and head deeper inside to serve papers to the leader of that scumbag chemical company, Hummel. The paper's inside. So's a little something to protect you from any chemical tricks they might pull. Use one of the neutralizers when the time comes, all right?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Serve the Court Subpoena to Apothecary Hummel in Shadowfang Keep." }
WordHunterWoW_QuestEN[14491] = { title = "The Restless Earth", description = "Until recently, a group of dwarves intruded on our lands to the west, carving the earth apart senselessly to search for treasure.  When the very earth itself tore apart, the spirits of the land they had abused rose up and took their revenge.\n\nThe agitated earth spirits still roam the former dig site, {name}.  We must offer them appeasement.\n\nTake this drum with you to the west and play to the spirits.  The rhythm may calm their fury and confusion.", objectives = "Use the Drums of the Soothed Earth to calm 6 Agitated Earth Spirits.", completion = "The land is clearly still in great upheaval if it took such effort to calm.\n\nRemember this, <name>.  Do not forget seeing the fate of those who would scar the Earth Mother." }
WordHunterWoW_QuestEN[20438] = { title = "A Suitable Disguise", description = "Getting you inside the Sunreaver's Sanctuary will be tougher than it appears. Only those who possess Sunreaver tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work.\n\nOn the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.", objectives = "Obtain a Borrowed Tabard from Shandy Glossgleam.", progress = "Was Shandy able to help you get a Sunreaver tabard?", completion = "I knew Shandy would find a way to come through for us. Let me get this enchanted and ready for you to use. The sooner you get done with the tabard, the sooner we can get it back to Shandy and the better the chances that its owner will never have missed it." }
WordHunterWoW_QuestEN[20439] = { title = "A Meeting With The Magister", description = "I've placed an enchantment on the tabard that should allow you to slip past the Sunreaver Sanctuary's defenses for a short period of time. You should have enough time to find your way into The Filthy Animal and meet up with the Sunreaver contact there, one Magister Hathorel.\n\nObtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest while your disguise holds, and return it to me.", objectives = "Retrieve the Ancient Dragonforged Blades tome from Magister Hathorel.", progress = "Have you recovered that book?", completion = "Excellent work. Now that this is in our hands, we must get it to Caladis Brightspear as soon as possible. We can't risk the book falling back into Sunreaver hands.\n\nI'll ensure that Shandy Glossgleam gets his tabard back without incident, along with a healthy reward for his help." }
WordHunterWoW_QuestEN[20440] = { title = "Poison Water", description = "Our sacred wells have been tainted, and I will need your help to fix this.\n\nTo cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual.\n\nFirst we will create a cleansing totem for the Winterhoof Water Well.  To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons.  They are to the southwest.\n\nReturn to me with the paws and talons, {name}.", objectives = "Collect 6 Prairie Wolf Paws and 4 Plainstrider Talons.", progress = "Do you have the paws and talons, <name>?", completion = "You have done well, <name>.  I will take these and bind their power into a totem of cleansing." }
WordHunterWoW_QuestEN[20441] = { title = "Rite of Vision", description = "Again, be sure you are ready to leave Bloodhoof Village behind, {name}. The next step on your journey will take you far from here.\n\nYour path continues to lead onward, across the fields of Mulgore, the eyes of the Earth Mother on you at all times. When you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, your eyes will be opened, and the spirits will guide you.", objectives = "Consume the Water of Vision in front of the tribal fire in Bloodhoof Village.", completion = "Be not afraid, <name>. You have successfully passed the Rite of Vision." }
WordHunterWoW_QuestEN[23733] = { title = "Rites of the Earthmother", description = "Today, you have undertaken a rite of passage far more difficult than we ask of most of our youths. Be proud. Now, it is time for you to continue on your journey.\n\nTo the west, beyond our burial ground, you will find a path winding up the mesa. Follow it to the top, and speak with Dyami Windsoar.\n\nWalk with the Earth Mother, friend. You will always be welcome here.", objectives = "Speak to Dyami Windsoar atop Fargaze Mesa.", completion = "If you are prepared to leave Camp Narache behind, I will help call the spirits to guide you onwards." }
WordHunterWoW_QuestEN[24215] = { title = "Rite of the Winds", description = "Look, {name}. The rolling plains of Mulgore stretch before you: our home, the cradle of the Earth Mother. Here she provides us with all we could ever need, a peaceful and verdant land. This is what you will fight to protect.\n\nYour journey will take you far beyond her sheltering arms, to the farthest and cruelest regions of this world, and beyond.\n\nBelow us is Bloodhoof Village. The first step on your true path begins now. Drink deep of the Water of Vision, and let the spirits guide you onward.", objectives = "Drink the Water of Vision.\n\nProvided item:", completion = "Welcome to Bloodhoof Village, hero.  I am glad the spirits have guided you safely here." }
WordHunterWoW_QuestEN[24216] = { title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, <name>.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24217] = { title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, <name>.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24218] = { title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24219] = { title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24220] = { title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, <name>.  We cannot allow the Horde scum to secure the resources that are rightfully ours!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24221] = { title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, <class>, go to Arathi Basin and crush the enemy.  Victory to the Horde!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24222] = { title = "Call to Arms: Eye of the Storm DEPRECATED", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!You will receive:", objectives = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran,  or Shattrath." }
WordHunterWoW_QuestEN[24223] = { title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, <name>.  We cannot allow the Horde scum to secure the resources that are rightfully ours!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24224] = { title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24225] = { title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, <name>.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24226] = { title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, <class>, go to Arathi Basin and crush the enemy.  Victory to the Horde!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24227] = { title = "DEPRECATED", description = "The fight against the Horde knows no boundaries, <name>.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.You will receive:", objectives = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[24426] = { title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, <name>.  Earn great honor by heeding the call of the brave Frostwolf warriors.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath." }
WordHunterWoW_QuestEN[24427] = { title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, <name>, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath." }
WordHunterWoW_QuestEN[24428] = { title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Zardeth of the Black Claw.", objectives = "Take the Head of Onyxia to Zardeth of the Black Claw in the basement of the Slaughtered Lamb.", progress = "By Nozdormu's teeth!", completion = "What? How did you get this? Isn't she... Never mind the details, I suppose. You'll be wanting one of these baubles as recompense, no doubt." }
WordHunterWoW_QuestEN[24429] = { title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Arnak Fireblade.", objectives = "Take the Head of Onyxia to Arnak Fireblade in the Cleft of Shadow.", progress = "What is the meaning of this?!", completion = "You've brought me the head of someone who is... No, best not to think about it too hard. You'll be wanting recompense for your heroic deeds, no doubt." }
WordHunterWoW_QuestEN[24430] = { title = "Blacken the Skies", description = "{name}! Give us a hand here, will ya? Gorsch here had a bad experience at the all-you-can-eat seafood joint back in town, and now we're short a pilot.\n\nMy job was to take out those elven glaive throwers before they cut our air units to ribbons. Hop on this wind rider and take to the skies! One of my bombardier buddies will ride with you and bomb the targets at your command.\n\nAnd hey! Chuck a bomb straight at the night elven command center - the large building south of here, beside the bridge. Glorious!", objectives = "Mount a Grounded Wind Rider and fly over Talrendis Point. Destroy 6 Talrendis Glaive Throwers and bomb the Command Center.", progress = "More bombs. More bombs!", completion = "Oh yeah! I love the smell of freshly-cratered dirt!\n\nWord around camp is that the elven front line is collapsing back toward the river. Talk to Chawg and see if there's anything you can do to help seal the deal." }
WordHunterWoW_QuestEN[24431] = { title = "Waterlogged Recipe", description = "This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....", objectives = "Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.", progress = "Wine is only as fine as the person drinking it, I always say.", completion = "This is quite a find, <name>.  I can't have you selling this to anyone else, so I'm willing to offer generously." }
WordHunterWoW_QuestEN[24432] = { title = "Sea Legs", description = "Welcome to The Briny Cutter, {class}.\n\nI am Erunak, the last surviving passenger of this once-proud vessel.\n\nI'm afraid your travails have only just begun. The naga have been attacking here relentlessly.\n\nYou're not equipped to be of much help down here yet, but I can remedy that.\n\nJust outside this ship live a special breed of starfish. Bring me some of them along with a conch shell. I'll prepare an enchantment that should help to increase your chances of survival.", objectives = "Erunak in The Briny Cutter wants you to bring him 3 Saltwater Starfish and a Conch Shell from Seafarer's Tomb.", progress = "It is good to see that you're still alive, <race>.\n\nHave you found the items I require?", completion = "Here you are, <class>. With this you should find maneuvering in the sea to be nearly effortless. \n\nNow we must get to work. There is much to be done in little time." }
WordHunterWoW_QuestEN[24433] = { title = "Let Them Feast on Fear", description = "Our grunts are strong but have no initiative. They're fighting toe-to-toe on the front lines. But an independent {class} like yourself - well, someone like you can slip behind the lines and cause some real havoc deep within the enemy redoubt.\n\nCut a swath of destruction through the heart of Talrendis, {name}! Slay our foes in territory they think is secure, leaving blood and fear in your wake.", objectives = "Fight your way across Talrendis Point, slaying 12 Talrendis Defenders and 6 Talrendis Sentinels.", completion = "Lok'tar ogar, <name>! As they discover the bodies of their comrades they will learn that no place is safe from the fury of the horde, and their will to fight will crumble." }
WordHunterWoW_QuestEN[24434] = { title = "Commando Drop", description = "Are you sensitive to the tremors of the local ley-lines, {name}? I can feel the occasional thrum, like the plucking of a string. It's the kind of resonance I'd expect from a long-range summoning spell. The Lorekeepers in Talrendis, with their laughably primitive magics, are trying to summon in backup from Darnassus.\n\nWe can use this to our advantage, {name}. If you can compromise their summoning stone, we can teleport a crack team of commandos behind enemy lines.\n\nLocate the summoning stone in Talrendis!", objectives = "Slay 5 Talrendis Lorekeepers and locate a Lorekeeper Summoning Stone somewhere within Talrendis Point.", progress = "If Andorel's instructions are to be believed, it should be easy to refocus the stone's energies.", completion = "Images of a great and distant tree flood your mind. Your stomach lurches as you reorient the stone, briefly filling your senses with visions of a fiery portal, a towering mountain, a frigid wasteland, and a terrible scar across the earth.\n\nAfter a moment, the magical energies of the stone calm, and you feel you are but a step away from Valormok. Andorel's invasion can begin..." }
WordHunterWoW_QuestEN[24435] = { title = "Mop Up", description = "There are a lot of naga left on this beach. Looks like you have some wet work ahead of you, son.", objectives = "Kill 12 Spitelash Naga on the Shattered Strand.", completion = "Good clean fun." }
WordHunterWoW_QuestEN[24436] = { title = "Halo Drops", description = "We've got \"soldiers\" all over the beach trying to get out of their work by dying on us. Find the slackers and use this flaregun to call in a priest to take care of the situation.\n\nWe can't have men thinking they can get off that easy.", objectives = "Call in Airborne Priests at the bodies of 8 Wounded Soldiers on the Shattered Strand.", completion = "Fine job there, bud. We'll have this beach cleaned up in no time." }
WordHunterWoW_QuestEN[24437] = { title = "First Come, First Served", description = "There's some gorgeous beach front property along the shore. I can market this stuff for 10 times what construction will cost me.\n\nThe prime spots are that naga pagoda to the south, the tower right next to the water, and the ruins at the far northern end of the beach. I'll give you some coin if you claim them for me before the fighting clears out.", objectives = "Plant Ruckus' Territorial Claim Flag next to the prime real estate locations along the Shattered Strand.", completion = "Hah hah! Brilliant. Right fine job there, boy." }
WordHunterWoW_QuestEN[24438] = { title = "Exodus", description = "We have no choice, {name}.  We must move further inland.\n\nI don't like it one bit, but we're vulnerable here.\n\nReturn to the stables below the manor.  Let's get everybody on carriages and send them eastbound.  I pray it's not too late.", objectives = "Board a carriage below Greymane Manor.", completion = "Thanks for stopping, <name>.  Our carriage got hit pretty bad.\n\nThe one in front of us got it worse." }
WordHunterWoW_QuestEN[24439] = { title = "The Conquest of Azshara", description = "{name}! Was it you who piloted the wind rider who bombed the command center? It was a direct hit!\n\nMy scouts tell me that you gravely wounded Jarrodenus, flight master of the night-elven skychasers and de facto commander of the opposition.\n\nThe opportunity to strike is now - I don't have time to assemble a full assault. Rush the command center building and kill Commander Jarrodenus before his backup arrives. Bring me his head... and Azshara is ours!  ", objectives = "Slay Commander Jarrodenus in Talrendis Point and collect his head.", progress = "Is Jarrodenus still barking orders, or have you removed from him the burden of his head?", completion = "...Then it is done!\n\n<Chawg surveys the battlefield.>\n\nThere are still pockets of resistance around our camp, but this rearguard action appears to be masking a full-fledged retreat to Ashenvale. Azshara is ours!\n\nThe Warchief will hear of this victory and your part in it. But we will surely need the help of a <class> like you elsewhere. Be sure to speak with Kroum here in camp before you leave." }
WordHunterWoW_QuestEN[24440] = { title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  The well is to the southeast, but be warned: whoever did this may still be there, laying in wait.\n\nThis may prove very dangerous, {name}.  Be careful...but do not let the defilers of our well escape.", objectives = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well.", completion = "The Grimtotem...\n\n<Mull scowls.>\n\nI'd hoped to see the end of my days before <race> attacked other <race> senselessly on the very plains of Mulgore.  But be proud, <name>.  You have done a great thing for the land, and for our people." }
WordHunterWoW_QuestEN[24441] = { title = "Thunderhorn Totem", description = "There is more work to be done.  We must create a new totem to cleanse the Thunderhorn Well.\n\nYou must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me.\n\nYou will find the prairie stalkers and flatland cougars to the east and west.", objectives = "Collect 6 Stalker Claws and 6 Cougar Claws.", progress = "<name>, do you have the claws I sent you to gather?  The Thunderhorn Water Well grows more tainted with each passing hour!", completion = "Thank you, <name>.  The purity with which these beasts hunt is vital in the creation of the next cleansing totem.\n\nThe Thunderhorn Well is a symbol of my own tribe, and to know it is being desecrated by our own kind raises a fury in me I haven't felt for years." }
WordHunterWoW_QuestEN[24442] = { title = "Battle Plans Of The Kvaldir", description = "Looking over the captured attack plans, you find a map of the Eastern Kingdoms and Kalimdor with major settlements marked. Reading over the orders, you learn that  Kvaldir captains have drafted plans for a series of devastating raids.\n\nAccording to the orders, the attacks are to begin after Mistcaller Yngvar \"consults the Heart of the Mists.\" Perhaps you could delay the attacks by capturing the omen from the Mistcaller's Cave on the western side of Hrothgar's Landing and notify Justicar Mariel Trueheart.", objectives = "Recover the Heart of the Mists and bring it and the Kvaldir Attack Plans to Justicar Mariel Trueheart at the Argent Tournament Grounds.", progress = "What is it that you've found, <name>?", completion = "<Mariel accepts the orders and the captured seeing crystal and examines both.>\n\nGood work, <name>, and quick thinking. I'm sure the theft of this trinket won't slow them down for long, but I think you've bought us time to warn the leaders of the Horde and Alliance about the impending attacks." }
WordHunterWoW_QuestEN[24443] = { title = "The Captured Hunter", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Honu Staghunter, a young hunter trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Honu Staghunter." }
WordHunterWoW_QuestEN[24444] = { title = "The Captured Shaman", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Miira Thunderhoof, a young shaman trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!\n", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Miira Thunderhoof." }
WordHunterWoW_QuestEN[24445] = { title = "The Captured Druid", description = "It's fallen to some of our youngest to defend our camp, {name}, and many of our bravest apprentices are out there as we speak, fighting the quilboar.  I fear for their safety...\n\nPlease, look for the young druid Keshu Treehoof to the east, deep within quilboar territory. If you find her and the other apprentices alive, they may be able to help you.", objectives = "Find Keshu Treehoof." }
WordHunterWoW_QuestEN[24446] = { title = "The Captured Sunwalker", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Bowe Dawnhorn, a young Sunwalker, away in one of their foul cages. Please, find a key on one of the quilboar's bodies and go save him!", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Bowe Dawnhorn." }
WordHunterWoW_QuestEN[24447] = { title = "The Captured Seer", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Seer Skyhoof, a young seer, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!", objectives = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Seer Skyhoof." }
WordHunterWoW_QuestEN[24448] = { title = "Field Promotion", description = "Commander Molotov sent word directly that you should be dispatched to our forward post. We're preparing to send squads into the ruins to rout the naga and recover the artifact, and he would like you to lead one of them.\n\nGet to the northwest corner of the beach and follow the path up to our forward post.", objectives = "Report to Captain Tork at the forward post in the Ruins of Eldarath.", completion = "<name>! You made it in one piece, good.\n\nWe've got a lot of work for you to handle for us inside the ruins, but we're sending you in with the best to take care of it. You're working with GAMA Force now, Goblin Army: Mergers and Acquisitions. Molotov says you can handle it - that's all I need to hear." }
WordHunterWoW_QuestEN[24449] = { title = "Shore Leave", description = "We're looking pretty good here at this point. It's definitely been a pleasure working with you, soldier.\n\nIf you're ready to take the artifact back, we've got a Gyrocopter ready to take you back to Bilgewater Harbor so that you can deliver it to Uncle Bedlam personally.", objectives = "Bring the Heart of Arkkoroc to Uncle Bedlam in Bilgewater Harbor.", progress = "Ah, the man of the hour!", completion = "And you come with the artifact! The operation was a success then. Mergers and Acquisitions can definitely handle themselves. This thing will fetch quite a pretty penny.\n\nAnd you - I heard you did some impressive work down there. You may well have cut-down expenses by 10% single-handedly. That's the kind of smarty businessman I want in my army!\n\nHere are your wages, as promised. And a little something extra too - I hope you like it." }
WordHunterWoW_QuestEN[24451] = { title = "An Audience With The Arcanist", description = "I've placed an enchantment on the tabard that should allow you to slip past the Silver Enclave's defenses for a short period of time. You should have enough time to find your way up to the top level of the Silver Enclave and meet up with the Silver Covenant's man there, known as Arcanist Tybalin.\n\nWhile disguised, obtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest, and return the book to me.", objectives = "Retrieve the Ancient Dragonforged Blades tome from Arcanist Tybalin.", progress = "Did you recover the book from Wyrmrest?", completion = "Excellent work. Now that this is in our hands, we must get it to Myralion Sunblaze as soon as possible. We can't risk the Silver Covenant taking the book from us again.\n\nI'll get that tabard back to Shandy and see that he's well compensated for his assistance. Once the book is in Myralion's hands, the Silver Covenant won't be a threat anymore." }
WordHunterWoW_QuestEN[24452] = { title = "Profitability Scouting", description = "Things seem to be quieting down a bit. Gallywix will probably keep forking out cash to keep us posted here, but I have a feeling we might be able to milk a bit more out of the deal.\n\nNaga and Sea Giants aren't normally friends, so the naga must be controlling them somehow. Take this stealth field generator, get in those ruins, and let me know if you find something that looks really pricey.", objectives = "Use the stealth field generator to infiltrate the Ruins of Eldarath and identify the Heart of Arkkoroc.", progress = "Our stealth field generator has the same acronym as our rocket launcher. Probably poor planning on our part.", completion = "Hahah! Sweet deal. I'll get the ball rolling on this. All I need now is to find a buyer and get the go-ahead from Uncle Bedlam.\n\nHere are your wages for your work here. Excellent work, soldier." }
WordHunterWoW_QuestEN[24453] = { title = "Private Chat", description = "Look... one last favor before you run off.\n\nPrivate Worcester is still back at that tower \"recruiting.\" Go and let him know that we're good to pack it up now. Back to town.\n\nPleasure working with you, recruit.", objectives = "Speak to Private Worcester at the Orgrimmar Rocketway Exchange.", completion = "What?! I got left out of the action completely? Are you serious?\n\nAlright, alright... no shooting the messenger. Thanks for the news, bud. Maybe I'll see you back at town." }
WordHunterWoW_QuestEN[24454] = { title = "Return To Caladis Brightspear", description = "We must get this book to Caladis Brightspear immediately. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at keeping the Sunreavers at bay.\n\nTake it with you to Quel'Delar's rest, south of the Argent Tournament Grounds in Icecrown. Caladis and the sword will be waiting. The sooner we can identify the blade, the sooner we can claim it.", objectives = "Bring Ancient Dragonforged Blades to Caladis Brightspear at Quel'Delar's Rest.", progress = "We've been expecting your return. What has kept you?", completion = "<Caladis accepts the heavy book and begins leafing through it.>\n\nI knew the symbols on the blade were familiar. The weapon was most certainly forged by the dragons and gifted to one of the mortal races, but which blade is this, and how did it come to rest in Icecrown?" }
WordHunterWoW_QuestEN[24455] = { title = "Rapid Deployment", description = "You will be reporting for active duty immediately. Captain Desoto is overseeing deployment just down the ramp at the rocket launch station.\n\nMake us rich, soldier. Dismissed!", objectives = "Report to Captain Desoto in Bilgewater Harbor for deployment.", completion = "Nice to meet you soldier. Commander Molotov speaks highly of you." }
WordHunterWoW_QuestEN[24456] = { title = "Thunderhorn Cleansing", description = "The Grimtotem are a tribe that believe all of Kalimdor should belong to the tauren alone. Their hate and anger led to a corrupting thirst for power. Magatha, their leader, poisoned our High Chieftain, Cairne Bloodhoof, and attempted to take Thunder Bluff for herself; she was defeated, and the Grimtotem exiled.\n\nNow they seek to ruin Mulgore itself as they are driven out. Quickly, {name}, you must go to the Thunderhorn Water Well in the north and perform the ritual!", objectives = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well.", completion = "You've done great honor for both me and my ancestors today.  Please, take this with my gratitude." }
WordHunterWoW_QuestEN[24457] = { title = "Rite of Vision", description = "I cannot thank you enough for cleansing my tribe's well, {name}, and for fighting the savage Grimtotem to do it. But there is more to be done, and it is time for your journey to lead you beyond Bloodhoof Village.\n\nZarlman Two-Moons stands by the fire in the north end of the village.  Go speak with him and learn of the next ritual you must undertake.", objectives = "Speak with Zarlman Two-Moons in Bloodhoof Village.", completion = "I sensed you would be coming to me, <class>. I can always recognize one who is trying to pass the Rites of the Earthmother." }
WordHunterWoW_QuestEN[24458] = { title = "A Hello to Arms", description = "{name}, I've taken the purified sample of Azsharite you rescued from the lab and I've weaponized it. If my calculations are correct, it will detonate with enough force to level a city.\n\nIf I'm wrong, we may cleave the planet in two.\n\nThe only way to find out is a test-firing! Deliver the Azsharite core to the giant cannon in Bilgewater and report to Bleenik Fizzlefuse. My pilot-for-hire Friz Groundspin here can give you a ride.\n\nI'll follow... from a safe distance.  ", objectives = "Deliver the Armed Azsharite Core to Bleenik Fizzlefuse at Bilgewater Harbor. Speak with Friz Groundspin for a free airlift.", progress = "What's that you've got there - did Grapplehammer send you?", completion = "Oh! This is it! It's the big one!\n\n<Fizzlefuse calls out to his workers.>\n\nWe're in business boys!" }
WordHunterWoW_QuestEN[24459] = { title = "Morin Cloudstalker", description = "You may have heard of the Venture Company. They are a goblin \"cartel\", something like a tribe.\n\nWhile one of these cartels has joined us in the Horde, the Venture Company is loyal only to greed. These greedy goblins and their workers have tried to exploit the resources of Mulgore before, to little success.\n\nOne of our outrunners, Morin Cloudstalker, has gone to check the remains of one of the goblin caravans. If you wish to help him, follow the road out of the village to the east.", objectives = "Find Morin Cloudstalker to the east of Bloodhoof Village.", completion = "Well met. If Ahmo has already explained the minor quibbles of what kind of goblin we'll be driving from our lands, let's get to work." }
WordHunterWoW_QuestEN[24460] = { title = "Out of Order", description = "Hey there <name>, I need you to solve the Cataclysm. Go hunt me some zombies.  You are |5<race>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Paul's Test Questgiver wants you to kill zombies." }
WordHunterWoW_QuestEN[24461] = { title = "Reforging The Sword", description = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.\n\nIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar.\n\nYou must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.", objectives = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer and use them to make the Reforged Quel'Delar.", progress = "Were you able to reconstruct Quel'Delar?", completion = "You have remade the blade of Quel'Delar, although Blood-Queen Lana'thel proclaimed we could not! The blade must still be tempered, but she and her master will not stand in our way!" }
WordHunterWoW_QuestEN[24462] = { title = "Operation Item Get", description = "Now that ye've killed those wolves, let's try out somethin' different.  Go nab some items from the troggs over yonder.\n\nOnly the burliest of the burly have items.\n\nci 49707 5You will receive:", objectives = "Paul's Test Questgiver wants you to obtain 5 Trogg Items." }
WordHunterWoW_QuestEN[24463] = { title = "Probing into Ashenvale", description = "Even as the Darnassian scum pull back from Azshara, I've been getting mixed reports from my riders stationed in Ashenvale, to the west. The night elves may be making an assault on our territory in the Barrens.\n\n{class}, I need you to slip across the border and speak to one of my scouts. Look for Kulg Gorespatter just across the bridge at the southwest edge of Talrendis Point. Find out what's happening in those woods!", objectives = "Speak with Kulg Gorespatter in Ashenvale.", completion = "You say Talrendis Point has fallen? That's good news!\n\nIt also explains the exodus of elves I've seen along this road." }
WordHunterWoW_QuestEN[24464] = { title = "Track Beasts", description = "The art of tracking is the soul of the hunt, and you did well in finding me here. I am no seasoned expert, but I've been taught well; I can share with you more ways of following beasts and finding your prey.\n\nIt is the least I can do in repayment for saving me.", objectives = "Speak to Honu Staghunter and learn Track Beasts." }
WordHunterWoW_QuestEN[24465] = { title = "Mark of the Wild", description = "I am but an apprentice myself, {name}, but I can still impart a lesson to you in thanks.\n\nAllow me to teach you how to call out to the Earth Mother, and draw upon the power of the wild.", objectives = "Speak to Keshu Treehoof and learn Mark of the Wild." }
WordHunterWoW_QuestEN[24466] = { title = "Battle Shout", description = "I am but an apprentice myself, {name}, but I can still impart a lesson to you in thanks.\n\nAllow me to teach you how to harness your inner fury into a mighty battle shout.", objectives = "Speak to Brave Sharphorn and learn Battle Shout." }
WordHunterWoW_QuestEN[24467] = { title = "Fade to Black", description = "Now we put an end to all this madness. We need to rout the black dragonflight from Azshara entirely before they can return with any communication for their master.\n\nI still don't know what they have up their sleeve for capturing us, so I'd like to ask this one last thing of you - go into sable ridge and kill their leaders, Twilight Lord Katrana and Malicion.\n\nIf things get hairy, I will come help. I just don't want to risk falling into whatever trap they set for Azuregos.", objectives = "Kill Twilight Lord Katrana and Malicion in Sable Ridge.", progress = "I will be glad to be done with these wretches.", completion = "You truly amaze me, mortal. It's rare to meet someone so dedicated and resourceful.\n\nAzuregos and I are likely to depart Azshara and remain discrete for a while. I do hope that we meet again someday though. Perhaps to put an end to Deathwing himself.\n\nFarewell, <name>. Stay safe." }
WordHunterWoW_QuestEN[24468] = { title = "Stranded at the Marsh", description = "The ogres got two of our stagecoaches: this one and one that fell into the marsh just north of here.\n\nI want you to head there and rescue any survivors while we hatch up a plan to deal with these ogres.", objectives = "Rescue 5 Crash Survivors at the Hailwood Marsh.", progress = "Were any of the passengers still alive?", completion = "You've done it again, <name>.  You have my thanks." }
WordHunterWoW_QuestEN[24469] = { title = "Hold the Line!", description = "Hey, you there!  Ye're a stout-looking {class}.  Lend us a hand?\n\nIt looks like today's big earthquake shook a bunch o' those barbarous troggs out of the ground, and they're sure steamed about something.  My men are doing what they can to hold them off, but we could use a hand.\n\nDo yer part - head just south of here and help dig me mountaineers outta trouble.  We've got to hold the line!", objectives = "Slay 6 Rockjaw Invaders.", progress = "How many of 'em did ya get?", completion = "Impressive work, laddie.  We can hold the perimeter from here on out.\n\nHere, take this for yer troubles.  It might come in handy, as I've got something more important to ask of ye..." }
WordHunterWoW_QuestEN[24470] = { title = "Give 'em What-For", description = "Alright, {name}, listen up.  I know a thing or two about troggs, and one of those things is that the biggest, strongest troggs get the most respect.  The brutes value strength over anything else.\n\nYe see those great big troggs sitting back behind the front lines?  They're the closest they have to what ye'd call a leader.  Go take out a few, and show 'em what it means to mess with the Sons of Ironforge!", objectives = "Kill 3 Rockjaw Goons.", progress = "Well, what're ye waitin' for, <class>?", completion = "Hmm... they blame us for destroying their home, ye say?  Well, that wasn't us, that was the horrible earthquake we had earlier today.  Are they that dense that they can't see we nearly lost our camp too?\n\nCan't blame a trogg for fightin' for his home, though." }
WordHunterWoW_QuestEN[24471] = { title = "Aid for the Wounded", description = "{name}, listen!  Unlike Joren, I've no need for yer blade, but I do need someone with a steady hand and a bit o' courage.\n\nOur mountaineers are trained to protect the village from the odd wolf attack... not an all-out trogg invasion!  Many of our best have succumbed to wounds and exhaustion, and I need yer help bandaging them up.\n\nHere, take my first aid kit and assist as many as ye can.", objectives = "Use Sten's First Aid Kit on 4 Wounded Coldridge Mountaineers.", progress = "Thanks for yer help, <name>.", completion = "Many of those that y'saved have already made it back to camp.  The wounds're well-dressed!  Ye might have a future in first aid, if ye're into that sorta thing." }
WordHunterWoW_QuestEN[24472] = { title = "Introductions Are in Order", description = "The Forsaken are right on our heels and now these ogres are trying to flank us, {name}.\n\nThey're servants of the ettin Koroth -- the meanest, most destructive force in all of Gilneas.\n\nIf we can bait Koroth into charging the Forsaken's forward force, we should be able to cover our retreat and buy some time.\n\nThe only way this can work is if we make Koroth furious.  It won't be enough to just kill his minions.  We need to swipe his most prized possession, a tiger-skinned banner.", objectives = "Kill 4 Ogre Minions and obtain Koroth's Banner in Koroth's Den.", progress = "How did it go, <name>?", completion = "You definitely got the ettin angry, <name>.   I heard him myself.\n\nLet's hope this works." }
WordHunterWoW_QuestEN[24473] = { title = "Lockdown in Anvilmar", description = "We appreciate yer help out here, but there may be a place where they need ye even more.\n\nDue to the trogg attacks - not to mention that massive earthquake we just had - we're putting all civilians on lockdown inside Anvilmar, just up the hill to the northwest.\n\nGo an' talk to me wife, Jona, inside Anvilmar.  I'm certain she's in need of an able-bodied man such as yerself.", objectives = "Speak with Jona Ironstock in Anvilmar.", completion = "Achh.. and what do YOU want?  Can't ye see I'm busy in here!  Go an' bother someone else, I haven't the time.\n\nWait, what's that ye say?  Joren sent you to help?  Well why didn't ye say so?" }
WordHunterWoW_QuestEN[24474] = { title = "First Things First: We're Gonna Need Some Beer", description = "I don't know how ANYONE expects to get any work done around here if we don't have any ale!  Our beer level here in Anvilmar is dangerously low.\n\nLucky for us, we've stowed some backup kegs for just such an occasion.  West of Anvilmar, along the valley's northern border, ye'll find kegs of Stormhammer Stout and Theramore Pale Ale.  Just to the east of here, ye'll find a stash of Gnomenbrau.  That's me personal favorite.", objectives = "Obtain a Cask of Stormhammer Stout, a Cask of Theramore Pale Ale, and a Cask of Gnomenbrau.", progress = "The ale, darling, the ale!", completion = "<Jona drinks deeply from the Gnomenbrau.>\n\nAhh... that hits the spot.  Now we can get some work done around here." }
WordHunterWoW_QuestEN[24475] = { title = "All the Other Stuff", description = "If we're going to be on lockdown for any extended period o' time, we're gonna need some food, and some blankets to keep the wee ones warm.  Would ye mind headin' outside and gatherin' up some supplies?\n\nYe'll find that a few o' the small boars actually have some healthy-sized haunches... good for eatin'.  We'll also need some pelts from the young wolves.\n\nYe'll find animals almost anywhere ye go in Coldridge.", objectives = "Obtain 3 Boar Haunches and 4 Ragged Wolf Hides.", progress = "The people are gettin' restless.  D'ye have the supplies yet?", completion = "This'll have to do for now.  We've a lot of people to feed here, but we've got to make do with what we've got.  With any luck, King Bronzebeard in Ironforge will send us some help shortly." }
WordHunterWoW_QuestEN[24476] = { title = "Tempering The Blade", description = "At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.\n\nDeep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me in The Frozen Halls.", objectives = "Temper the Reforged Quel'Delar in the Crucible of Souls.", progress = "Until the sword is tempered, it will be useless.", completion = "I... I don't understand. Tempering the sword should've restored the blade to its original condition. What has happened here?" }
WordHunterWoW_QuestEN[24477] = { title = "Dwarven Artifacts", description = "{name}, my boy!  Are you into archaeology?\n\nWe've an exciting opportunity right outside our front door.  All the shaking from today's seismic event has knocked a number of artifacts loose from the soil around our encampment.  Survey along the valley's northern border, and you should find all sorts of treasures.  Bring some back to me, and perhaps we can study them together.\n\nRight, then!  Off you go!", objectives = "Obtain 5 Forgotten Dwarven Artifacts.", progress = "Yes?", completion = "Wonderful!  Look at this one... it must be over 200 years old!\n\nNow, onto other matters..." }
WordHunterWoW_QuestEN[24478] = { title = "The Trial of Frost", description = "You know, some of my apprentices have called me cold hearted. I always say though, I shall not let the temperature of my body parts stand in the way of true learning.\n\nTo reach the Trial of Frost, touch the Frost crystal to open a portal. Once there, the goal is quite simple - gather the little floaty ice orb thingies.\n\nTo counter the simple, the rotating Frostburns may put back your progress, as it were. If you want to be fancy, you can use the rune traps to jump over them as they rotate by. Neat, eh?", objectives = "Complete the Trial of Frost by gathering 20 Essence of Ice without getting hit by Frostburn.", progress = "No. Just no. Do it right this time.", completion = "Brilliant. You certainly don't let cold feet stop you. Or cold any part for that matter!\n\nNo? ...too soon?" }
WordHunterWoW_QuestEN[24479] = { title = "The Trial of Shadow", description = "Let us not be confined by the bounds of the mage repertoire of magic. I, for one, choose not to be classist. Necromancy can just be so much fun!\n\nTouch the Shadow Crystal to open a portal to my Trial of Shadow. Once there, move to the Altar when you are ready to begin.\n\nWeeping Souls shall begin to pursue you... your goal is simply to drag them into the traps. And be sure not to let them touch you.", objectives = "Complete the Trial of Shadow by luring 20 Weeping Souls into the shadow runes without getting touched.", progress = "You're not very good at this. You're supposed to complete the trial BEFORE you come talk to me again. Make sense?", completion = "I like the way you move, apprentice.\n\nDon't you worry about where I got all the souls from. They were obtained in a perfectly humane manner, I assure you." }
WordHunterWoW_QuestEN[24480] = { title = "The Halls Of Reflection", description = "You have reforged and tempered the sword, yet it sits quietly in its sheath, showing no signs of the power it should possess. You say the sword pulls you, as though it possesses a will?\n\nDare you bring it where it wishes to go? It's not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Take it into Icecrown Citadel's Halls of Reflection, but be on your guard! I'll be waiting for you in The Frozen Halls.", objectives = "Bring your Tempered Quel'Delar to Sword's Rest inside the Halls of Reflection.", progress = "What happened inside the Halls of Reflection?", completion = "I had not thought it possible for evil to take hold in such a sword, but I suppose it was naive of me. If the greatest of dragonkind's creations could be corrupted and turned against them, why not a mere sword?\n\nUther's advice is wise, <name>, and I would urge you to heed it quickly." }
WordHunterWoW_QuestEN[24481] = { title = "Rockbiter Weapon", description = "I am but an apprentice myself, {name}, but I can still impart a lesson to you in thanks.\n\nAllow me to teach you how to draw upon the spirits of earth, and imbue your weapon with elemental power.", objectives = "Speak to Miira Thunderhoof and learn Rockbiter Weapon." }
WordHunterWoW_QuestEN[24482] = { title = "Power Word: Fortitude", description = "I am but an apprentice myself, {name}, but I can still impart a lesson to you in thanks.\n\nAllow me to teach you how to channel the fortitude of An'she, and imbue yourself with great stamina.", objectives = "Speak to Seer Skyhoof and learn Power Word: Fortitude." }
WordHunterWoW_QuestEN[24483] = { title = "Stormglen", description = "Our carriage drivers were told to regroup in the fishing town of Stormglen.  Our scouts report there might be shelter and supplies to be found there.\n\nMeet Gwen Armstead there, she'll be in charge of taking care of our people.", objectives = "Speak to Gwen Armstead in Stormglen.", completion = "It's good to see you made it, <name>.  It looks like most everybody did.\n\nWe're not doing too bad so far for an emergency evacuation." }
WordHunterWoW_QuestEN[24484] = { title = "Pest Control", description = "Well, what do you know, {name}?  All this time and Stormglen's been left mostly intact.\n\nIt's too bad the Forsaken are still working their way inland, but it'll make a fine place to rest our feet for a night or two.\n\nThe other half of town is overrun with spiders, so I've asked the villagers to stay away from there.\n\nPerhaps you'd like to lend a hand in clearing the spiders out?  I'm certain our injured men and women will sleep more soundly if they know someone's keeping those eight-legged beasts at bay.", objectives = "Kill 6 Vilebrood Skitterers in Stormglen.", progress = "You're back, <name>.  Have the spiders been taken care of?", completion = "You've done well, <name>.  The spiders are everywhere, however, and I'm afraid we've barely put a dent in their numbers." }
WordHunterWoW_QuestEN[24485] = { title = "Seal of Righteousness", description = "I am but an apprentice myself, {name}, but I can still impart a lesson to you in thanks.\n\nAllow me to teach you how to fill yourself with the light of An'she, and strike down your enemies with ", objectives = "Speak to Bowe Dawnhorn and learn Seal of Righteousness." }
WordHunterWoW_QuestEN[24486] = { title = "Make Hay While the Sun Shines", description = "The trogg village to the southwest suffered similar damage to ours.  One would assume, logically, that there would be some trogg artifacts sticking out of the ground, too!\n\nUnfortunately, it looks like most of the artifacts have already been scooped up by trogg scavengers.  Please, go see if you can find some way to get them back.  Believe it or not, knowledge about troggs may eventually lead to further knowledge about the mighty dwarves!", objectives = "Obtain 5 Priceless Rockjaw Artifacts from Rockjaw Scavengers.", progress = "Did you manage to pry any artifacts from the troggs?", completion = "Well would you look at this!  An axe blade, a couple of arrowheads, and what appears to be some sort of rudimentary spoon.  This is indeed fascinating.\n\nThanks again for your help, <name>.  I've much studying to keep myself occupied while Joren's got us under lockdown." }
WordHunterWoW_QuestEN[24487] = { title = "Whitebeard Needs Ye", description = "Ye've done us a great service here, but I'm afraid I've gotta send ye off elsewhere.\n\nGrelin Whitebeard, a good friend of mine, has put in word that he may need some reinforcements near the troll camps to the southwest.  Follow the road westward, ye should find him soon enough.\n\nBe well, {name}.  Troggs may be a pain, but trolls are a whole other type of trouble.", objectives = "Report to Grelin Whitebeard's camp in Coldridge Valley.", completion = "Welcome, <class>.  Are you ready to get to work?" }
WordHunterWoW_QuestEN[24488] = { title = "The Replacements", description = "My guys are all on the injured roster! Our shredders are all kaput! The ref is about to call the game!\n\nIt's down to the wire and I need you, {name}!!!\n\nLet's get one of these shredders in working condition. There are replacement parts all over Bilgewater Port. Any green-blooded Kezanian will gladly let you have them if there's a chance that the Buccaneers will win.\n\nWe'll show those no-good Steamwheedle Sharks how to play footbomb!", objectives = "Collect 6 Replacement Parts.", progress = "We're counting on you, <name>!", completion = "That's my boy! Now to get one of these useless hunks of metal in working order and you into the game!" }
WordHunterWoW_QuestEN[24489] = { title = "Trolling for Information", description = "I'm notoriously bad at reading troll facial expressions.  That being said, these trolls don't look angry to me.  They seem to be confused... maybe a little frightened.\n\nSomething happened that we're not seeing here, {name}.  I say we do some investigation before we just kill every troll in sight.\n\nThere are three troll camps in the area: one to the southeast, one to the southwest, and one due west.  Each camp has a soothsayer... see if you can get close enough to listen to what they're saying.", objectives = "Stand near a Frostmane Soothsayer in each of the Frostmane camps and listen to what they have to say.", progress = "I can't even begin to imagine what would make the trolls act like this.", completion = "Hmm... interesting.  From what you're saying, it sounds like a fire elemental might have snuck in from Searing Gorge.  Or, the earthquake opened up a crack to the elemental plane...\n\n<Soren laughs uncomfortably.>\n\nEither way, this is bad news.  You should probably report this information to Grelin." }
WordHunterWoW_QuestEN[24490] = { title = "A Trip to Ironforge", description = "The presence of a fire elemental here in Coldridge is no small matter.  That earthquake did more than just upset a bunch of troggs... it changed the world enough to tear a gash into the elemental plane.  We should submit a report to Ironforge.\n\nYou wouldn't be willing to take a trip, would ya?  Don't worry, I've a feeling that you'll do just fine.  Talk to Hands Springsprocket by the tunnel on the eastern edge of the valley.  He'll point you in the right direction.", objectives = "Report to Hands Springsprocket in Coldridge Valley.", completion = "To Ironforge?  Well first, you'll need to go through Kharanos, and before that, you'll have to go through this tunnel." }
WordHunterWoW_QuestEN[24491] = { title = "Follow that Gyro-Copter!", description = "D-d-did you see that?  How the whole cave just crumbled like that?  I guess it's good that you got here when you did, and not a minute earlier.\n\nWhile this development makes my job of monitoring the cave entrance much easier, I imagine it makes it a lot harder for you to get to Kharanos.\n\nHey wait, I've got an idea!  The Gnomeregan Airmen have a flight path not far from here.  I'll send up a signal, and they should be here to help.  I imagine they'll land back over at Anvilmar.", objectives = "Report to Milo Geartwinge near Anvilmar.", completion = "Milo Geartwinge, reporting for duty.  You sent up a distress signal?" }
WordHunterWoW_QuestEN[24492] = { title = "Pack Your Bags", description = "The weight limit on my gyro is such that I only have enough room for one {race}.  Looks like you're in luck, {name}!\n\nThat dwarf woman Jona told me that most of your personal belongings have been moved inside Anvilmar.  Please gather what you'll need, finish up any affairs that remain, and return to me when you're prepared for takeoff.", objectives = "Obtain a Coldridge Beer Flagon, a Ragged Wolf-Hide Cloak, and some Leftover Boar Meat.", progress = "Are you absolutely certain you've taken care of everything?  You won't have time to turn back.", completion = "Took you long enough.  Hold on tight, and take a good hard look!  Chances are you won't be coming back here for quite some time." }
WordHunterWoW_QuestEN[24493] = { title = "Don't Forget About Us", description = "You're leaving?  Make sure you stock up before you head out.\n\nMore importantly, please speak to Tharek Blackstone once you arrive in Kharanos.  Tell him what has happened here in Coldridge, and that we could use some assistance.  Hopefully he'll be able to arrange something for us.", objectives = "Report to Tharek Blackstone in Kharanos.", completion = "Coldridge Valley?  I've got my own problems here!  What, they can't deal with a couple of troggs?  And trolls?  And incursions from the elemental plane?\n\nActually, on second thought, that's kind of a lot.  I'm surprised they're doing as well as they are.  I'll see what I can do." }
WordHunterWoW_QuestEN[24494] = { title = "Empowered Rune", description = "<name>, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the shaman trainer Teo. Take a gander at it and go find him inside Anvilmar.", objectives = "Read the Empowered Rune and speak to Teo Hammerstorm in Anvilmar.", progress = "The sprits have forewarned me of your arrival, <name>.  Have you heard them too?", completion = "These are dark days, friend.  Look around you... even here in remote Coldridge, the sprits are rebelling.  The land is crying out for help.  Yet still, even in times such as these, the spirits will always turn an ear to those who ask for their assistance." }
WordHunterWoW_QuestEN[24495] = { title = "Pieces of the Past", description = "I found a journal by a man named Bradshaw.  Unfortunately it's missing many pages.  Especially towards the end.\n\nIf you find enough of the pages I might be able to piece together what happened here after the Curse broke out.\n\nWho knows... maybe the people in this town found a way out.   Maybe there are still survivors out there.\n\n Maybe my father is still alive.", objectives = "Obtain 6 Old Journal Pages.", progress = "Any luck finding those pages?", completion = "Thank you, <name>.  It will take some time, but I'll try to make sense of what we have." }
WordHunterWoW_QuestEN[24496] = { title = "Arcane Rune", description = "<name>, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the mage trainer Teegli. Take a gander at it and go find her inside Anvilmar.", objectives = "Read the Arcane Rune and speak to Teegli Merrowith in Coldridge Valley.", progress = "I see that Jona's given you my runic message.  Do you still have it with you?", completion = "The power of the arcane is everywhere, <name>.  Only some of us have the ability to see it, and fewer still possess the ability to master it.\n\nYou are one of those few." }
WordHunterWoW_QuestEN[24497] = { title = "Airborne Again", description = "We just got word from Valormok that we can't send anymore windriders that way unless we want them shot down by Talrendis snipers. We can't give up Valormok if we want a secure route to Ashenvale, so we're going in another way.\n\nThe airborne priests have graciously offered to drop some people in for us from above sniper range. Head up to the military area and secure a ride on one of their planes. They'll get you there in one piece, and hopefully once you're there, you can resecure our windrider lines.", objectives = "Secure a ride to Valormok with the Airborne Priests in the eastern portion of Bilgewater Harbor.", completion = "It's past time that these night elf scum be purged from Azshara. Glad to have an able body like you to sink the point home.\n\nReady to get to work?" }
WordHunterWoW_QuestEN[24498] = { title = "The Path to the Citadel", description = "They've put my captured soldiers to work in the quarry!\n\nKill their captors and set them free, hero. We will need their aid when we confront Scourgelord Tyrannus.", objectives = "Free 15 Alliance Slaves and kill Forgemaster Garfrost.", progress = "My men and I appreciate your help, <class>. More than we could possibly express in these trying times.", completion = "You've done well this day.\n\nWith many of the slaves freed and now with access to the forges, it will not be long before I have a strong force to aid in delivering us from Scourgelord Tyrannus and this foul pit." }
WordHunterWoW_QuestEN[24499] = { title = "Echoes of Tortured Souls", description = "We're severely undermanned to be risking a venture into the citadel, but opportunities like this are too rare to pass up.\n\nClear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the citadel.", objectives = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", completion = "The Pit of Saron lies ahead, and if our scouts are correct, past that will be the Halls of Reflection.\n\nIt is there that Arthas lets his guard down, and it is there that we hope to find a clue to his weakness... or maybe, just maybe, his redemption." }
WordHunterWoW_QuestEN[24500] = { title = "Wrath of the Lich King", description = "It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?\n\nMany questions remain. but you need to find Jaina and escape the Lich King while there's still time.", objectives = "Find Lady Jaina Proudmoore and escape the Halls of Reflection.", completion = "<Jaina is still catching her breath.>\n\nI can barely believe we're still alive. It was foolish of me to follow him. I've made that mistake too many times.  And you... it was reckless of you to come after me instead of escaping with the information!\n\nBut... well... thank you. You truly are a hero.\n\nWith Uther's guidance, we may stand a chance at defeating Arthas. All the lives lost today were not in vain." }
WordHunterWoW_QuestEN[24501] = { title = "Queen-Sized Troubles", description = "The spiders keep coming in alarming numbers, {name}.  You're going to have to go into their lair and kill the broodmother.\n\nWe've spotted the giant spider known as Rygna at the edge of the Blackwald in an area covered in thick webs.  It'll be dangerous, but we're all counting on you.", objectives = "Slay Rygna at Rygna's Lair.", progress = "Did you take care of Rygna, <name>?", completion = "Great job, <name>.  We've heard rumors of survivors further in the mountains.  Now we'll be able to send scouts there." }
WordHunterWoW_QuestEN[24502] = { title = "Necessary Roughness", description = "We're down to our last shredder. While no one was looking, I loaded it up with, shall we say, modified footbombs.\n\nKid, I need you to get in that shredder and give 'em heck!", objectives = "Get into the Bilgewater Buccaneer and then throw the Footbomb at 8 Steamwheedle Sharks." }
WordHunterWoW_QuestEN[24503] = { title = "Fourth and Goal", description = "It's all up to you, kid. You demolished the Steamwheedle Sharks, so now all that's left to do is to kick the winning goal.\n\nNow, just between you and me, I think we should do this one right. I don't want you to just kick a goal... I want you to kick it so far it sails between the two smokestacks behind the goal!\n\nI've modified the footbomb to give you the extra power that you'll need.\n\nMake me proud!", objectives = "Score the winning goal by kicking the Footbomb through the smokestacks behind the opposing goal.", completion = "Uh... you did it, kid. You REALLY did it! We won the game and....\n\nDID YOU SEE THAT DRAGON?!!!" }
WordHunterWoW_QuestEN[24504] = { title = "Clear the High Road", description = "This way, {class}! I see you've discovered the high road.\n\nThe Alliance hopes to sever our ties with Stonetalon, but they forget that we tauren have hunted across these lands for generations. We know every hillside switchback and game trail from here to Thousand Needles.\n\nBut for these paths to stay open, we must stop the humans from mapping them out.\n\nPatrol the trail east and kill any high road scouts you find along the way, then speak to Tunawa Stillwind just up the path.", objectives = "Slay 3 High Road Scouts.", completion = "Patrolling the high road is grave business, but it must be done. These narrow mountain trails are, for the time being, one of our only lifelines into Stonetalon. They must be preserved.\n\nThank you." }
WordHunterWoW_QuestEN[24505] = { title = "Holdout at Hunter's Hill", description = "Honor's Stand may have been lost, but its spirit was never crushed. Even now survivors are holding out at a point called \"Hunter's Hill.\"\n\nContinue following the high road and you will find our camp just up ahead. Speak with Onatay when you get there and let her know the trail is, for the moment, still clear.", objectives = "Speak with Onatay at Hunter's Hill in Southern Barrens.", completion = "So the Alliance is probing the twists and turns of the high road?\n\nEven if they were to map it out, they couldn't attack these hills in numbers. This is our land, <name>. And they will pay dearly for presuming otherwise." }
WordHunterWoW_QuestEN[24506] = { title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy queen, the Lady Sylvanas Windrunner, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find fierce fighters to send her way. I think you'll do.\n\nGo to her within the entrance to the forge, {class}.", objectives = "Enter The Forge of Souls from the side of Icecrown Citadel and locate Lady Sylvanas Windrunner.", completion = "Good. <name>, I know of you. You'll be perfect for these tasks.\n\nWe've been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we're to avoid Arthas' notice." }
WordHunterWoW_QuestEN[24507] = { title = "The Path to the Citadel", description = "They've put our captured soldiers to work in the quarry.\n\nKill their captors and set them free, {class}. We will need their aid when we confront Scourgelord Tyrannus.", objectives = "Free 15 Horde Slaves and kill Forgemaster Garfrost.", completion = "You've done well this day.\n\nWith many of the slaves freed and now with access to the forges, it will not be long before I have a strong force to aid in delivering us from Scourgelord Tyrannus and this foul pit." }
WordHunterWoW_QuestEN[24508] = { title = "Temp Quest Record", description = "", objectives = "" }
WordHunterWoW_QuestEN[24509] = { title = "Temp Quest Record", description = "", objectives = "" }
WordHunterWoW_QuestEN[24510] = { title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy patron, the Lady Jaina Proudmoore, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find any help that I could... and, well, I was hoping that might be you.\n\nPlease, find her there as soon as you can.", objectives = "Enter The Forge of Souls from the side of Icecrown Citadel and find Lady Jaina Proudmoore.", completion = "<name>! I'm so glad you've come.\n\nWe've been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we're to avoid Arthas' notice." }
WordHunterWoW_QuestEN[24511] = { title = "Echoes of Tortured Souls", description = "Delving into the citadel with so few is risky at best, but opportunities like this are too rare to pass up.\n\nClear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the Citadel.", objectives = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", completion = "The Pit of Saron lies ahead, and if our scouts are correct, past that will be the Halls of Reflection.\n\nIt is there that Arthas lets his guard down, and it is there that we hope to find a clue to his weakness... and a route to vengeance long overdue." }
WordHunterWoW_QuestEN[24512] = { title = "Warriors' Redemption", description = "Those that surrendered when Honor's Stand fell are no longer worthy of our Horde, {class}. But I'm not giving up on them yet. The prison tower below us is lightly guarded. Let's give those prisoners one final chance to die with honor.\n\nI've set up ropes that will allow you to quickly clamber up and down the mountain. Slip down, acquire the confiscated weapons, and re-arm the prisoners inside the tower.\n\nAnd {name}, stay by the tower! We're not yet equipped for an assault on the base proper.", objectives = "Acquire 5 crates of Confiscated Arms from Honor's Stand and re-equip 5 Stonetalon Prisoners. Use the nearby ropes to quickly sneak in and out of the Alliance camp.", progress = "It is a dangerous climb up and down the cliffs, but our ability to appear and disappear without warning is what will drive terror into the hearts of our foes.", completion = "From up here I got the perfect view of the havoc you just caused, <name>. Our lost brothers reclaimed some of their dignity, and the Alliance dogs were sent scrambling. Sharp work, my friend!\n\nIf the Alliance sleeps comfortably at night, we are not doing our job.\n\nWe will never let up.\n\nWe will never give in." }
WordHunterWoW_QuestEN[24513] = { title = "Eye for an Eye", description = "Who goes there? Your footsteps are not the lazy stride of a guard.\n\nA {class}, you say? Still brave and free? There's no hope for me, friend. I have lost my eyesight and am no longer fit for battle.\n\nI dared speak up while Captain Peake savagely beat one of the prisoners. In return he kicked me in the head. And kept kicking. He kicked me blind, {race}.\n\nYou'll find Captain Peake at the top of this tower. If you seek justice, bring me his eyes.\n\nIf he does not part with them willingly... so be it.", objectives = "Slay Captain Peake and deliver his eyes to Oltarg.", progress = "Peake is a monster. If his superiors knew, they would thank the Horde for ending him.", completion = "You have them? I'll take your word for it. Hearing Peake scream like one of his victims is reward enough for me.\n\nNow leave me be, <name>. I do not wish to be a burden to my clan." }
WordHunterWoW_QuestEN[24514] = { title = "Raptor Scraps", description = "We are besieged here, {class}, and between that chasm and the harassment of the Alliance we are short on supplies. But we make do with what's at hand, as we tauren always have.\n\nIn the absence of a forge, a skilled leatherworker can strengthen and patch up our damaged armor with good quality hides.\n\nDown below is the hunting ground of the Terrortooth Raptors. They are not so easy to kill, in part due to the ruggedness of their thick skin. Hunt them, {name}, and bring their hides to me!", objectives = "Gather 8 Terrortooth Hides from Terrortooth Runners and Terrortooth Scytheclaws.", progress = "Terrortooth raptors hunt in packs and surround their prey. We hunt them, yes; but we also respect them.", completion = "<Onatay looks over the fresh hides, nodding her head slowly.>\n\nYes <name>, I can work with these. You work fast!\n\nThese hides will help us hold out for reinforcements longer. Thank you." }
WordHunterWoW_QuestEN[24515] = { title = "Signals in the Sky", description = "Turn your eyes to the southeast. Do you see the campfire smoke from Camp Una'fe?\n\nNot ten minutes ago I saw great puffs of white smoke roll up into the sky from the center of camp. It was an old signal used by my village to coordinate the hunt over great distances, but this time, it was a distress signal.\n\n{name}, my brother Makaba had gone into that unnatural jungle. Please go there and make sure he's not in any trouble.\n\nThere are few paths: look for tents within the wilderness.", objectives = "Travel to Camp Una'fe in the Overgrowth of Southern Barrens and speak with Makaba Flathoof.", completion = "So my sister recognized the old signals? Her hunter's eyes are as sharp as ever.\n\n<name>, when we first set up this camp we were at the edge of this jungle. Now look at it!\n\nSomething is amiss." }
WordHunterWoW_QuestEN[24517] = { title = "Put the Fear in Them", description = "Do you see the trail below us, {name}? That is MY trail. And if the Alliance dogs choose to use my trail, they'd best be looking over their shoulder.\n\nIt's time to collect my toll! Slay the footsoldiers from Honor's Stand and see if we can't send them scurrying back to their walls.\n\nBe sure to take out at least one of their officers patrolling the road. They need to realize that nobody is safe.", objectives = "Kill 8 Honor's Stand Footmen and 1 Honor's Stand Officer.", completion = "Excellent, <name>. It will be some time before we can assault the hold proper, but until then, we must teach them to fear the Barrens." }
WordHunterWoW_QuestEN[24518] = { title = "The Low Road", description = "This bundle of papers was found in a leather satchel hidden under the officer's clothes.\n\nBattle maps of the region depict Honor's Stand, connected to what appears to be a large unfinished roadway crossing the Barrens all the way from Theramore. It looks like the Alliance plans to build a road from the coast straight into the heart of Kalimdor!\n\nKilrok Gorehammer will want to see this.", objectives = "Deliver the Roadway Plans to Kilrok Gorehammer at Hunter's Hill in Southern Barrens.\n\nProvided item:", progress = "Ah, you say you found something on one of the bodies?", completion = "<Kilrok pages through the plans you discovered.>\n\nThis explains much, <name>. No wonder our foes are so hellbent on taking the southern Barrens. It's at the center of their plans for the continent!\n\nBut they didn't account for us, did they <class>?" }
WordHunterWoW_QuestEN[24519] = { title = "Stalling the Survey", description = "These maps have all been drawn by the same steady hand. I've seen a human surveyor heading up and down the road between the hold and the jungle to the east.\n\nWe can set their plans back by making an example out of this surveyor, {name}.\n\n<Kilrok points to the signature at the bottom of the maps.>\n\nWhat do you think that says? \"Zykes?\" Even human names sound thin and weak. Kill him.", objectives = "Find and kill the surveyor Henry Zykes.", completion = "Good, good. We've got to keep Honor's Stand isolated.\n\nAlone ... afraid ... <name>, if we keep up the pressure, maybe someday they'll simply surrender the pass." }
WordHunterWoW_QuestEN[24520] = { title = "Give Sassy the News", description = "I'd celebrate with you, {name}, but it feels like that dragon did a number on ol' Mount Kajaro. I... uh... I think I'm gonna grab my stuff and get on the first ship leaving the island!\n\nAnyways, you should probably head back to headquarters and let Sassy know that you won the footbomb title for us. I'm sure she'll also want to know about the dragon and Mount Kajaro.\n\nGood luck!", objectives = "Speak with Sassy Hardwrench at KTC Headquarters on Kezan.", completion = "You're kidding, right?! DEATHWING?!!!\n\n<Sassy looks panicked for a moment.>\n\nOkay, this'll work out just fine. We'll throw your party and by the time it's over, I'm sure that the dragon will be long gone and the ground will stop shaking.\n\nIf not, we can always charter a ship off of the island." }
WordHunterWoW_QuestEN[24521] = { title = "Report for Tryouts", description = "<name>, Coach Crosscheck, the leader of our fearless Bilgewater Buccaneers, is looking for you.\n\nHe says that the division title against the Steamwheedle Sharks is on the line and that you're the only one that can bring it home for us!\n\nHead west into town. You can't miss Kajaro Field!Upon completion of this quest you will gain:", objectives = "Speak with Coach Crosscheck at Kajaro Field on Kezan.<name>, Coach Crosscheck, the leader of our fearless Bilgewater Buccaneers, is looking for you.\n\nHe says that the division title against the Steamwheedle Sharks is on the line and that you're the only one that can bring it home for us!\n\nHead west into town. You can't miss Kajaro Field!Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[24522] = { title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians of the Sunwell will not simply allow you to walk in, so you must find Halduron Brightwing, who will be inspecting the guards there.", objectives = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.", progress = "What brings you here?", completion = "Admit you to the Sunwell? That's impossible! The Sunwell is the most sacred and important site of our people. We have only recently reclaimed it with the help of the Shattered Sun Offensive. It is not a place for tourists or travelers." }
WordHunterWoW_QuestEN[24523] = { title = "Wildmane Totem", description = "There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.\n\nAlphas often wander around the base of our mighty city, Thunder Bluff.", objectives = "Collect 4 Prairie Alpha Teeth from Prairie Wolf Alphas.", progress = "<name>.  Do you have the teeth I asked for?", completion = "Very good, <name>.  I can feel the sacrifice of the land in this offering, and my spirit swells with sadness, and pride." }
WordHunterWoW_QuestEN[24524] = { title = "Wildmane Cleansing", description = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young {name}.  The Wildmane Totem is made, and your last task lies ahead.\n\nThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the Grimtotem's poisons!  Let clean water flow once again!", objectives = "Use the Wildmane Cleansing Totem at the Wildmane Water Well.", completion = "You've done it.  You have cleaned the wells, and healed our land.  Bloodhoof village is grateful, <name>.\n\nMay the wind whisper your deeds for a hundred seasons, and may the waters of Mulgore remain clean forever." }
WordHunterWoW_QuestEN[24525] = { title = "Keeping the Dogs at Bay", description = "Not everyone who fled Taurajo was able to make it to Una'fe, {name}. Some died of wounds along the way. Others were jumped by opportunistic quilboar.\n\nI'll take care of the grim task of finding and gathering the bodies. But there is something you can do for me.\n\nHecklefang scavengers prowl the lands south of here and are savaging the corpses, tearing at their bowels and dragging away the limbs of the dead. Please, thin their numbers so that I can perform the proper funerary rites.", objectives = "Kill 6 Hecklefang Scavengers.", completion = "So it is done.\n\nNormally these scavengers are part of the Earthmother's cycle of life. But on the heels of the devastation wracked by both the Alliance and the cataclysm, their numbers grow overwhelming. It is good to thin them out." }
WordHunterWoW_QuestEN[24526] = { title = "Filling Up the Spellbook", description = "Excellent!  Let's get started.\n\nAs you grow in power, your connection to the arcane arts will deepen, and you'll gain access to new spells and abilities.\n\nGo, get some more experience, and you'll see what I mean. Come back when you learn something new and demonstrate it on the training dummies here.", objectives = "Reach level 3 to learn Frost Nova. Successfully cast it 2 times on the Training Dummies outside the entrance to Anvilmar.", completion = "There we go!  One spell down, many many more to go.  Come back to me after you've had some experience casting this spell, and I'll show you some more tricks." }
WordHunterWoW_QuestEN[24527] = { title = "Your Path Begins Here", description = "Excellent!  Let us begin.\n\nAs you grow along your journey, you will unlocked the ancient secrets of shamans. \n\nPrimal Strike is the first such skill.  The primal spirits, when called upon, will strengthen your arm to deliver a mighty blow.\n\nHelpful, isn't it?", objectives = "Reach Level 3 to learn Primal Strike, and then use Primal Strike 2 times on a Training Dummy near the entrance of Anvilmar.", completion = "This has been but one of many footfalls on the long path of the <class>.  Come back to me after you've had some experience in the field, and I will help guide you on your next step." }
WordHunterWoW_QuestEN[24528] = { title = "The Power of the Light", description = "Are ye ready to start?  Wonderful!  We're glad to have ye.\n\nAs ye get stronger, it brings ye closer to the light, and ye learn new techniques. Go ahead and get some more experience, and show me what ye learn.", objectives = "Reach level 3 to learn Seal of Command. Use Seal of Command on yourself, and then hit one of the Training Dummies at the entrance to Anvilmar.", completion = "There, ya did it.  The Light favors quick learners like you.  Come back to me after you've spent some time using what I've taught ya, and I'll show ya something new." }
WordHunterWoW_QuestEN[24529] = { title = "Bad to Worse", description = "When the refugees fled north from Taurajo, some were separated as darkness closed in. Many were taken prisoner by the Bristleback quilboar who set up camp west and southwest of here.\n\nI am not certain what the quilboar hoped to get from us by capturing our refugees; all they have earned is my ire. And all they'll get in return is vengeance.\n\nRescue my trapped brothers and sisters, and kill their captors to send a message to the quilboar.", objectives = "Rescue 5 caged Taurajo Refugees, and kill any combination of 8 Bristleback Thornweavers or Bladewardens.", progress = "How do things look in the quilboar camps, <class>?", completion = "It's bad enough to have one's village sacked... but to spend the following night in a quilboar cage? I'm glad you were there to help, <name>." }
WordHunterWoW_QuestEN[24530] = { title = "Oh, A Hunter's Life For Me", description = "The life of a hunter is steeped in tradition, ye know.  Trackin' mighty beasts through rugged terrain.  Drinkin'.  Travelin' the land, yer gun at yer side.  Drinkin'.  Survivin' on wits and courage and cunning, followed by a good stiff drink.\n\nBut before we get to the good stuff, though, ye'll need to learn how to do the beginner stuff.\n\nGo and get some more experience, and ye'll figure out how to do more things. Then ye' drink.", objectives = "Reach level 3 to learn Steady Shot, then use Steady Shot 5 times on the Training Dummies outside the entrance to Anvilmar.", completion = "Now that ye've got a new <class> trick under yer belt, and now that I've got some of yer money, go out there an' track some beasts!  Come back sometime in the future, an' we'll talk again." }
WordHunterWoW_QuestEN[24531] = { title = "Getting Battle-Ready", description = "Lesson one.  Aside from your sword and shield, what's the most important tool you have in your arsenal?\n\n<Thran awaits your response.>\n\nOh never mind, I'll answer it for you.  It's experience.\n\nAs you get more experience, you'll discover new techniques, which means you can be much more effective than you imagined.\n\nGo, get some experience, and learn something new. Then come back and demonstrate.", objectives = "Reach level 3 to learn Charge, then use Charge on one of the Training Dummies outside the entrance to Anvilmar.", completion = "Now we're getting somewhere.  You've got quite a manly bellow, sir!\n\nCome back to me in a bit, and I'll teach you something else." }
WordHunterWoW_QuestEN[24532] = { title = "Evisceratin' the Enemy", description = "When you get to be more experienced, you'll start to find you can take advantage of new abilities. \n\nOne of the things that you'll learn is the ability to use combat maneuvers to weaken an opponent, and then hit them with a devastating technique.\n\nGo and get some experience, figure out how to do it, and then try it out on some of the dummies here.", objectives = "Reach level 3 to learn Eviscerate, then use Eviscerate 3 times on the Training Dummies near the entrance to Anvilmar.", completion = "You've got the hang of it.  Go get some practice out there... maybe take out a few of those troggs or trolls.  Or rabbits, I don't care.\n\nReturn after you've gotten some practice, and I'll show you another trick of the trade." }
WordHunterWoW_QuestEN[24533] = { title = "Words of Power", description = "Now, if ya DO want to become somethin' special, ye'll need to talk to me.  A priest is nothin' without his spells.  And how do you learn new spells?\n\nYa go and get more experience. So go out, get stronger, and then come show me what ya learn.", objectives = "Reach level 3 to learn Shadow Word: Pain, then cast it 5 times on training dummies.", completion = "Well done, <name>.  You'll make a fine <class> in due time.\n\nReturn to me after you've proven yourself a bit more, and I'll reward you by teaching you another spell or two." }
WordHunterWoW_QuestEN[24534] = { title = "Speaking Their Language", description = "The quilboar are attacking because they perceive weakness. Strength is the only language they understand. So we will show them strength.\n\n<Makaba withdraws a large horn from his satchel.>\n\nThis is admittedly crude work but it'll do. Bristleback leaders use horns like these to challenge one another for dominance.\n\n{name}, I want you to challenge the Bristleback champion, Sabersnout, to single combat. Defeat him in front of his followers. Blow the horn at the Bristleback challenge ring due south of here.", objectives = "Blow the Horn of Challenge in the Bristleback Challenge Ring, and defeat Sabersnout in single combat.", progress = "Have you taken the Bristlebacks down a peg or two?", completion = "What? He attacked you with a dozen boars? I guess quilboar have their own ideas of what \"single combat\" means.\n\nStill, the Bristleback will be left reeling after the blow you delivered. It will not be long before a new champion rises amongst them to stir up trouble... but at least this buys us some time to get these refugees relocated safely.\n\nThank you, <name>. The survivors owe you a great debt." }
WordHunterWoW_QuestEN[24535] = { title = "Thalorien Dawnseeker", description = "If you truly bear Quel'Delar, {name}, I might be able to admit you to the Sunwell. If you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", objectives = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.", progress = "Did you visit the ground where Thalorien fell defending the Sunwell?", completion = "I confess that I did not expect Thalorien's spirit to recognize you as the heir to Quel'Delar, but I defer to his judgment. You may enter the Sunwell, but I remind you that you are a guest in our most sacred of precincts, and you should act accordingly." }
WordHunterWoW_QuestEN[24536] = { title = "Something Stinks", description = "Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume.\n\nTake this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.", objectives = "Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Detective Snap Snagglebolt in Orgrimmar.", progress = "You analyze that reek yet, kid?", completion = "Hey, thanks, kid. Give it over, let's take a look.\n\n<He takes the device from you and fiddles with it.>\n\nOh, that ain't good." }
WordHunterWoW_QuestEN[24539] = { title = "When Plants Attack", description = "This camp was built at the edge of this jungle, and already it is overwhelmed by plant growth. Something unnatural is happening here!\n\nEarlier I made the mistake of sending some of the healthier refugees out to gather nuts and berries. Those that returned talked about the plant life actually grasping at their legs or even picking them up. I worry about those that haven't come back yet.\n\n{class}, please rescue the refugees trapped in the grasping overgrowth around the camp. ", objectives = "Rescue 5 Taurajo Refugees by killing the Grasping Overgrowths that ensnare them.", progress = "Be careful out there. The plants and animals of this jungle are outside of the natural order.", completion = "Thank you, <name>. But now on to the larger question:\n\nWhere is this overgrowth coming from? And why is it raging out of control?" }
WordHunterWoW_QuestEN[24540] = { title = "War Dance", description = "Some see our people as gentle giants, or noble savages. They have never seen us fight against our own kind...against betrayers from within.\n\nThe Grimtotem were offered mercy in exile, and they have scarred their own home to spite us. They will no longer be tolerated in Mulgore.\n\nI've already sent our warriors ahead to drive them out through Stonetalon Pass, to the north. You have fought bravely against the Grimtotem, {name}; I ask that you join the battle again. Go, and help deal this final blow.", objectives = "Defeat Orno Grimtotem at Stonetalon Pass.", progress = "I do not plan on sitting idly in Thunder Bluff while our warriors risk their lives for our home, <name>. We shall meet on the battlefield. Strike out ahead of me; I will leave soon.", completion = "Welcome back, <name>.\n\n\n\nWhat was done was not for revenge, or pride. It was simply to protect Thunder Bluff, and all our people, from torment and fear. Today, Mulgore is safe once more.\n\nThe Earth Mother thanks you for all your brave deeds, <name>, as do I. You have earned your reward, hero. May you be welcome in Thunder Bluff always." }
WordHunterWoW_QuestEN[24541] = { title = "Pilfering Perfume", description = "I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff.\n\nDon't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like.\n\nI'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.", objectives = "While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Orgrimmar, then return the package they toss you to Detective Snap Snagglebolt in Orgimmar.", progress = "Did they toss ya a crate to deliver?", completion = "You got it, huh? Good job, kid. Top notch. Let's see what we got here.\n\n<He cracks open the crate and rummages around inside.>" }
WordHunterWoW_QuestEN[24542] = { title = "A Curious Bloom", description = "The great archdruid Naralex recently appeared here in the Barrens. He's either behind this mess or trying to fix it. Either way, you should talk with him before this jungle engulfs the whole world! He's in a small tauren camp to the southeast.\n\nAlong the way, it would be helpful for you to gather plant samples for him to study. The newest flower buds will tell him a great deal about the most recent changes in the jungle.", objectives = "Gather ten Unusual Flower Buds from Budding Flowers in the Overgrowth.", progress = "I am extremely busy, <class>.", completion = "Ah, samples from different parts of the overgrowth? These will be immensely helpful, yes. Thank you, <class>." }
WordHunterWoW_QuestEN[24543] = { title = "A Family Divided", description = "The children you see here were all rescued from Taurajo when the fighting started. I'm trying to track down their parents.\n\nOne of the refugees you rescued from the quilboar recognized the strongest child as belonging to Kirge and Mawre Sternhorn. Moreover, he said Kirge was camped at the Fields of Blood, just north of the Taurajo massacre site.\n\n{name}, please go there and tell Kirge Sternhorn that his child is alive and well!", objectives = "Find Kirge Sternhorn at Vendetta Point in Southern Barrens.", completion = "<Kirge listens intently and then falls to one knee.>\n\nAlive! My boy still lives! Praise to the earthmother, I still have a son.\n\n<Kirge composes himself.>\n\n<class>, my boy's mother didn't make it out of Taurajo alive. I will avenge her death, even if it means my son grows up without either of his parents." }
WordHunterWoW_QuestEN[24544] = { title = "Paul Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[24545] = { title = "The Sacred and the Corrupt", description = "It is against my judgment that I present you this errand, {race}, as it will likely end in your undoing.\n\nIgnore my counsel and embark on the endeavor, and I shall provide you with the knowledge and resources to see it through.\n\nYou must return to Frostmourne Cavern and recover Light's Vengeance, Arthas' discarded hammer. Reforged with saronite and etched with the acidic blood of the Lich King's abominations, it will provide the foundation for our work.", objectives = "Place Light's Vengeance, 25 Primordial Saronite, Rotface's Acidic Blood, and Festergut's Acidic Blood in Highlord Mograine's runeforge in Icecrown Citadel.\n\nRotface's Acidic Blood and Festergut's Acidic Blood may only be obtained in the 25 person difficulty setting of Icecrown Citadel.", progress = "As you draw near, the forge's flame seems to burn even more ravenously...", completion = "A deep sense of dread washes over you as the flame devours the items." }
WordHunterWoW_QuestEN[24546] = { title = "A Line in the Dirt", description = "The Alliance scorches a trail of murder across the Barrens. We must stop them here or there is nothing left for us.\n\nAcross the Fields of Blood there are a number of strategic hills, marked by wooden towers and neutral gray banners. We must take and hold these hills if we hope to slow the Alliance advance!\n\nLook for the towers to the north, east, and south of what's left of Taurajo. Claim a neutral flag and defend the hill against counterattack!", objectives = "Capture a neutral hill in the Fields of Blood and defend it against an Alliance counterattack.", completion = "So you held your ground! With tenacity like yours we may yet drive the Alliance from our lands." }
WordHunterWoW_QuestEN[24547] = { title = "A Feast of Souls", description = "Shadow's Edge is among the greatest weapons a {class} could hope to obtain.\n\nIs your lust for power sated, {race}?\n\n<You feel Mograine's penetrating gaze.>\n\nI thought not. A final warning then...\n\nYou now embark on the most treacherous leg of your quest. Bridle your aspirations, for if your aims are impure then your life, your very soul, is forfeit.\n\nThe weapon you hold is but an empty husk, a mere shadow of what it may become.", objectives = "Highlord Darion Mograine wants you to use Shadow's Edge to slay 50 of the Lich King's minions in Icecrown Citadel. Souls can be obtained in 10 or 25 person difficulty.", progress = "Has the weapon's hunger been sated, <class>?", completion = "<Highlord Mograine eyes you in silence for a moment.>\n\nYou seem to have endured this leg of your trial admirably, <race>.\n\nPray that fate continues to smile upon you in your endeavor..." }
WordHunterWoW_QuestEN[24548] = { title = "The Splintered Throne", description = "The Lich King's throne once served as his prison. Kil'jaeden himself crafted the vessel of icy crystals from the twisting nether, its sole purpose to hold Ner'zhul's vengeful spirit.\n\nWhen Arthas struck the crystal with Frostmourne, he released Ner'zhul's soul, allowing it to merge with his own. Splinters from that impact are now scattered throughout the citadel.\n\nI shall require those shards, held only by the Lich King's most powerful servants, to seal the power contained in your blade.", objectives = "Highlord Darion Mograine wants you to collect 50 Shadowfrost Shards.\n\nShadowfrost Shards may only be obtained in the 25 person difficulty setting.", progress = "Have you obtained the shards of the frozen throne, <class>?", completion = "These should suffice, <class>.\n\nSpeak to me when Shadow's Edge has been thoroughly empowered and I will attempt its completion." }
WordHunterWoW_QuestEN[24549] = { title = "Shadowmourne...", description = "", objectives = "Highlord Darion Mograine wants you to bring him Shadow's Edge.", completion = "Congratulations, <class>.\n\nAgainst insurmountable odds, you have weathered the storm.\n\nI trust that you shall find your reward proportionate to your conviction..." }
WordHunterWoW_QuestEN[24550] = { title = "Journey into Thunder Bluff", description = "The wells are cleansed, and Mulgore's waters run sweet and clear once more. You've saved us...but you've also uncovered grim happenings. The actions of the Grimtotem must be made known.\n\nIt is time for you to enter Thunder Bluff, our great city atop the mesa.  Go to our leader, Baine Bloodhoof, son of Cairne. He must hear of this.", objectives = "Speak with Baine Bloodhoof in Thunder Bluff.", completion = "Welcome to Thunder Bluff, <name>. You've done great things for our people.\n\nTell me of your journey." }
WordHunterWoW_QuestEN[24551] = { title = "Meet the New Boss", description = "Our defense of the Barrens hasn't gone well under Gar'dul's command, {name}. Garrosh has sent Warlord Bloodhilt here to take control of the situation. He's here in camp, and if you want to make a good impression, you'll demonstrate some initiative.\n\nHead east into the Fields of Blood and seek out Northwatch recon units. Bringing the new Warlord a stack of their merit badges will help you make a name for yourself!", objectives = "Kill Northwatch Recon patrols and collect 10 Theramore Merit Badges.", progress = "You look like the type of <class> who gets things done. What news do you have from the field?", completion = "<Bloodhilt looks at the badges, then allows them to spill from his hands onto the sands below. His lips curl open into a toothy grin.>\n\nNow THIS is what I like to see, <class>! What is your name again?\n\nYou will go far here." }
WordHunterWoW_QuestEN[24552] = { title = "Lion's Pride", description = "If you seek vengeance on our Alliance invaders, you would do well to observe the fiercest of predators in the Barrens.\n\nThe lions that stalk amongst the tall grass do so with cunning, stealth, and power. Learn from their example and you will understand the kind of war we need to fight.\n\nHunt the plains prowlers and pridemanes, then return to me to discuss what you have learned. You will often find them in the shade of large trees.", objectives = "Kill any combination of 5 Plains Prowlers or Plains Pridemanes.", progress = "The Barrens is a harsh land, but I have come to love it. How are you faring?", completion = "Ah yes... I see a cunning in your eyes that was not present before. Well done, <class>." }
WordHunterWoW_QuestEN[24553] = { title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to me and to the rest of my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. The blade will bond to you. When that happens, carry it to Caladis Brightspear at Quel'Delar's Rest.", objectives = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened during your time in the Sunwell?", completion = "This is unbelievable, <name>. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored." }
WordHunterWoW_QuestEN[24554] = { title = "The Battered Hilt", description = "This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art.\n\nThe graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Sunreavers would be interested in hearing about the recovery of such an artifact. Seek out their representatives at Quel'Delar's Rest, to the south of the Argent Tournament Grounds.", objectives = "Bring the Battered Hilt to Myralion Sunblaze at Quel'Delar's Rest, south of the Argent Tournament Grounds.", progress = "What have you discovered?", completion = "<Myralion takes the hilt from you and scrutinizes the artifact.>\n\nThis came from the citadel? What was it doing there? This blade is certainly not of Scourge manufacture.\n\nWeapons of this quality can only be crafted by a few of Azeroth's creatures. We will have to consult them and see if they can help us identify it." }
WordHunterWoW_QuestEN[24555] = { title = "What The Dragons Know", description = "There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recognize these particular markings, but we haven't hit a dead end yet.\n\nKorialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Magister Hathorel inside Sunreaver's Sanctuary in Dalaran.", objectives = "Speak to Krasus at the top of Wyrmrest Temple.", completion = "We must recover that book from the Silver Covenant. Without that book from Krasus, we stand little chance of solving the mystery of the sword in Icecrown or unlocking its power." }
WordHunterWoW_QuestEN[24556] = { title = "A Suitable Disguise", description = "Getting you inside the Silver Enclave will be tougher than it appears. Only those who possess Silver Covenant tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work.\n\nOn the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.", objectives = "Obtain a Borrowed Tabard from Shandy Glossgleam.", progress = "Was Shandy able to help you get a Silver Covenant tabard?", completion = "I knew Shandy would find a way to make it work. Let me get this enchanted and ready for you to use. With any luck, the tabard's owner won't even know it's missing and Shandy will cover the rest of our tracks." }
WordHunterWoW_QuestEN[24557] = { title = "The Silver Covenant's Scheme", description = "One of my contacts in the Underbelly caught sight of a Silver Covenant agent gathering information at the Cantrips and Crows Tavern. Silver Covenant members aren't normally found in the sewers, so they must be plotting something.\n\nGo into the Underbelly, find this Silver Covenant agent, and eliminate him. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let those simpering Silver Covenant weaklings get it back to Icecrown before we do.", objectives = "Capture the Silver Covenant Orders.", progress = "Did you find anything of use on that agent?", completion = "<Magister Hathorel reads the captured orders.>\n\nThe agent you intercepted was supposed to deliver the Wyrmrest tome to Icecrown, after meeting with one Arcanist Tybalin inside the Silver Enclave. We have to reclaim that book, <name>, and we only have one chance before it leaves the city. We have to work quickly." }
WordHunterWoW_QuestEN[24558] = { title = "Return To Myralion Sunblaze", description = "We must get this book to Myralion Sunblade. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at evading the Silver Covenant's men.\n\nTake it with you to Quel'Delar's Rest, south of the Argent Tournament Grounds in Icecrown. Myralion will be waiting for you. If he can identify that blade, we may be able to claim it in the name of Aethas Sunreaver and show Dalaran and the Alliance that we will lead the charge against the Lich King.", objectives = "Bring Ancient Dragonforged Blades to Myralion Sunblaze at Quel'Delar's Rest.", progress = "We've been expecting your return. What has kept you?", completion = "<Myralion accepts the heavy book and begins leafing through it.>\n\nThose symbols on the blade seemed familiar and now there's little wonder why. This is certainly a dragon blade, gifted to one of the mortal races, but which blade is this, and how did it come to rest in Icecrown?" }
WordHunterWoW_QuestEN[24559] = { title = "Reforging The Sword", description = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.\n\nIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar.\n\nYou must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.", objectives = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer, then combine them with the Remnants of Quel'Delar to create the Reforged Quel'Delar.", progress = "Were you able to reconstruct Quel'Delar?", completion = "You have remade the blade of Quel'Delar in defiance of that Blood-Queen Lana'thel's pronouncement! Now, the blade must be tempered before we can show her the folly of her words." }
WordHunterWoW_QuestEN[24560] = { title = "Tempering The Blade", description = "At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.\n\nDeep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me. I'll be waiting in The Frozen Halls.", objectives = "Temper the Re-forged Quel'Delar in the Crucible of Souls.", progress = "Until the sword is tempered, it will be useless.", completion = "Tempering the sword should've restored the blade. Why hasn't it worked?" }
WordHunterWoW_QuestEN[24561] = { title = "The Halls Of Reflection", description = "You have re-forged and tempered the sword, yet it sits quietly in its sheath, little different from a mundane blade. You say the sword pulls you, as though it possesses a will?\n\nDare you bring it where it wishes to go? It is not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Bear it with you to Icecrown Citadel's Halls of Reflection, but be on your guard. I will wait for you in The Frozen Halls.", objectives = "Bring Quel'Delar to Sword's Rest inside the Halls of Reflection.", progress = "What happened inside the Halls of Reflection?", completion = "How can evil take root in such a sword? I would not have thought it possible if the evidence wasn't here before my eyes. If the greatest of dragonkind's creations could be corrupted and turned against them, why not a mere sword?\n\nI believe Uther is right. You must heed his advice quickly, <name>." }
WordHunterWoW_QuestEN[24562] = { title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians will try to stop you from entering the Sunwell Plateau, but make yourself known to Halduron Brightwing, who will be inspecting the guards there.", objectives = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.", progress = "What brings you here?", completion = "I hope you understand that I can't just admit you to the Sunwell, <name>. This is the most sacred place known to the sin'dorei and we have only recently regained control over it.\n\nYou would raise the hopes of our people with tales of Quel'Delar? Without proof of the truth of your claims, I see no reason to take you at your word." }
WordHunterWoW_QuestEN[24563] = { title = "Thalorien Dawnseeker", description = "You are the one working with Myralion Sunblaze, arent you? I know of a way we can test the sword.\n\nIf you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", objectives = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.", progress = "Did you visit the ground where Thalorien fell defending the Sunwell?", completion = "You truly do carry Quel'Delar. This is a great day for all of Quel'Thalas and the sin'dorei. You have my leave to enter the Sunwell and finish the sword's restoration. Keep your head high, <name>. The children of Silvermoon have dreamt of this day for years." }
WordHunterWoW_QuestEN[24564] = { title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Afterward, show the blade to Myralion Sunblaze at Quel'Delar's Rest.", objectives = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened inside the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!" }
WordHunterWoW_QuestEN[24565] = { title = "Biological Intervention", description = "The energies unleashed here have surged through the wildlife, twisting them into powerful and unstable forms. If allowed to spread beyond this grove, these deviates will wreak havoc on the existing ecosystem, devouring local prey and driving out the weaker natural creatures.\n\nYou must go and cull the population of the overgrowth. Return when this task is done.", objectives = "Kill 5 Deviate Terrortooths and 5 Deviate Plainstriders.", completion = "Thank you, <name>. I'm pleased to see you return intact; the viciousness I've been seeing among these creatures is startling." }
WordHunterWoW_QuestEN[24566] = { title = "Sowing a Solution", description = "Based on what you've brought me, I think we may have a solution. I've imbued the lashvine seeds with healing energies.\n\nSimple contact with these should imbue the creatures here with enough energy to force out the corrupted influence.\n\nGo and attempt to heal the mutated raptors and plainstriders by sprinkling the seeds on them, and report the results back to me.", objectives = "Use Soothing Seeds on 6 Deviate Terrortooths or Deviate Plainstriders and observe the results.", progress = "Did it work?", completion = "Oh dear. It seems the forces at work here are a bit difficult to control...\n\nPlease, don't bother Naralex with this. It will only upset him." }
WordHunterWoW_QuestEN[24567] = { title = "Report for Tryouts", description = "{name}, Coach Crosscheck is looking for you. He's the leader of our fearless footbomb team, the Bilgewater Buccaneers.\n\nHe says that the division title against the Steamwheedle Sharks is on the line and that you're the only one that can bring it home for us!\n\nHead west into town. You can't miss Kajaro Field.\n\nA footbomb star. This is going to be great for your image!", objectives = "Speak with Coach Crosscheck at Kajaro Field on Kezan.", completion = "There you are, my boy! Quick, there's no time to waste! We need to get one of these shredders back in working order.\n\nI'm bringing you off the bench... you're going to win the game and the title for us!" }
WordHunterWoW_QuestEN[24568] = { title = "To the Walls!", description = "{name}, they're massing at the gates! The Alliance is trying to push their way into Mulgore, using footsoldiers to overwhelm the guards.\n\nWe have so little with which to defend the walls. We've kept pots of water boiling to repel the attackers until help arrives... Those will have to do.\n\nBut we need someone to coordinate our defenses. Say the word and I can give you an eagle-eye view of the battlefield.\n\nWe need you, {name}!", objectives = "Speak with Winnoa Pineforest at the Fields of Blood in order to defend the gates of Mulgore from attack." }
WordHunterWoW_QuestEN[24569] = { title = "Siegebreaker", description = "{name}, you've proven yourself on the Fields of Blood. But the Alliance still threatens our tauren friends.\n\nThe siege machinery outside the gates of Mulgore is like a spear aimed at our heart. I want you to go to the gates, south of here, and remove those siege vehicles from play.\n\nHere, use these stickybombs. They're courtesy of our new goblin allies. It looks as though they stuffed explosive powder into ... what looks like ... grease-covered socks. But they'll do.", objectives = "Destroy 4 Northwatch Siege Engines at the Mulgore Gates.", progress = "Why did Gar'dul allow the Alliance to create such a buildup of heavy siege vehicles? Why wasn't a strike ordered until I got here? Gar'dul will have to answer for this...", completion = "Very good. Now, should they storm the gates, they will have to do so with infantry.\n\nDo you think they have the stomach for that?" }
WordHunterWoW_QuestEN[24570] = { title = "Adder Subtraction", description = "The corruption unleashed here must be studied if we're to find a way of properly fighting it.\n\nLuckily, not all the creatures have been as altered as others. The smaller snakes drink little water, and do not eat plants, so their exposure to the energies here has been minimal. They've still absorbed enough to change coloration.\n\nGo collect these snakes from the overgrowth and return them to me, so we can see just what is happening to the creatures here.", objectives = "Collect 5 Enervated Adders.", progress = "Have you collected enough? We'll need several for proper comparison.", completion = "These will do perfectly. Bright colors like these don't occur naturally in the barrens, but they haven't developed any other mutations so far." }
WordHunterWoW_QuestEN[24571] = { title = "Lashvine Seeds", description = "There's got to be a way to cure these poor creatures without having to take their lives. I have an idea, but I'll need your help, {class}.\n\nThe lashvine plants that roam here hold seeds full of the primal energy of this place. Collect these for me and bring them back, and we'll see if something can be done.", objectives = "Collect 4 Writhing Seeds from Lashvines.", progress = "Do you have the seeds?", completion = "I'm concerned by how...active these are. Nevertheless, it simply means we must continue to act quickly before the corruption here becomes worse." }
WordHunterWoW_QuestEN[24572] = { title = "Taking Back Taurajo", description = "Outstanding work at the gates, {name}! The main body of the Alliance force is in general retreat. But I'm not satisfied.\n\nThey sacked Taurajo, which was little more than a hunters' camp. This 'Alliance' is unmasked at last for what it really is: A renegade band of butchers.\n\nEven now a group of humans linger behind to pick at the bones of smouldering Taurajo.\n\n<Bloodhilt hurls an axe into the dirt.>\n\nMake them suffer.", objectives = "Kill 8 Taurajo Looters in the ruins of Taurajo.", completion = "Excellent. I'll have their bodies strung up along the gold road as a message to the Alliance." }
WordHunterWoW_QuestEN[24573] = { title = "Honoring the Dead", description = "With the immediate threat gone, can you help with some grim business?\n\nWe tauren do not bury our dead, we prepare the body for its return to the elements and place it at our sacred grave sites. Those killed in the Taurajo massacre have had no funeral, and I worry misguided Alliance soldiers will burn the bodies of the dead before the proper rites have been performed.\n\n{name}, please take this totem to Taurajo and perform services for Krulmoo, Dranh, Yonada, and Omusa. They ... didn't make it out of there. ", objectives = "Use the Funerary Totem on the corpses of Krulmoo, Dranh, Yonada, and Omusa in the ruins of Taurajo.", progress = "Have their spirits found peace with the Earthmother?", completion = "<Winnoa bows her head.>\n\nThank you." }
WordHunterWoW_QuestEN[24574] = { title = "To Harvest Chaos", description = "If I have truly sown chaos, it is time for reaping.\n\nThe lumbering outgrowths of plant life shamble through the imbued stream here, {name}. They are a direct manifestation of the unstable forces mutating this area. Slay as many as you can, and we might be able to slow the spread of the overgrowth further.\n\nAnd while you're at it...be on the lookout for parts of them that appear especially corrupted. Bring any such pieces to me.", objectives = "Kill 5 Outgrowths and find a Squirming Heart.", progress = "Cutting down the outgrowth will merely buy us some time. Have you found any suspicious pieces?", completion = "<Naralex slowly takes the squirming heart from you, visibly disturbed.>\n\nI've been a fool. The one truth I did not want to accept has been staring me in the face this entire time...this foul thing is proof of that.\n\nYou and I have much work to do." }
WordHunterWoW_QuestEN[24575] = { title = "Liberation Day", description = "We recently found out that the villagers at Emberstone survived most of the ravages of the Curse.\n\nUnfortunately their village wasn't as fortunate when it came to the Forsaken invasion.\n\nThe Forsaken have taken the villagers prisoner and are forcing them to work the nearby mine as slaves.", objectives = "Free 5 Enslaved Villagers inside the Emberstone Mine.", completion = "You've done it again, <name>.  The freed villagers are eager to help us against the Forsaken in any way they can." }
WordHunterWoW_QuestEN[24576] = { title = "A Friendly Chat...", description = "<Roka listens with disgust as you tell her why you're trying to track down Snivel.>\n\nYou mean I've been under the spell of an alchemist all this time? I can't believe I fell for that fraud! If I ever get my hands on that conniving little goblin, I'll tear him apart!\n\nIf he's finished his errands, he's on his way down to the zeppelin tower in the middle of Orgrimmar! Whatever you do, <name>, you can't let him board that zeppelin and get away with all this!\n\nHurry to the zeppelin tower before you miss him!", objectives = "Go to the zeppelin tower on the central bluff in  Orgrimmar and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.", progress = "Did you find the guy, or did he crawl under a rock?", completion = "You got his ledger? Really? That's great, <name>. There's probably loads of good information in here." }
WordHunterWoW_QuestEN[24577] = { title = "Desolation Hold Inspection", description = "Thanks to you, the immediate threat is over. But my work here in the Barrens is only beginning.\n\nHonor's Stand was captured and Taurajo was sacked while Warlord Gar'dul was in charge of the region. The Warchief has sent me here to clean up his mess.\n\nI would like you to ride into Desolation Hold to the south in advance of me and let Gar'dul know that it is time for a reckoning.\n\nTalk to me when you are ready to leave and I will assemble my vanguard to accompany you.", objectives = "Talk to Warlord Bloodhilt, then ride into Desolation Hold and inform Gar'dul that Warlord Bloodhilt is on his way.", progress = "What is this about? Why are you creating such a commotion in my camp?", completion = "<Gar'dul breaks into a sweat.>\n\nLook - ah - let's not discuss this here, in front of the men..." }
WordHunterWoW_QuestEN[24578] = { title = "The Blackwald", description = "It took a while, but I think I've put together what happened here.  At least partially.\n\nThere were survivors of the Curse in this town.  They joined others in the mountains, in Tempest's Reach.\n\nEveryone left, except the man who kept the journal, old man Bradshaw.  He noticed that the worgen attacks had stopped all of a sudden and decided to venture into the Blackwald.\n\nThere is an abandoned mill just northeast of town, it was where Bradshaw lived.  See if you can find any clues there.", objectives = "Investigate the Bradshaw mill just outside Stormglen Village.", completion = "I've been expecting you, <name>.  Do not be alarmed.\n\nMy name is Belrysa.  I am a priestess of the moon... a night elf.\n\nYou might not know my people, but the destinies of our two races have been linked since the Curse befell you." }
WordHunterWoW_QuestEN[24579] = { title = "Sartharion Must Die!", description = "Sartharion, the Onyx Guardian, watches over the eggs of the Twilight Dragonflight. He rests within the Obsidian Sanctum in the Chamber of the Aspects underneath Wyrmrest Temple.\n\nThe Council of Six has decreed that Sartharion must die!", objectives = "Kill Sartharion.\n\nThis quest can be completed with any difficulty or size raid.", completion = "With Sartharion slain, surely Deathwing and Sinestra's plans are now stalled." }
WordHunterWoW_QuestEN[24580] = { title = "Anub'Rekhan Must Die!", description = "Anub'Rekhan, once-mighty Spider Lord of the nerubian empire, has been taken by the Lich King and corrupted into a state of undeath.\n\nNow a crypt lord, he sits in his parlor in the Arachnid Quarter of Naxxramas, spinning strategies for Kel'Thuzad.\n\nThe Council of Six has decreed that Anub'Rekhan must die!", objectives = "Kill Anub'Rekhan.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Word of your success precedes you, <class>. Anub'Rekhan is no more. You did him a great service, <name>." }
WordHunterWoW_QuestEN[24581] = { title = "Noth the Plaguebringer Must Die!", description = "Noth the Plaguebringer, traitor and coward! Second only to the Lich King himself for the number of souls that have been Scourged!\n\nMake haste to Naxxramas. You will find him within the Plague Quarter hiding behind his undead minions.\n\nDestroy him! The Council of Six has decreed that Noth must die!", objectives = "Kill Noth the Plaguebringer.\n\nThis quest can be completed with any difficulty or size raid.", completion = "That's one less thorn in our side. With Noth destroyed, Scourge research into refining the means of creating the undead will grind to a halt." }
WordHunterWoW_QuestEN[24582] = { title = "Instructor Razuvious Must Die!", description = "Instructor Razuvious smugly struts about the Military Quarter of Naxxramas. It is said that only a death knight personally trained by him could possibly even withstand the prowess of his blade.\n\nYou and your group are going to prove everyone wrong.\n\nThe Council of Six has decreed that Razuvious must die!", objectives = "Kill Instructor Razuvious.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Well done, <class>. The Scourge military command out of Naxxramas has been thrown into disarray by Razuvious's demise." }
WordHunterWoW_QuestEN[24583] = { title = "Patchwerk Must Die!", description = "The so-called \"avatar of war\", Patchwerk is the ultimate abomination. It is also taking a heavy toll upon on our forces in the Dragonblight.\n\nI want you to assemble your companions and enter the Construct Quarter of Naxxramas. Disassemble the construct.\n\nThe Council of Six has decreed that Patchwerk must die!", objectives = "Kill Patchwerk.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Children everywhere will sleep easier knowing that Patchwerk is no more." }
WordHunterWoW_QuestEN[24584] = { title = "Malygos Must Die!", description = "Our resources are strained. Malygos, the Spell-Weaver, is draining all of the magic out of the world, consolidating it in the Eye of Eternity. Without magic, we are doomed.\n\n{class}, the Nexus War must be brought to an end. The Council of Six has decreed that Malygos must die!", objectives = "Kill Malygos.\n\nThis quest can be completed with any difficulty or size raid.", completion = "With Malygos defeated, the Nexus War should come to a swift conclusion. You have the gratitude of the Kirin Tor, <name>." }
WordHunterWoW_QuestEN[24585] = { title = "Flame Leviathan Must Die!", description = "Within the Formation Grounds sits Ulduar's first line of defense: Flame Leviathan.\n\nThe Kirin Tor have been provided with information suggesting that this Keeper-created machine is soon to be transported to an undisclosed location and let loose to wreak havoc upon the mortals of Azeroth.\n\nThis must not come to pass. The Council of Six has decreed that Flame Leviathan must die!", objectives = "Kill Flame Leviathan.\n\nThis quest can be completed with any difficulty or size raid.", completion = "I never cease to be amazed by the horrors that can be created through the use of technology." }
WordHunterWoW_QuestEN[24586] = { title = "Razorscale Must Die!", description = "Razorscale normally keeps to her aerie near the Colossal Forge in Ulduar. Of late, however, she has been spotted raining fire down upon lands outside of the titan complex.\n\nThough the broodmother's is a sad tale, she poses an imminent threat to all of Northrend. The Council of Six has decreed that Razorscale must die!", objectives = "Kill Razorscale.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Now Veranus can finally rest in peace." }
WordHunterWoW_QuestEN[24587] = { title = "Ignis the Furnace Master Must Die!", description = "The great fire giant, Ignis the Furnace Master toils away inside of Ulduar's Colossal Forge. Under orders from Loken, Ignis creates weapons that are terrifying in their power.\n\nThe Council of Six has decreed that Ignis must die!", objectives = "Kill Ignis the Furnace Master.\n\nThis quest can be completed with any difficulty or size raid.", completion = "I trust that you did not have to face too many of his iron construct assistants?" }
WordHunterWoW_QuestEN[24588] = { title = "XT-002 Deconstructor Must Die!", description = "Yet another strange construct of Mimiron, the XT-002 Deconstructor actually thinks that it is the keeper's son. Do not be fooled by its feigned innocence. It is a deadly machine!\n\nYou will find the Deconstructor within Ulduar's Scrapyard. The Council of Six has decreed that XT-002 Deconstructor must die!", objectives = "Kill XT-002 Deconstructor.\n\nThis quest can be completed with any difficulty or size raid.", completion = "The greatest weakness of Ulduar is its masters' blind faith in their inventions to protect it." }
WordHunterWoW_QuestEN[24589] = { title = "Lord Jaraxxus Must Die!", description = "Archmage Timear has foreseen a horrible event, which is about to transpire. A foolish gnome warlock is about to accidentally summon an Eredar lord of the Burning Legion into the middle of the Trial of the Crusader.\n\nYou must be there when it happens, {class}. If Lord Jaraxxus escapes, he will open a portal and the Burning Legion will spill forth into our world once more.\n\nThe Council of Six has decreed that Lord Jaraxxus must die!", objectives = "Kill Lord Jaraxxus.\n\nThis quest can be completed with any difficulty or size raid.", completion = "All of Azeroth is fortunate that Timear foresaw the Eredar lord's arrival and that you were there in time to slay him." }
WordHunterWoW_QuestEN[24590] = { title = "Lord Marrowgar Must Die!", description = "Lord Marrowgar is the guardian of the Frozen Throne within the Spire Chamber. Pieced together by the Lich King from the bones of a thousand vanquished adventurers, Marrowgar wields the power of the throne itself.\n\nWithout the destruction of this bone wraith, there is no hope of taking Icecrown Citadel.\n\nThe Council of Six has decreed that Lord Marrowgar must die!", objectives = "Kill Lord Marrowgar.\n\nThis quest can be completed with any difficulty or size raid.", completion = "The Frozen Throne is without its chief guardian thanks to you. Our attacks upon the Lich King's forces will be all the more successful now." }
WordHunterWoW_QuestEN[24591] = { title = "Changing of the Gar'dul", description = "When Bloodhilt arrives, I'd like to - ah - talk in private. Can you accompany me to make sure things stay on the level? This Bloodhilt is a, ah, he's a, he's a loose cannon.\n\n<Gar'dul tries to compose himself.>\n\nMeet me atop the northern tower and we'll talk with Bloodhilt together.", objectives = "Go to the top of the northern tower in Desolation Hold and help Warlord Bloodhilt \"Relieve\" Gar'dul of command." }
WordHunterWoW_QuestEN[24592] = { title = "Betrayal at Tempest's Reach", description = "King Greymane has been taken prisoner by Lord Godfrey in Tempest's Reach!\n\nHe managed to convince two of the eastern lords to go with his plan.  The fool seems to think he can strike a deal with the Forsaken by turning Greymane over to them.\n\nListen carefully, {name}.  We need to resolve this with as little bloodshed as possible.\n\nThis potion will allow you to sneak in undetected.  We need you to assassinate the traitorous lords before this gets out of hand!", objectives = "Drink Krennan's Potion of Stealth in Tempest's Reach and assassinate Baron Ashbury and Lord Walden.", progress = "Careful, <name>.", completion = "I wish it could've been avoided, <name>.  Let us ensure this is resolved without further bloodshed." }
WordHunterWoW_QuestEN[24593] = { title = "Neither Human Nor Beast", description = "It is time, {name}.  This... alchemy that has kept the beast inside you at bay will not last for long.\n\nThe first cursed worgen were night elf druids like our new allies.  They, however, abandoned the balance that the rest of their kind embraced and allowed the beast to take over their minds.\n\nIt is only fitting that their brethren be the ones that deliver us from the Curse.  Go, {class}.  Drink from the waters of Tal'doren and make peace with yourself.", objectives = "Drink from the Well of Tranquility, the Well of Balance and the Well of Fury.", progress = "It is always good to see you brother.", completion = "It is done then, <name>.  You are one of us now." }
WordHunterWoW_QuestEN[24594] = { title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell to enter the Sunwell Plateau. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Show the blade to Myralion Sunblaze at Quel'Delar's Rest once it is restored.", objectives = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "You have returned from the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!" }
WordHunterWoW_QuestEN[24595] = { title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. Once the blade is restored, return with it to Caladis Brightspear at Quel'Delar's Rest.", objectives = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "Tell me of what happened in the Sunwell, <name>.", completion = "This is unbelievable, <name>. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored." }
WordHunterWoW_QuestEN[24596] = { title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete the its restoration, then speak with Myralion Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", objectives = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened during your visit to the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!" }
WordHunterWoW_QuestEN[24597] = { title = "A Gift for the Emissary of Stormwind", description = "Did you want to make a Lovely Charm Bracelet for the Emissary of Stormwind? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", objectives = "Present a Lovely Charm Bracelet to Emissary Audwin Alston in Stormwind.", progress = "Well met, <class>. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet." }
WordHunterWoW_QuestEN[24598] = { title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete its restoration, then show it to Myralio Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", objectives = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What news do you bring from the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!" }
WordHunterWoW_QuestEN[24601] = { title = "The Nightmare Scar", description = "This confirms it. The overgrowth here is not being caused by a mere overabundance of energy.\n\nDo you understand? This is beyond what happened at the Wailing Caverns now. A rift into the Nightmare must have torn open in the middle of the very land we're standing on! And to think it's my fault...\n\nI'm done picking at the edges of this wound. Go to the west, to the center of the overgrowth, and meet me again there. We will dive into the heart of this corruption and force it shut!", objectives = "Help Naralex seal the Nightmare Scar.", progress = "We must not allow the nightmare to spread further into our world!", completion = "We've done it! The nightmare's connection to this place has been severed. The rest of the land is safe from this intrusion now, and in time, the abberations here will be subsumed by the balance of nature.\n\nI cannot thank you enough, <name>. By helping to restore order here, you've let me make amends for my foolish actions." }
WordHunterWoW_QuestEN[24602] = { title = "Laid to Rest", description = "In our hurried escape for safety, we disturbed the resting homes of our ancestors, {name}.  A grave sin, if you'll pardon the pun.\n\nIt is tradition that a small memento be buried on top of a Gilnean's graveyard, beneath the shallow earth.  The stampede of people fleeing these tunnels has unearthed these mementos and angered the spirits.\n\nFind them and bring them to me.  We'll see to it that the dead return to their eternal slumber.", objectives = "Obtain 5 Unearthed Mementos.", progress = "You're back, <name>.", completion = "Thank you, <name>.  Let us hope this works." }
WordHunterWoW_QuestEN[24603] = { title = "Don't Stop Bereavin'", description = "For a moment, I thought my hatred had stilled. My wife laid to rest, a final offering of the blood of her murderers to quell her tortured spirit. I thought perhaps peace would appeal to me.\n\nI was wrong.\n\nI will not rest now until every single filthy, squealing, murderous quilboar lays dead and broken! I cannot kill them fast enough with my own two hands.  Go and slay more for me, {race}.", objectives = "Kill 13 Razormane Quilboar.", completion = "Good. Take your reward; this is only a prelude." }
WordHunterWoW_QuestEN[24604] = { title = "Concern for Mankrik", description = "I would ask a favor of you, {class}.\n\nA warrior named Mankrik passed through our camp not long ago, on a lonely journey. His wife was killed by the quilboar, long ago, and he still seeks revenge. I cannot forget his eyes...burning with inconsolable hatred, every waking moment.\n\nWe did not talk long, but I cannot bear to think of him out there alone. Please, bring this to Mankrik, and tell him it is from me... ", objectives = "Bring Mahka's Gift to Mankrik, south of Firestone Point.", progress = "<Mankrik snarls.>\n\nWhat is it!? I'm busy!", completion = "Mahka sent you?\n\n<Mankrik's fury quells for a moment.>\n\nIt is a small comfort. But nothing can console me until I am done here." }
WordHunterWoW_QuestEN[24606] = { title = "Blood of the Barrens", description = "This bright red stone, found clutched in the grasp of a quilboar, has been carefully carved into the likeness of a great boar, with thorny vines sprouting from its back. Its surface is smooth and worn with care.\n\nDid the quilboar make this? If you find others, maybe one of the shaman at Firestone Point could tell you more about them.", objectives = "Collect 6 Blood Shard Trinkets from Razormane Quilboar.", progress = "Yes?", completion = "These are blood shards. They used to be found all over the Barrens.\n\nIt's said they were formed from the blood of Agamaggan, the great demigod that the quilboar sprang from. I knew the quilboar prized them, but nobody would think they'd take the time and care to carve them like this one...\n\nThere may be more to learn here." }
WordHunterWoW_QuestEN[24607] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Nortet to the east.", objectives = "Meet with Nortet in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually look ta be in shape though. Steady hands. Fierce eyes. I may be able ta turn ya into a real <class>.\n\nLets not waste anymore time 'den." }
WordHunterWoW_QuestEN[24608] = { title = "Mangletooth", description = "I no longer care for honor or glory, {class}. All that matters to me is that the quilboar die, by any means, at anyone's hand.\n\nMangletooth, the chief of these filthy Razormane, sits in his lair to the northwest, atop a hill. End his life.\n\nI plan to stay here, and pile these bodies until no more vermin run squealing from the Kraul to face me...", objectives = "Kill Mangletooth.", progress = "Is he dead?", completion = "Good.  Good! They will all die!  Their chieftains, and their women, and their children, and their foul pets!" }
WordHunterWoW_QuestEN[24609] = { title = "A Gift for a Lord of Ironforge", description = "Did you want to make a Lovely Charm Bracelet for Muradin Bronzebeard? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", objectives = "Present a Lovely Charm Bracelet to Muradin Bronzebeard in Ironforge.", progress = "Well met, <class>. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet." }
WordHunterWoW_QuestEN[24610] = { title = "A Gift for the High Priestess of Elune", description = "Did you want to make a Lovely Charm Bracelet for the High Priestess of Elune? I'm sure she'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", objectives = "Present a Lovely Charm Bracelet to Tyrande Whisperwind in Darnassus.", progress = "Well met, <class>. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet." }
WordHunterWoW_QuestEN[24611] = { title = "A Gift for the Prophet", description = "Did you want to make a Lovely Charm Bracelet for the Prophet of the Exodar? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", objectives = "Present a Lovely Charm Bracelet to Prophet Velen in the Exodar.", progress = "Well met, <class>. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet." }
WordHunterWoW_QuestEN[24612] = { title = "A Gift for the Emissary of Orgrimmar", description = "Did you want to make a Lovely Charm Bracelet for the Orgrimmar Emissary? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", objectives = "Present a Lovely Charm Bracelet to Emissary Drunzek Skullband in Orgrimmar.", progress = "Well met, <class>. Did you have something for me?", completion = "My \"thanks\" for this Lovely Charm Bracelet." }
WordHunterWoW_QuestEN[24613] = { title = "A Gift for the Banshee Queen", description = "Did you want to make a Lovely Charm Bracelet for the Banshee Queen? I'm sure she'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", objectives = "Present a Lovely Charm Bracelet to Lady Sylvanas Windrunner in Undercity.", progress = "Well met, <class>. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet." }
WordHunterWoW_QuestEN[24614] = { title = "A Gift for the High Chieftain", description = "Did you want to make a Lovely Charm Bracelet for the High Chieftain? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", objectives = "Present a Lovely Charm Bracelet to Baine Bloodhoof in Thunder Bluff.", progress = "Well met, <class>. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet." }
WordHunterWoW_QuestEN[24615] = { title = "A Gift for the Regent Lord of Quel'Thalas", description = "Did you want to make a Lovely Charm Bracelet for the Regent Lord of Quel'Thalas? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", objectives = "Present a Lovely Charm Bracelet to Lor'themar Theron in Silvermoon City.", progress = "Well met, <class>. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet." }
WordHunterWoW_QuestEN[24616] = { title = "Losing Your Tail", description = "You must have many questions, {name}.  And they will be answered in time.\n\nI know why you're here and what you're looking for.\n\nI can't lead you there with the enemy tracking you.\n\nOne of Sylvanas's scouts has been following your tracks.  You can't lead the Forsaken to the place you seek.  Take this talisman and walk along the road just north of here.\n\nLet the ranger lure you to her trap and use the power of the talisman to break free and counterattack.", objectives = "Use Belysra's Talisman to defeat the Dark Scout.", progress = "Is it done, <name>?", completion = "Well done, <name>.  The scout never had a chance." }
WordHunterWoW_QuestEN[24617] = { title = "Tal'doren, the Wild Home", description = "There are others like you, {name}.  And they too, were lost and confused.\n\nThere is a place where you belong.\n\nTal'doren, the wild home, was once home to an order of druids who took the shape of wolves.\n\nIt is there that you will find the answers you seek.  It is also there that you will find someone who can offer guidance.  An old friend.", objectives = "Speak to Darius Crowley at Tal'doren, in the heart of the Blackwald.", completion = "You're all right, <name>!  I've been waiting for this day for a long time, it truly is great to see you friend.\n\nI've heard of what you've done and I'm thankful... especially for Lorna -- she's all I've left.  I will send for her right away." }
WordHunterWoW_QuestEN[24618] = { title = "Claim the Battle Scar", description = "We have fought the Alliance to a standstill here, even as the land beneath our feet falls apart. To the east you will find the Battlescar, a wide swath of decimated terrain. It is little more than a line in the sand, but it must be OUR line.\n\nIn the center of the scar you will find a flag marker designating who controls it. Scout out the flag.\n\nIf it's not already ours, capture it for the Horde - it will swing the battle in our favor. Investigate the scar and kill anyone you find in there!", objectives = "Go to the Battlescar. Scout out the flag marker and kill 10 Triumph Vanguard soldiers.\n\nCapturing the flag will give all Horde players in the scar a combat advantage.", completion = "Excellent! You're my kind of <class>, <name>.\n\nWith your help, we will throw these invaders back into the sea." }
WordHunterWoW_QuestEN[24619] = { title = "Parts-is-Parts", description = "I've always wanted to try making an abomination. It looks simple enough, but you know how it is when you learn things from a book. There's no substitute for doing!\n\nFirst, I'm going to need parts. Lots of parts. And you're going to get them for me.\n\nNo need to be picky: human, orc... it doesn't matter. Parts is parts.\n\nJust be sure the corpses you harvest come from the Battlescar, so I know they're fresh.\n\n<Calder presses a rusted, gore-covered bonesaw into your hands and smiles disarmingly.> ", objectives = "Use Calder's Bonesaw on corpses within the Battlescar and collect 15 Severed Extremities.", progress = "Did you get my parts? Let me see them!", completion = "<Calder peers into the sack of extremities and licks his lips with a dry, black tongue.>\n\nOh my. This is exciting.\n\n Aren't you excited, <name>?" }
WordHunterWoW_QuestEN[24620] = { title = "Hearts-is-Hearts", description = "These parts - so lovely! Muscle and sinew and fingers and toes ... I am SO hungry right now.\n\nBut work must come first. Once I stitch this pile of parts together I'm going to need a heart strong enough to pump sludge through this rat's nest of veins. I would use my own heart, but it's a shriveled up husk resembling a turnip.\n\nNo, I need some real power. Get me a kodo heart from one of those giant landquaker bulls to the south of the Battlescar.", objectives = "Slay a Landquaker Bull south of the Battlescar and collect an Enormous Kodo Heart.", progress = "You've gotta have heart, <name>. All you really need is heart.", completion = "<Calder grasps the gigantic heart in both hands, squeezing it and listening to the valves slurp and squish.>\n\n<His pale mask of a face splits open into an enormous, childlike grin.>\n\nIt is so very important to love one's work, wouldn't you agree, <name>?" }
WordHunterWoW_QuestEN[24621] = { title = "Smarts-is-Smarts", description = "My monstrosity is taking shape! All that's left is to stuff his skull with something useful.\n\nI'm talking about brains, {name}. And here I'm going to be picky. The abomification process causes significant brain damage so it's best to start with someone smart.\n\nOne of the Alliance officers should do nicely. Seek out one of the Captains on the far side of the Battlescar and try not to damage the goods while you kill him.", objectives = "Kill a Triumph Captain on the far side of the Battlescar and acquire a Fresh Brain.", progress = "Brraaaaaaiiinnnnss...", completion = "<Calder holds the brains in an outstretched hand while withdrawing a gore-caked multi-tool from his belt.>\n\nWonderful work! Now the secret here is to leave the reptilian nervous systems intact while removing the higher cognitive functions. We can't have our new friend developing a conscience or remembering he's Alliance...\n\n<Calder digs and snips at the brain, removing large chunks.>\n\nAnd... we're finished! How lovely." }
WordHunterWoW_QuestEN[24622] = { title = "A Troll's Truest Companion", description = "If ya lookin' for something ta do, we need some more raptors moved over to da pens. If ya head over to da island south of here, you can be meetin' with our caretakers and dey can set ya up.\n\nDey might appreciate a hand too. Got ta be spreadin' da love, ya know?", objectives = "Speak to Kijara on Bloodtalon Shore.", completion = "Nice ta see new faces 'round here, mon. It's easy ta get ta feelin' isolated since we left Orgrimmar." }
WordHunterWoW_QuestEN[24623] = { title = "Saving the Young", description = "I actually have somethin' really important dat I could use help with, if ya be willin', mon.\n\nOur hatchlins' are bein' stolen by someone on da next island. At first I thought dey were just runnin' away or that nature be claimin' dem, but we are missin' more than a dozen of da little guys now.\n\nPlease head to Zalazane's Fall to da northwest and point da little hatchlins back dis way. Poor tings.", objectives = "Use the Bloodtalon Whistle to rescue 12 Lost Bloodtalon Hatchlings.", progress = "Poor little tings.", completion = "Thank ya so much! They can be vicious when provoked, but most of da time dey don't know betta." }
WordHunterWoW_QuestEN[24624] = { title = "Mercy for the Lost", description = "The fiend who stole our raptors has been corruptin' dem with some kind of magic. Now dat dey've grown with dis corruption inside of them, I fear dere's little we can be doin' to save dem outside grantin' them da peace of death. Go ta Zalazane's Fall, northwest of here, an' see da task done.\n\nI hope ya can stomach dae work. I don't tink I could bring myself ta do da deed, even knowin' that it be needed.", objectives = "Kill 8 Corrupted Bloodtalon Raptors.", completion = "Thank you, <class>.\n\nIt will be takin' brave and determined people like you ta drive da Darkspear up again. I hope dere are more people even half as dedicated to come." }
WordHunterWoW_QuestEN[24625] = { title = "Consort of the Sea Witch", description = "I been investigatin' our corrupted Bloodtalons troubles and I think I've found da source. A lone naga. He was holdin' a red orb aloft over our hatchlings and I could see dem... changin'.\n\nI'm certain he tinks his thievery and spellcastin' have gone unnoticed, so ya should be able ta catch him unawares. Kill dis naga and bring me back dat vile orb - you'll be findin' him to da northwest, at Zalazane's Fall.", objectives = "Kill Naj'tess and retrieve his orb.", progress = "Da naga have been our enemies for a long, long time, and our previous encounters with dem have not gone well. It be clear dat dis time will be different. Tings have changed, and you be part of dat change.", completion = "Well done, <name>! Dis naga has set us back quite some time, but nothin' will be holdin' us down foreva.\n\nIt's good ta be havin' ya wit us, <name>. Ya have a fierce heart within ya." }
WordHunterWoW_QuestEN[24626] = { title = "Young and Vicious", description = "Ya be a good one, {name}.\n\nMoraya was askin' for new raptors ta train. We shouldn't keep her waitin' any longa! I have a few other recruits bringin' some over as well, but I have a special one dat I've been promisin' Moraya for a while.\n\nSwiftclaw be one of our fastest and bravest young raptors yet, but he can be a bit unruly. I'll lend ya da lasso, I just need ya to catch him somewhere on da island here and steer him over to da pens on da main isle. I doubt he'll be makin' it easy on ya though.", objectives = "Capture Swiftclaw and bring him back to the pens near Darkspear Hold.", progress = "Did ya come back wit one of the raptors I sent ya for?", completion = "Swiftclaw! Kijara was tellin' me about him and he sounded like he'd be a handful. I don't mind da challenge - it's da spirited ones like dat that be makin' da bravest and truest companions when real times of need be comin'.\n\nTank ya, hon. Ya've been very helpful." }
WordHunterWoW_QuestEN[24627] = { title = "At Our Doorstep", description = "The night elves have taught us much during this time, {name}.  They've taught us who we are and where we come from.\n\nThanks to them... thanks to this place... we're no longer mere beasts.  We have regained free will.\n\nThe Forsaken aren't here for our land alone.\n\nThey're looking for something we possess.  An artifact capable of uncontrollably spreading the Curse to all humanity.  We cannot let them find it.\n\nSylvanas's banshees have come very close.  Help my trackers take them out.", objectives = "Kill 6 Howling Banshees.", completion = "You are as good as I remember, <name>.  It is good to have you back." }
WordHunterWoW_QuestEN[24628] = { title = "Preparations", description = "What you know as the Curse began as a heresy among our brethren.\n\nFaced with a losing battle against demonic forces, the Druids of the Pack eschewed the balance they were sworn to and allowed the beast to overtake them.\n\nThey were banished to the Emerald Dream where they live in eternal slumber under a tree identical to this one, but not before their curse spread to others.\n\nToday our ceremony will restore balance to your people. Bring me the leaf that grows only in Tal'doren's vicinity.", objectives = "Bring 6 Moonleafs to Vassandra.", progress = "You've returned, <name>.", completion = "These simple leaves grow by Elune's grace.  They will help your mind understand the need for balance and your soul will permanently earn mastery over the beast." }
WordHunterWoW_QuestEN[24629] = { title = "A Perfect Puff of Perfume", description = "You look like a real go-getter, <class>. How about we work out a little win-win scenario?\n\nCrown's looking to offer samples of our latest holiday-themed products to as many potential customers as possible. Help us share the love, and we'll give you discounts on some great Crown merchandise!\n\nYour time, our money, friend. What do you say?", objectives = "Spray 10 people with the Crown Perfume Sprayer.", completion = "Great work, <name>! People will come running to buy Crown perfumes now that they've had a chance to sample their wonders.\n\nHere's a little something for helping us out." }
WordHunterWoW_QuestEN[24630] = { title = "The Crone of the Kraul", description = "The five of us have communed with the spirits, and found the source of the Quilboar's aggression. Charlga Razorflank leads them from within Razorfen Kraul. She holds the promise of Agamaggan's resurrection over their heads, whipping the tribes into frenzy to raze and pillage the land for her.\n\nPlease, <class>, put a stop to this. Without Charlga, the quilboar may not be saved, but they may at least be less dangerous.You will receive:", objectives = "Kill Charlga Razorflank in Razorfen Kraul." }
WordHunterWoW_QuestEN[24631] = { title = "Flightmare", description = "The Alliance has hired in Wildhammer mercenaries to control the skies over the Battlescar. I believe these same gryphon-riders were the ones to firebomb Taurajo during the attack.\n\nI want our skies scoured clean.\n\nThe wildhammer dwarves fly low enough for a sharp-eyed {class} to hook them. Take this. Target their gryphons and dismount the riders - once grounded, show them no mercy.", objectives = "Use Tomusa's Hook on Triumph War Gryphons to dismount and kill 5 Wildhammer Mercenaries.", progress = "The Wildhammer are fierce fighters, in the air or on the ground. How goes the battle?", completion = "<Tomusa snorts as he takes back his hook.>\n\nVengeance feels hollow. Still. I could not allow them to go unpunished." }
WordHunterWoW_QuestEN[24632] = { title = "Tauren Vengeance", description = "My people are not wrathful by nature, but sometimes a thirst for justice causes us to take up arms in anger.\n\nMy old friend Gann Stonespire, on learning of the butchery in Taurajo, flew into a fury. Tribal elders could no longer hold his rage in check.\n\nNow he has all but parted ways with the Horde. He's gone rogue, {name}, and seeks to lash out at the Alliance with a small band of like-minded partisans.\n\nIf you, too, seek vengeance, you will find him southeast of here, at the foot of Bael Modan.", objectives = "Seek out Gann Stonespire at Spearhead in Southern Barrens.", completion = "<Gann looks you up and down.>\n\nWe could use your help, <class>. But this is not a skirmish. We fight here to strike a killing blow... or die trying." }
WordHunterWoW_QuestEN[24633] = { title = "Mahka's Plea", description = "I can't put him out of my mind, {name}. Sometimes at night, I can hear his howls of rage and suffering, echoing across the plains. To imagine him out there, alone and in such pain...\n\nPlease, I must ask a favor of you. Go to Mankrik, and tell him to come see me.", objectives = "Talk to Mankrik.", progress = "I am sorry to ask this of you, but I want him to come here. He needs to leave that place of death...", completion = "Thank you, <name>." }
WordHunterWoW_QuestEN[24634] = { title = "Intelligence Warfare", description = "I am convinced the Alliance is using spies to scout the field and pass along information. They knew to strike at Taurajo while the hunters were afield. And they countered every one of Gar'dul's moves like he was an open book.\n\nWell {name}, I for one will not be outplayed. Not here. We will win the battle for intelligence.\n\nEven now I hear reports of Alliance operatives slinking around in the shadows, especially here, outside these very walls. Kill them and bring me back something of use.", objectives = "Kill a Barrens Operative and retrieve the SI:7 Briefings.", progress = "Watch your back, <class>. They could be anywhere.", completion = "Hah! The fool didn't destroy these orders.\n\nLet's see what we can learn..." }
WordHunterWoW_QuestEN[24635] = { title = "A Cloudlet of Classy Cologne", description = "You seem the enterprising sort, <class>. How about we make a little deal?\n\nCrown wants to offer samples of our latest holiday-themed products to as many potential customers as we can. Help us share the love while earning some fantastic Crown merchandise!\n\nYour time, our money, friend. What do you think?", objectives = "Spray 10 people with the Crown Cologne Sprayer.", progress = "That cologne isn't going to give itself out, you know.\n\nGet spraying!", completion = "Nice work, <name>! People will be buying Crown colognes by the crate-load now that they've had a chance to try them.\n\nHere's a little something for helping us out." }
WordHunterWoW_QuestEN[24636] = { title = "Bonbon Blitz", description = "I can see you've got an eye for opportunity, <class>. What do you say we make a little coin together?\n\nCrown needs to push samples of our latest holiday-themed products to every potential customer in the city. Help us share the love, and we'll share some of that amazing Crown merchandise with you!\n\nYour time, our money, friend. We got a deal?", objectives = "Toss 10 people samples from the Crown Chocolate Sampler.", progress = "You know, those chocolates aren't going to fling themselves at people.\n\nYou need to get to work!", completion = "Lovely work, <name>! People will be tripping over one another to get Crown chocolates now that they've had a chance to taste those sweet, romantic treats.\n\nHere's a little something for helping us out." }
WordHunterWoW_QuestEN[24637] = { title = "The Butcher of Taurajo", description = "This operative had orders to secure the roadways between the Alliance command and Fort Triumph. General Hawthorne is on the move.\n\n<Bloodhilt crumples the documents in his fist.>\n\nIt's HIM, {name}! Hawthorne - I spit the name - he is the one who ordered the assault on Taurajo! Now we know when and where to strike him down. Quickly, follow the road north of the Battlescar and meet up with my assassin Karthog. CRUSH Hawthorne and string his body up along the road!", objectives = "Speak with Karthog, then lure out and assassinate General Hawthorne.", completion = "<Upon hearing the news, Bloodhilt snorts. His eyes gleam. He tips his head back and bellows a wet, cackling laugher that echoes between the blackened walls of Desolation hold and reverberates throughout the hills beyond.>\n\nSo it is done! The Butcher of Taurajo is felled at last. Cut down in the streets like a dog. Fitting.\n\nYou have done well, <name>. You've sowed fear into our enemies, and soon we will reap the harvest!" }
WordHunterWoW_QuestEN[24638] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's right outside Orgrimmar's gates, to the west! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon just west of Orgrimmar's gates in Durotar, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24639] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", objectives = "Destroy 6 Tiki Targets.", progress = "Strength isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. Everytin has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya swings - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go." }
WordHunterWoW_QuestEN[24640] = { title = "The Arts of a Warrior", description = "As ya get bettah' at fightin', you'll start to find new tings that ya nevah knew you could do.\n\nWanna see? Go, train up some, and learn someting new.\n\n'Den come back and ya can show me.", objectives = "Reach level 3 to learn Charge. Practice using Charge against a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya." }
WordHunterWoW_QuestEN[24641] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese." }
WordHunterWoW_QuestEN[24642] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day." }
WordHunterWoW_QuestEN[24643] = { title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", objectives = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear." }
WordHunterWoW_QuestEN[24644] = { title = "Troll Introduction Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[24645] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just outside Ambermill in Silverpine Forest. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Thugs and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Ambermill in Silverpine Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24646] = { title = "Take Back What's Ours", description = "Ever since the Forsaken invaded Gilneas, we've tried to keep the location of the Scythe of Elune secret.   We moved it at night to one of many safe locations.  The Dark Rangers got close, but never found it... until now.\n\nThey were last spotted at the Woods' End Cabin, west of here.  Blow this horn when you find them and Tobias and his trackers will engage the Dark Rangers.\n\nOnly then will it be safe for you to venture inside the cabin and take back the scythe.  Hurry, {name}.  It must not reach Sylvanas.", objectives = "Blow the Horn of Tal'doren at the Woods' End Cabin and retrieve the Mysterious Artifact inside.", progress = "Do you have the scythe, <name>?", completion = "I knew we could count on you.  You've done well, <name>." }
WordHunterWoW_QuestEN[24647] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just outside the village of Hillsbrad in -- you guessed it -- Hillsbrad Foothills. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Dusters and use Snagglebolt's Khorium Bomb to destroy one chemical wagon just outside of Hillsbrad Village in Hillsbrad Foothills, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24648] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's near Sentry Point, just outside Theramore in Dustwallow. Don't give me that look, okay? This is a problem for us, too. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Hoodlums and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Theramore in Dustwallow Marsh, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24649] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's to the east of Aerie Peak in the Hinterlands. Don't give me that look, okay? This is a problem for the Horde, too. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Agents and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Aerie Peak in the Hinterlands, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24650] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's in Winterspring, just east of Everlook. Oh, now this is personal. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Sprinklers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Everlook in Winterspring, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24651] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's just east of Shattrath, in Terokkar Forest. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Underlings and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Shattrath City in Terokkar Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24652] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in the Forlorn Woods of Crystalsong, northwest of the Mirror of Twilight. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Sprayers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon in the Forlorn Woods of Crystalsong Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24653] = { title = "Echoes of Agamaggan", description = "I think the quilboar are being driven by more than just crude desire. Would you help me look into this further?\n\nTo the west, scattered among the quilboar's settlements and camps, I've noticed boar skulls. They gleam from a distance, polished smooth...distinct from the remains littered in their waste piles. I think these may be objects of worship.\n\nBring me several of these to examine, {name}.", objectives = "Collect 3 Polished Boar Skulls.", progress = "Do you have the skulls?", completion = "Yes, these are clearly symbols of Agamaggan. But if the quilboar are still devoted to their dead god, what is the source of their vicious agression?  It is said Agamaggan was noble, and even gave his life fighting the Burning Legion...\n\nA moment, <name>. We must confer with the spirits." }
WordHunterWoW_QuestEN[24654] = { title = "Silithissues", description = "The silithid! They're bugs, {name}. Or something like bugs. They're not natural... and we built a fortress on the equivalent of an anthill.\n\nTake this burning pitch. It'll set the buggers on fire and plug up their burrows at the same time. Be careful when you pour this stuff on there - the silithid will come out in swarms!\n\nLook for silithid mounds around the exterior of Desolation Hold. They look like heaps of sand. Kill anything that crawls out.", objectives = "Use the Bucket of Burning Pitch on Silithid Mounds and kill 10 Silithid Swarmers as they emerge.", progress = "The Alliance is nothing. Swarms of those critter-crawlys?\n\n<Crawgol shudders.>", completion = "You're covered in hot tar and bug juice! Don't worry, friend. It'll come off.\n\nSomeday." }
WordHunterWoW_QuestEN[24655] = { title = "Something Stinks", description = "Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume.\n\nTake this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.", objectives = "Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Inspector Snip Snagglebolt in Stormwind.", progress = "You analyze that reek yet, kid?", completion = "Hey, thanks, kid. Give it over, let's take a look.\n\n<He takes the device from you and fiddles with it.>\n\nOh, that ain't good." }
WordHunterWoW_QuestEN[24656] = { title = "Pilfering Perfume", description = "I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff.\n\nDon't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like.\n\nI'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.", objectives = "While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Stormwind, then return the package they toss you to Inspector Snip Snagglebolt in Stormwind.", progress = "Did they toss ya a crate to deliver?", completion = "You got it, huh? Good job, kid. Top notch. Let's see what we got here.\n\n<He cracks open the crate and rummages around inside.>" }
WordHunterWoW_QuestEN[24657] = { title = "A Friendly Chat...", description = "<Marion listens with horror as you tell her why you're trying to track down Snivel.>\n\nYou mean, he might've used some kind of chemical on me? Ew! I can't believe I fell for that fraud!\n\nIf he's finished all of his errands, he's on his way down to the docks to catch a ship to the South Seas! Whatever you do, <name>, you can't let him get away with this.\n\nHurry down to Stormwind Harbor before you miss him!", objectives = "Go to Stormwind Harbor and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.", progress = "Did you find the guy, or did he crawl under a rock?", completion = "You got his ledger? Really? That's great, <name>. There's probably loads of good information in here." }
WordHunterWoW_QuestEN[24658] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's northeast of Westbrook Garrison right outside in Elwynn! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon northeast of Westbrook Garrison in Elwynn Forest, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24659] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just south of the Grove of the Ancients in Darkshore. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Thugs and use Snagglebolt's Khorium Bomb to destroy one chemical wagon south of the Grove of the Ancients in Darkshore, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
WordHunterWoW_QuestEN[24660] = { title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just southeast of Darkshire in Duskwood. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", objectives = "Kill 5 Crown Dusters and use Snagglebolt's Khorium Bomb to destroy one chemical wagon at the abandoned farm southeast of Darkshire in Duskwood, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya." }
