WordHunterWoW_QuestEN[24667] = { title = "Firestone Point", description = "I've been on top of this silithid situation for almost a month, which makes me the local expert. Just last week the Earthen Ring was visiting, and wanted me to write down everything I know.\n\n<Crawgol hands you a tattered book.>\n\nI'm not much of a writer. Or a reader, for that matter. But this book is probably the most definitive thing ever written about this foe.\n\nDeliver it to Tauna Skychaser down in Firestone Point. It's south of here, just west of the main road.", objectives = "Deliver Crawgol's Silithid Field Guide to Tauna Skychaser at Firestone Point in Southern Barrens.", progress = "Ah, do you bring news from up north?", completion = "Is this from Crawgol? Wonderful! Despite all the turmoil in the world, we can't turn our back on the silithid threat. It is important to have people like Crawgol studying our enemy closely and learning its secrets for the fight ahead!\n\n<Tauna opens the book and glances over the first page. Her face falls.>\n\nOh. Well. I suppose it's something, at least." }
WordHunterWoW_QuestEN[24671] = { title = "Cluster Cluck", description = "Ridiculous! The greatest goblin mind of all time reduced to food detail? I made the Micro Mechachicken just for this reason and they let it get away!\n\n<Hobart turns a deeper shade of green as his blood pressure rises.>\n\nDo I look like I should be rounding up escaped cluckers? No, my friend, not I! Bamm most definitely, though he's too lazy.\n\nYour station in life has recently taken a turn for the worse. You do it!\n\nTake these remote control fireworks and attach them to the cluckers.", objectives = "Capture 10 Wild Cluckers by attaching remote control fireworks to them.", progress = "Not enough cluckers, <name>. We'll all starve.", completion = "Success! Was there ever any doubt?\n\nGreely, fire up the poultryizer!" }
WordHunterWoW_QuestEN[24672] = { title = "Onwards and Upwards", description = "I will do as Darius asked and have our people move through the Blackwald.\n\nYou ought to catch up with King Greymane.  He and Krennan went into Tempest's Reach after Lord Godfrey confirmed survivors had made their dwelling there.\n\nFollow the road out of Stormglen into the mountains.  I asked Krennan to wait for you at the bridge before Tempest's Reach.", objectives = "Find Krennan Aranas on the road to Tempest's Reach.", completion = "<name>!\n\nGenn... they've taken Genn... they've taken... our king!" }
WordHunterWoW_QuestEN[24673] = { title = "Return to Stormglen", description = "It'll be a long time before our nation comes together again.  The old political divisions pale in comparison to what divides us now.\n\nYet if there was ever a time for us to come together and unite against a common enemy, it is now.  And it is you, {name}, who have proven able to bridge the gap between our people.\n\nReturn to Stormglen and tell them it is safe to go through the Blackwald on their way to Tempest's Reach.  We will take care of any Forsaken who follow them.", objectives = "Speak to Gwen Armstead in Stormglen.", completion = "King Greymane gave me a brief rundown of the plan before he set off for the Blackwald.  Doesn't make it sound any less crazy." }
WordHunterWoW_QuestEN[24674] = { title = "Slaves to No One", description = "I was one of the few that escaped, {name}.  When the Forsaken took over our town and our mine, they treated us with utmost cruelty.\n\nThose of us who were weak and could not endure hard labor were worked to death by the abomination known as Brothogg.\n\nMy wife was among his victims, {class}, and I swore that one day her death would be avenged.  I am too frail now, but you can deliver justice... for my wife... for Gilneas!", objectives = "Slay Brothogg the Slavedriver inside Emberstone Mine.", completion = "I thank you, <name>.  Our people will no longer suffer under that monstrosity's yolk." }
WordHunterWoW_QuestEN[24675] = { title = "Last Meal", description = "I'm not dumb, {name}.  I know what's ahead of us.\n\nOur people are going to go through those gates and fight against an enemy that is better trained, has more numbers and better weapons than us.\n\nEven if we succeed, it'll be at a great cost.  For most of us, today's meal will be the last.\n\nI cannot fight, but I sure can cook.  Bring me meat from the stags that roam this area and I will ensure that the last meal these folks get will be their best.", objectives = "Obtain 10 Sides of Stag Meat.", progress = "Did you get what I needed, <name>?", completion = "I thank you, <name>.  Our men and women will have a last good meal before they set off for battle." }
WordHunterWoW_QuestEN[24676] = { title = "Push Them Out", description = "The people are free, but the town is still occupied by the Forsaken.  They're cut off from their main force, so if we're to drive them out, now's our chance.\n\nTheir leader, Executor Cornell, is known  for his unbound ruthlessness.  Also among them is Valnov the Mad, a so-called scientist who carries out inhuman experiments on villagers too old to work the mines.\n\nTake care of them all.", objectives = "Slay 4 Forsaken Infantry, Executor Cornell and Valnov the Mad in Emberstone Village.", progress = "You're back, <name>.", completion = "We have the people of Emberstone on our side now thanks to you." }
WordHunterWoW_QuestEN[24677] = { title = "Flank the Forsaken", description = "I thank you, {name}.  We can't rest on our laurels, however.\n\nWe found out about a mining town, currently under Forsaken occupation.  We sent some of my men, along with Crowley's daughter to the nearby livery stables to begin operations there.  Liam should be joining them shortly.\n\nI'll stay here and organize the final push for Gilneas City.  Speak to Lord Hewell to secure a horse to get you there.", objectives = "Speak to Lord Hewell to obtain a ride to the Livery Outpost and report to Lorna Crowley.", completion = "I am glad to have you here, <name>.  We're surrounded by Forsaken on all sides and can use all the help we can get." }
WordHunterWoW_QuestEN[24678] = { title = "Knee-Deep", description = "It's time to pack it in, {name}.  Most of our people have made it through -- it's your turn now.\n\nTake this torch, you're going to need it.  The tunnel is full of nasty, knee-biting critters of the worst kind.  Use it to keep them at bay.\n\nSpeak to Krennan on the other side.", objectives = "Use the Half-Burnt Torch to get to the other side of the tunnel beneath Gilneas City.\n\nProvided item:", completion = "You're here, <name>.  Most everyone made it through, but now we're stuck here... surrounded by our own... dead!" }
WordHunterWoW_QuestEN[24679] = { title = "Patriarch's Blessing", description = "You've done it, {name}.  Even in these times we must honor our dead.\n\nTake these offerings and place them at Aderic's tomb.\n\nLet's hope that's enough to placate the ghosts of our ancestors.", objectives = "Place the Blessed Offerings at Aderic's Tomb.", progress = "Is it done, <name>?", completion = "It's done, <name>.  The dead return to their slumber." }
WordHunterWoW_QuestEN[24680] = { title = "Keel Harbor", description = "We might've lost our city, but at least it looks like the dead have forgiven us.\n\nMeet with the rest of the survivors in Keel Harbor.\n\nI'm sure there's plenty to do before we're in the clear.  Genn hasn't arrived yet, so I suppose Lord Crowley will be in charge there.", objectives = "Speak to Lord Darius Crowley at Keel Harbor in Gilneas.", completion = "It's good to see you again, <name>." }
WordHunterWoW_QuestEN[24681] = { title = "They Have Allies, But So Do We", description = "The night elves made good on their promise.  They've brought ships and are ready to offer us sanctuary in their lands.\n\nUnfortunately, the Forsaken's allies have arrived as well.\n\nThe orcs are advancing upon us while the Horde gunship prevents the transport ships from taking our people to safety.\n\nThe druids are holding the enemy back, but won't last long.  Fortunately, the elven ships were carrying siege weapons.  Take one of the glaive throwers and meet the enemy head on.", objectives = "Use the Night Elven Glaivethrower to slay 40 Orc Raiders, 8 Wolfmaw Outriders and 4 Orcish War Machines.", progress = "You're back!", completion = "It's almost over, <name>.  Only one obstacle remains between us and survival." }
WordHunterWoW_QuestEN[24682] = { title = "The Pit of Saron", description = "Quickly, through the portal! I'll find you on the other side.", objectives = "Meet Lady Sylvanas Windrunner inside the entrance to the Pit of Saron.", completion = "Incapable fools.\n\nI begin to wonder if any of these louts from the tournament will be of any use at all. Perhaps you'll prove me wrong." }
WordHunterWoW_QuestEN[24683] = { title = "The Pit of Saron", description = "Quickly, through the portal! I'll meet you on the other side.", objectives = "Meet Lady Jaina Proudmoore just inside the Pit of Saron.", completion = "I underestimated this Scourgelord, and it's my men that paid for it.\n\nWhen I think that my guilt over Arthas' betrayal cannot go any deeper, he proves me wrong yet again.\n\nWe have to press on. We cannot let their sacrifice be meaningless." }
WordHunterWoW_QuestEN[24684] = { title = "A Weezil in the Henhouse", description = "<Gann grasps you with a blood-caked hand.>\n\nMy wounds are great but I will not rest until the dwarves of Bael Modan pay for their crimes. <Wheeze> We smuggled a man inside their fortress during our last raid. A goblin saboteur: Weezil Slipshadow. \n\nCreate a disruption at the gates - kill who you can - then slip inside the fortress of Bael'dun to the south and find Weezil.\n\nThat stronghold <cough> can only be destroyed from within, and Weezil can't do it alone.", objectives = "Head into the Bael'Dun Keep and kill 10 Bael'Dun Dwarves (Riflemen, Soldiers, and Officers.) Then find Weezil Slipshadow, who should be hiding within.", progress = "Quiet, you big plodding brute! Keep your voice down.\n\nIf they spot us talking, pretend I'm just ordinary cheese.", completion = "You do good work, <class>. That riot you caused at the fortress entrance has these dwarves running around with their heads cut off." }
WordHunterWoW_QuestEN[24685] = { title = "Dwarf Fortress", description = "I don't know if you noticed on your way in, but this whole fortress is erected around a giant cannon. If we can just find the ammunition magazine, we could blow this place sky-high as easy as kiss-my-hand!\n\nBut to figure it out I'm going to need the fortress schematics, and I haven't been able to steal them yet.\n\nLook for the plans on the lowest floor, right down these stairs.", objectives = "Acquire the Bael'Dun Fortress Schematics.", progress = "Give me the plans, quickly! Our time grows short.\n\nMostly because I've been eating my disguise.", completion = "Let's see, let's see.\n\nIt looks like the artillery shells are prepped here, then loaded into the secure magazine...\n\n<Weezil rubs his hands together.>\n\n<name>, are you ready to blow some stuff up?" }
WordHunterWoW_QuestEN[24686] = { title = "Carried on the Waves", description = "The Bloodpetals of Un'Goro have a fascinating life cycle.\n\nThese trees in front of us bear seeds that fall down into the river when they mature.  The river's current then takes the seed north of here, where the seed hatches - almost like an egg - and a newborn Bloodpetal emerges.\n\nI require these seeds for my studies.  Take this net, and use it to scoop up the bright orange seeds in the river.  You'll have to hunt them down under the water.", objectives = "Use Garl's Net to obtain 4 Bloodpetal Seeds.", progress = "Have you obtained the seeds yet?", completion = "Hmm... yes, these seeds will do nicely.  You have the gratitude of the Cenarion Circle, <name>." }
WordHunterWoW_QuestEN[24687] = { title = "Bouquets of Death", description = "You're already familiar with the first phase of the Bloodpetals' life cycle: the waterborne seed.  The next phase, however, is not so docile: the pack of juveniles.\n\nWhen Bloodpetals hatch, they quickly form gangs and travel together, offsetting their weakness with overwhelming numbers.  These packs of young lashers normally keep to themselves, but upset one of them and you upset them all.\n\nFor our safety and the safety of others, dispose of them.  They roam close by, to the west and north.", objectives = "Kill 6 packs of Juvenile Lashers.", progress = "Remember the tale of Archimonde, <class>.  The young lashers are much weaker than you, but they can still overrun you with their numbers.", completion = "You return victorious.  Good, good... perhaps the crater will now be a bit safer to those who travel through it." }
WordHunterWoW_QuestEN[24688] = { title = "Zen'Aliri", description = "You've already met one of my new students, the young worgen named Garl.  My other student is a troll by the name of Zen'Aliri.  He currently camps with the explorers of Marshal's Expedition, to the west of here.\n\nTake these results to him, {name}, and tell him to read them well.", objectives = "Report to Zen'Aliri in Marshal's Stand." }
WordHunterWoW_QuestEN[24689] = { title = "Flowing to the North", description = "Ithis Moonwarden is the night elf druid who indoctrinated me into the Cenarion Circle.  He has set up camp north of here, near the cliffs of the crater's easternmost edge.  Follow the flow of the Bloodpetal seeds, and I'll wager you'll find him nearby.\n\nMy studies are limited only to seeds and other reagents, but he pursues more advanced matters.  If you are curious to learn more about Un'Goro's flora, you should speak with him now.", objectives = "Report to Ithis Moonwarden in the Roiling Gardens.", completion = "Ahh... did Garl send you?  How are his studies coming?  I find that he can be a bit slow at times, but he's truly a force to be reckoned with when he takes the form of the bear.\n\nNow, we have more pressing matters to attend to." }
WordHunterWoW_QuestEN[24690] = { title = "Blazerunner", description = "I'm still a bit concerned about these fire elementals, {name}.  One last request: head to the top of Fire Plume Ridge, and kill the one they call Blazerunner.  He's the biggest and strongest of all the fire elementals in the crater.  With him gone, I'll be able to sleep much better.", objectives = "Kill Blazerunner.", completion = "At last, Blazerunner is dispatched.  Thanks, <name>... he was driving me batty." }
WordHunterWoW_QuestEN[24691] = { title = "Peculiar Delicacies", description = "Hey bub, interested in making an extra dime?\n\nI've got it on good authority that some interested parties are paying BIG money for silithid legs.  Yes, you heard me right, silithid legs!  Apparently these things are delicious if you cook them right.  They're like underground lobsters, and they live just south of here.\n\nThing is, I'll need a good amount of them to pay for my overhead.  Think you could get me 8 dozen or so?", objectives = "Obtain 96 Silithid Legs.", progress = "I need a lot of them because I've got to pay for shipping, handling, marketing... oh, and I've got to pay you as well.", completion = "Brilliant!  We're on the cusp of something big here, <name>.  Here's your share of the inevitably huge profits.\n\nNow, on to other matters..." }
WordHunterWoW_QuestEN[24692] = { title = "The Fledgling Colossus", description = "If you're here to help, then maybe you can help us with a lurking threat.\n\nTo the south lies the Slithering Scar, a quivering silithid outpost in the middle of the jungle.  You can't miss it.\n\nOne of my scouts reports that the silithid are harboring a young colossus in their large central underground chamber, and once it is fully grown, they plan to unleash it upon Un'Goro!\n\nThis must not be allowed to pass, {name}.  Find the colossus and kill it.", objectives = "Kill the Gorishi Fledgling Colossus.", completion = "You've completed a remarkable task, <name>.  You are truly worthy of commendation.  Thank you, and congratulations!" }
WordHunterWoW_QuestEN[24693] = { title = "Mossy Pile", description = "Here in Marshal's Stand, I can't really do too much profiteering without arousing suspicion from the scientists.  There is, however, another place where I might have use of you.\n\nMy business associate, Gremix, has a camp northwest of here, on the opposite side of the volcano.  He's a savvy business mind, and has a better eye for profit than even I do.  I'm sure he could put you to work, if you'd like to make some more coin.", objectives = "Report to Gremix at Mossy Pile.", completion = "Very well, if Quixxil recommended you, then I suppose you're alright.  In all our years working together, Quixxil's never steered me wrong." }
WordHunterWoW_QuestEN[24694] = { title = "The Shaper's Terrace", description = "<As you look into the orb in front of you, you hear a voice.>\n\nThe crystal pylons have been activated.  A sufficient number of crystals have been gathered.  The prerequisites have been met.  We are prepared for teleport to The Shaper's Terrace.\n\nSpeak to me when you are ready, {race}.  We will consult with The Watcher.", objectives = "Speak with the Un'Goro Examinant to teleport to The Shaper's Terrace, then speak with Nablya.", completion = "I have been watching you, <name>.  Your arrival was not unforeseen.\n\nIn fact, your arrival here has been predetermined for some time now." }
WordHunterWoW_QuestEN[24695] = { title = "Ever Watching From Above", description = "When my master Khaz'Goroth shaped the world you call Azeroth, he designed Un'Goro Crater to be an area for experimentation.  You might call it the Titans' petri dish.\n\nIf you seek further knowledge about the methods in which we observe the world, pull the four levers behind me and complete my tests.", objectives = "Pull the levers behind Nablya and complete her tests.", progress = "You have not yet completed my gauntlet, <name>.", completion = "You have proven to be both wise and agile, young <name>.  You have my blessing to take your newfound knowledge and spread it as you continue on your journey." }
WordHunterWoW_QuestEN[24696] = { title = "Un'Goro: PRK - E - Shizzle's Flyer 02 - Testing It Out", description = "", objectives = "" }
WordHunterWoW_QuestEN[24697] = { title = "How to Make Meat Fresh Again", description = "I don't believe we've met... I'm Nolen Tacker, Marshal Expeditions' new chief of the guards.  I'm also their chef.  There's actually more overlap than you'd think.\n\nI've got a fun little task for you.  Have you seen the spike pits around the perimeter of the camp?  See if you can convince some of the nearby dinosaurs to walk into them.  If you throw this rotten meat at them when they're not looking, it'll either make them hungry or angry.  Either way is fine, as long as they follow you into the pit!", objectives = "Use the Scraps of Rotting Meat on nearby dinosaurs to lure them into the pits around Marshal's Stand.", progress = "Throw the meat, then let the dinosaurs chase you into the pit.  Easy as that!", completion = "Excellent work, <name>.  Now we're a bit safer from dinosaur attacks... plus I've got all this fresh meat to serve to my men." }
WordHunterWoW_QuestEN[24698] = { title = "Adventures in Archaeology", description = "Hey, you want to try my new diemetradon dogs?  No?  Raptor risotto?  Pterrordax ptacos?\n\nFine.  Oh, I just remembered!  I have a friend nearby that might be able to use your assistance.  His name is Spark Nilminer, and he's Marshal Expeditions' chief archaeology officer.\n\nHe's been sent out to Golakka Hot Springs, to the west.  You'll likely find him on the springs' western shore.", objectives = "Report to Spark Nilminer at Golakka Hot Springs.", completion = "Good ol' Nolen.  How is he doing?  Hopefully better than I am..." }
WordHunterWoW_QuestEN[24699] = { title = "Gormashh the Glutinous", description = "Hey, I know!  We've been looking at the wrong tar creatures.\n\nGremix once told me about a larger-than-normal tar creature that he ran into.  It lurks around the tar pit far to the east of here, south of Fungal Rock.  I'll bet that the bigger these creatures get, the stickier they get!  We'll make some money yet, {name}!\n\nDon't forget the scraper!", objectives = "Kill Gormashh and obtain the Unbelievably Sticky Tar.", progress = "I'm counting on you, <name>.  I'm invested pretty heavily into this \"tar as glue\" scheme, and it'd be a shame if you came back empty-handed.", completion = "Yes, this tar is just the stuff...\n\nHey, wait a minute, my hands... I can't seem to get them apart...\n\nMaybe this wasn't such a good idea. Oh, but wait! Super sticky tar remover! That's where the real money is!" }
WordHunterWoW_QuestEN[24700] = { title = "Hard to Harvest", description = "The Lakkari Tar Pits, just north of here, conceal a hidden treasure: rare flowers that grow at the bottom of the pits.  These tarblossoms, as they're called, are valued for their beauty and their durability.  It's been a while since I last harvested tarblossoms, so there should be some new plants growing at the bottom of the pits.  Grab some for me?\n\nBy the way, good luck swimming in tar.  It's nothing like swimming in water.", objectives = "Obtain 4 Tarblossom Blossoms.", progress = "Have you obtained the tarblossoms yet?  I don't see them...", completion = "Oh, there they are.  Great work, handsome!  Here's some gold.  You've earned it." }
WordHunterWoW_QuestEN[24701] = { title = "Marshal's Refuse", description = "A big part of making money is shamelessness.  You have to be willing to profit off of the misfortune of others.  It all ends up boiling down to one question: How much do you love money?\n\nWhen Marshal and his crew abandoned their refuge up to the north, they left behind lots of supplies.  This stuff isn't rare, or even particularly valuable, but it's there if you're willing to take it.  His camp is up in the cliffs, to the north.\n\nOh, and be on the lookout for whatever it was that made them leave...", objectives = "Obtain 10 Discarded Supplies.", progress = "Did you find anything good?", completion = "It's a bunch of junk, but it's a bunch of FREE junk, and that's all that matters to me.\n\nWell, mostly free.  Here's your share.  Thanks!" }
WordHunterWoW_QuestEN[24702] = { title = "Here Lies Dadanga", description = "", objectives = "Obtain 10 Bloodpetal Sprouts.", progress = "Sturdy mount and trusted friend.\n\nDied shortly after the Cataclysm.  He always hated loud noises.\n\nIn lieu of flowers, please drop off a few Bloodpetal sprouts.  In life, he loved nothing more.", completion = "<You almost sense an air of gratitude as you place the Bloodpetal sprouts on the grave.>" }
WordHunterWoW_QuestEN[24703] = { title = "An Important Lesson", description = "What ho, traveler!  You must know that you set foot upon the camp of Maximillian of Northshire!  Mayhap you have heard tales sung of my many exploits?  I can see from the look in your eye that you have.  That glint of recognition plays upon your visage like the White Lady's reflection o'er Stonecairne Lake.\n\nIt is clear to me that you seek adventure.  As you seem able enough, and thoroughly well-intentioned, I would offer to make you my squire.", objectives = "Speak to Maximillian of Northshire to learn more about becoming a squire.", progress = "Your first quest is a simple one, yet it somehow remains unfinished.  Endure my words and become my squire.", completion = "You please me, <name>.  From this day forward, you are no longer a simple beggar, but a squire loyal to Maximillian of Northshire.  Prepare yourself for our first sally, good squire, for together we shall plunge our fists elbow-deep into what they call adventure!" }
WordHunterWoW_QuestEN[24704] = { title = "The Evil Dragons of Un'Goro Crater", description = "This crater is filled with a malignant breed of dragon.  Have you seen them?  They wander all about, parading their spiky backs and lizardy faces all around the Crater.\n\nDon't let them fool you, squire, for these dragons are no minions of graceful Alexstrasza.  They are clearly vicious, and direly in need of a hero's blade.\n\nI have decided that I will slay no less than 15 of them.  As my squire, you must come along.  Should we become separated, you may meet me back here at the Hot Springs.", objectives = "Help Maximillian of Northshire slay 15 \"Dragons\".", completion = "...and that makes 15 of them.\n\nJustice had a name today... and that name was Maximillian of Northshire.  For Doloria!" }
WordHunterWoW_QuestEN[24705] = { title = "Town Dwellers Were Made to be Saved", description = "I've a feeling that we may find more than dragons here in this crater.  My paladin's instinct tells me that there are townsfolk nearby that require our aid. Those in distress cannot be ignored.\n\nLet us sally forth, Squire {name}!  The people of Un'Goro require our aid!", objectives = "Rescue the Dweller by the Shore, the Dweller in the Cliffs, and the Dweller of the North.", completion = "Our duty is fulfilled.  Even so, it troubles me that today's damsels were less than gracious... only the fair-haired one by the lake managed to show us any gratitude for our chivalry.  Perhaps tomorrow's damsels will have thankfulness to match their beauty.\n\nNow we must ride.  More adventures await!" }
WordHunterWoW_QuestEN[24706] = { title = "The Spirits of Golakka Hot Springs", description = "A moment of seriousness now, {name}.  We have an important quest ahead of us.  The treacherous dragons that plague this valley will not cease their mischief until we destroy their repugnant brood mother.  Before we even attempt to complete such a task, we must ask the Light for aid.\n\nI have seen the Light manifest itself nearby, in the form of Spirits floating by the shores of Golakka Hot Springs.  Come, I must speak with them, and ask them for aid.", objectives = "Stand by as Maximillian of Northshire speaks to 2 Steam Furies.", completion = "Might I ask you a question?  What act have you committed to make the spirits so angry at you?  I'm impressed that you had the patience to sit so still while they pummeled you so violently.\n\nNow we may proceed.  The teeth and scales of Un'Goro's greatest dragon await us." }
WordHunterWoW_QuestEN[24707] = { title = "The Ballad of Maximillian", description = "The time we have waited for is upon us, Squire {name}.  Un'Goro's brood mother will perish at my hands.  The gravity of our task weighs heavily on me, but with the power of the Light behind us, we are guaranteed to succeed.\n\nAre you ready to depart?", objectives = "Help Maximillian of Northshire kill the Devilsaur Queen. If you become separated from Maximillian, meet him at Golakka Hot Springs in Un'Goro Crater.", completion = "The day is saved!  Huzzah!  Today we learned that while armor can be replaced, valor has no price.\n\nBecause of your key involvement in this task, I hereby graduate you from squire to fledgling knight.  No longer do the chains of servitude bind you to me; you are free to serve other masters.\n\nGo with honor, young hero!  For chivalry, the Light, and the beauty of Doloria!" }
WordHunterWoW_QuestEN[24708] = { title = "The Fossil-Finder 3000", description = "One of the things I hate the most about digging is the fact that half the time, all you find is dirt.  That's why I've been spending most of my time out here tinkering instead of digging.\n\nLet me show you what I've invented: the Fossil-Finder 3000.  I just put the finishing touches on it.  If it works properly, it should find the largest fossils in the area.  I know, sweet, huh?\n\nTest it out and see if you can find some ridiculously big dinosaur bones.", objectives = "Obtain an Enormous Dinosaur Talon.", progress = "Have you found anything?  Did it work?", completion = "What an interesting femur you've brought here, but why's it all sharp and curvy?\n\n...\n\nWait a minute, that thing's a TALON?  A dinosaur with a talon that size would've been... well, really big, that's for sure.  Is this the only fossil that you found there?" }
WordHunterWoW_QuestEN[24709] = { title = "A Tale of Two Shovels", description = "Hey wait a minute, this bone has pickax marks on it.  These aren't yours, are they?  No, I recognize this mark... this must be that blasted dwarf!  Gah!\n\nLet me step back for a minute and explain.  There's another archaeologist south of here named Durrin Direshovel.  He practices a reckless, devil-may-care brand of archaeology that offends even me.\n\nA priceless fossil, ruined by sloppy pick-work.  This is the last straw, Durrin!\n\n{name}, go put an end to Direshovel and his negligent excavation.", objectives = "Kill Durrin Direshovel and obtain Durrin's Archaeological Findings.", progress = "Is the deed done?  Did you manage to salvage his notes?", completion = "I knew it!  Durrin HAS been digging around here.  And he's been excavating what could be the archaeological find of the century!  Now I just have to find out where he's stashing the bones...\n\nThanks <name>.  You've been a great help." }
WordHunterWoW_QuestEN[24710] = { title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nHe will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", objectives = "Kill Scourgelord Tyrannus.", completion = "Such a senseless waste! Arthas goes too far!\n\nI can only hope what we find in the Halls of Reflection makes this somehow worth it.\n\nIf what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas." }
WordHunterWoW_QuestEN[24711] = { title = "Frostmourne", description = "We've come so far... we're so close to our goal.\n\nI'm uncertain how we're going to escape with so many men lost and so few to keep our path secure, but we must press on.", objectives = "Meet Lady Jaina Proudmoore at the entrance to the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready. Arthas may not be here, but it would be naive to think that he would leave Frostmourne unguarded entirely." }
WordHunterWoW_QuestEN[24712] = { title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nThere, he will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", objectives = "Kill Scourgelord Tyrannus.", completion = "The Halls of Reflection lie ahead.\n\nIf what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas." }
WordHunterWoW_QuestEN[24713] = { title = "Frostmourne", description = "You must press on, hero. We've come so far... we're so close to our goal. For now, I must stay here and secure a path for your exit.\n\nFind Sylvanas and continue the mission.", objectives = "Meet Lady Sylvanas Windrunner inside the entrance to the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready, <class>. I will not be so naive as to think that Arthas left his precious sword entirely unguarded." }
WordHunterWoW_QuestEN[24714] = { title = "Chasing A-Me 01", description = "Unfortunately, something's happened to one of my greatest inventions.  You've seen mechanical squirrels, yes?  Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has been studying the local wildlife at Fungal Rock for several months, but she should have returned by now.  I fear the worst for her.\n\nCan you help me find her?", objectives = "Find A-Me 01 at Fungal Rock.", completion = "A-Me lies motionless before you.  No power seems to be running through her components." }
WordHunterWoW_QuestEN[24715] = { title = "Repairing A-Me 01", description = "<Suddenly, the robotic gorilla's eyes light up, and it begins to speak.>\n\n\"...operational capacity... less than 5%... accidentally... punctured oil reservoir...\"\n\n\"...use coconut milk... rock... save A-Me 01...\"\n\n<A-Me closes her eyes.>", objectives = "You're pretty sure that A-Me 01 has asked you to obtain an Un'Goro Coconut, crack it on the rock nearby, and give her the High Viscosity Coconut Milk.", progress = "<A-Me 01 has gone into power save mode.>", completion = "You pour the coconut milk into what appears to be A-Me 01's oil reservoir.  You hear the sound of gears whirring and actuators firing." }
WordHunterWoW_QuestEN[24716] = { title = "Returning A-Me 01", description = "Greetings.  I unit A-Me 01.  You... <race>?\n\nA-Me's mission to study the local gorillas was success.  A-Me has gathered data and now will bring to Karna.\n\nIt time for A-Me to return to Karna.  You come with?  We embark right away, so make sure you ready first.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Escort A-Me 01 back to Karna Remtravel at Mossy Pile." }
WordHunterWoW_QuestEN[24717] = { title = "The Apes of Un'Goro", description = "There's plenty of money to be had here in Un'Goro, you just need to know where to look!\n\nApes may be common here in Un'Goro, but they're much rarer up north.  In Everlook, a gorilla hide fetches ten times what you'll get for it down here!\n\nI'm not going to send you all the way up to Winterspring - that'd be irresponsible - but I could use your help actually obtaining some hides.\n\nYou'll find gorillas at Fungal Rock, to the northeast, near a waterfall.  Don't forget to check inside the cave!", objectives = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Gremix at Mossy Pile.", progress = "I never know what style is in vogue, so I'll want a few different colors.  Try to get hides from each different type of gorilla there.", completion = "Wow, 2 of each color!  You're certainly an overachiever, <name>.  My companions and I could use a <race> like you around here.  Ever consider a career in profiteering?" }
WordHunterWoW_QuestEN[24718] = { title = "The Mighty U'cha", description = "Looking around, you see bits of red fur laying around this part of the cave.  It appears to match the consistency of gorilla fur.\n\nBased on your conversations with Gremix, you know that he would almost certainly be interested in a red gorilla hide, if you were to obtain one.", objectives = "Bring U'cha's Pelt to Gremix at Mossy Pile.", progress = "Red fur?  What're you waiting for!  Go back and get that red gorilla!  I'll pay you double!", completion = "Wow, look at this one!  Not just the color, but the size of it... you could cover a tauren with this.\n\nHere you go, <name>.  You've earned this.  Stick around, I'm sure we can find something else for you to do." }
WordHunterWoW_QuestEN[24719] = { title = "Claws of White", description = "Stop, {race}.  I could use the help of a {class} like you.\n\nRight outside this camp, there are raptors with deadly claws.  I've been using the claws for druid rituals, but it doesn't seem to be working.  However, I did notice that some of those raptors sometimes have white claws, when most have deathly black ones.\n\nThe earth works in strange ways.  Maybe you could fetch me some of the white claws, and I'll try one last time?", objectives = "Obtain 5 White Ravasaur Claws.", progress = "Have you gotten any of the claws yet?", completion = "My mentor says that sometimes you have to take away from nature before you can give back.  These raptors... I feel that they died for good cause.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[24720] = { title = "Crystals of Power", description = "I'm sure you've noticed 'em, {name}. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?  \n\nYou'll find yellow crystals to the northwest, red crystals to the... oh, I'm sure you'll figure it out.", objectives = "Collect 7 Power Crystals of each color: red, blue, yellow, and green.", progress = "I just know I'm onto something here, <name>!", completion = "Now I will continue my experiments! Thank you, <name>." }
WordHunterWoW_QuestEN[24721] = { title = "The Eastern Pylon", description = "High up in the cliffs above me there is a large crystal pylon.  Who placed it there, I cannot say, nor can I determine any reason that it would be built in such a strange place.\n\nMaybe you can make more of it than I can.  I personally don't care what it does, so you needn't report back to me, but perhaps one of the scholars in Marshal's Stand might be interested in what you discover.", objectives = "Touch the Eastern Crystal Pylon in Un'Goro Crater.", completion = "You were right to bring this pylon to my attention, <name>.  This is just the sort of thing I've been studying." }
WordHunterWoW_QuestEN[24722] = { title = "The Northern Pylon", description = "You've done us a number of favors, {name}... now let Gremix do one for you.  The attacks on Marshal's Refuge were terrible, undoubtedly.  They came without warning, and took no prisoners.  They were lucky that so many of them survived.\n\nA few weeks ago, I came across a crystal pylon in the cliffs to the northeast of here, east of Marshal's Refuge.  I think the pylon and the attacks may be related somehow.  Maybe you can investigate?  I'm sure someone in Marshal's Stand will thank you.", objectives = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", completion = "You think this may be related to the attacks on Marshal's Refuge, <name>?" }
WordHunterWoW_QuestEN[24723] = { title = "The Western Pylon", description = "Durrin's research touched on one area that intrigues me: a potential link between the titans and the dinosaurs.  J.D. Collie back at camp is always talking about titan this and crystal that... maybe she'd be interested.\n\nBefore you report to her, you might want to check out the crystal pylon not far from here.  It's just up in the cliffs, to the west of here.  It's got crystals on it, and it always seemed to me like it might have something to do with the titans.", objectives = "Discover the location of the Western Crystal Pylon.", completion = "A pylon in the west?  And a relationship between titans and dinosaurs?  This is a lot to take in, <name>." }
WordHunterWoW_QuestEN[24724] = { title = "Crystal Restore", description = "", objectives = "The Pylon table allows you to combine green power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to heal yourself or your allies.", progress = "The Pylon table allows you to combine green power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to heal yourself or your allies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
WordHunterWoW_QuestEN[24725] = { title = "Crystal Charge", description = "", objectives = "The Pylon table allows you to combine red power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a large explosion that can inflict damage on your enemies.", progress = "The Pylon table allows you to combine red power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a large explosion that can inflict damage on your enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
WordHunterWoW_QuestEN[24726] = { title = "Crystal Force", description = "", objectives = "The Pylon table allows you to combine green power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to increase your spirit.", progress = "The Pylon table allows you to combine green power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to increase your spirit.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
WordHunterWoW_QuestEN[24727] = { title = "Crystal Spire", description = "", objectives = "The Pylon table allows you to combine blue power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a shield that does damage to enemies.", progress = "The Pylon table allows you to combine blue power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a shield that does damage to enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
WordHunterWoW_QuestEN[24728] = { title = "Crystal Ward", description = "", objectives = "The Pylon table allows you to combine green power crystals with red power crystals.\n\nAccording to J.D.'s manual, this combination can be used to strengthen the protection you have against physical damage.", progress = "The Pylon table allows you to combine green power crystals with red power crystals.\n\nAccording to J.D.'s manual, this combination can be used to strengthen the protection you have against physical damage.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
WordHunterWoW_QuestEN[24729] = { title = "Crystal Yield", description = "", objectives = "The Pylon table allows you to combine red power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to weaken an enemy's defenses.", progress = "The Pylon table allows you to combine red power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to weaken an enemy's defenses.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
WordHunterWoW_QuestEN[24730] = { title = "Roll the Bones", description = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.", objectives = "Obtain 8 Dinosaur Bones.", progress = "Think whatever you want of me, but they're not going to care if the bones they get to research are from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps.  I'll just be happy if we get out of here alive...", completion = "Excellent, these should do the trick.  And now, if you'll permit me, in case anyone's listening...\n\nTHANKS FOR DIGGING ALL OF THESE BONES OUT OF THE GROUND FOR US AND NOT HURTING THE NATIVE BEASTS IN ANY WAY.\n\nWhether you really did or didn't, I don't want to know.  Let's keep it that way, shall we?  Here - maybe this will keep your lips shut on the whole thing.  Anything to get out of here alive, I say!" }
WordHunterWoW_QuestEN[24731] = { title = "The Fare of Lar'korwi", description = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nStart your search to the west.", objectives = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass.", progress = "Do not take my words lightly, <name>. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar'korwi and defeat him.", completion = "This will do nicely, <name>. It seems Lar'korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.\n\nRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you've angered Lar'korwi enough that he will not kill me until after he's tasted your flesh." }
WordHunterWoW_QuestEN[24732] = { title = "The Scent of Lar'korwi", description = "I'm actually surprised he has not come for you yet, {name}. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.", objectives = "Obtain 2 Ravasaur Pheromone Glands.", progress = "Be careful, <name>. Getting close to any nest of eggs surely will provoke the mothers... even if you've already secured a gland from one. The mothers can be just as deadly as Lar'korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar'korwi out from hiding.", completion = "Ah, fine specimens, <name>. The two pieces you've found should be perfect for baiting Lar'korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death." }
WordHunterWoW_QuestEN[24733] = { title = "The Bait for Lar'korwi", description = "This will be the most difficult part because there is some complexity to the plan.  Continue following the river to the north, and look for a bend in the river.  It was here I saw Lar'korwi last.  You will know you are in the right area because of all the bones from massive creatures that once wandered nearby.\n\nTake the meat you recovered and place it there.  Then, rub this mixture I created on the meat.\n\nIf both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.", objectives = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", progress = "Do not let fear overpower you, <name>. Fear is the great betrayer... you must remain strong!", completion = "The Earth Mother be praised! You've done it! Fair play to you, <name>. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.\n\nOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations." }
WordHunterWoW_QuestEN[24734] = { title = "Lost!", description = "You've got to help me, {name}! My friend, Ringo left earlier to explore the volcano to the north of here, and he has been gone way too long. I am really worried about him.\n\nDo you think you could find him? Why don't you take my canteen with you -- if you do find Ringo, I'm sure he'll need it!", objectives = "Find signs of Ringo at Fire Plume Ridge.", progress = "Ringo's sack rests on the rock in front of you.", completion = "You find what appears to be Ringo's belongings.  If he left these here, he can't have gone far away.  Maybe you should look for him." }
WordHunterWoW_QuestEN[24735] = { title = "A Little Help From My Friends", description = "Ugh... It's so hot...\n\nI was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion.\n\nPlease, help me get back to my friend Spraggle at Marshal's Stand. I think I'm well enough to follow you there.\n\nI am feeling a little out of it, so you can slap me if I'm feeling woozy.  If I do happen to faint again, just splash some water on me from Spraggle's canteen. That should work, I hope...", objectives = "Lead Ringo to Spraggle Frock at Marshal's Stand.\n\nIf Ringo feels weak, slap him. If he faints, use Spraggle's Canteen to revive him.", progress = "I've been so worried about Ringo...", completion = "Ringo's not in the best shape, <name>, but I am glad to have him back in one piece!\n\nThank you for finding him." }
WordHunterWoW_QuestEN[24736] = { title = "Shizzle's Flyer", description = "I'm making a flying machine!\n\nI got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death.\n\nSo, will you help me? All I have left to build is the wings, and I was thinking that the webby scales from the pterrordax in the Screaming Reaches to the west would be perfect. There's no way I'm going to go up against one of those, but you look pretty tough. Why don't you give it a try?", objectives = "Collect 35 Webbed Pterrordax Scales.", progress = "Every great vehicle needs a name... I was thinking I'd call it... Pwned!", completion = "Yes, these scales are perfect. I should be able to get this flyer off the ground with these scales for sure!\n\nThanks!" }
WordHunterWoW_QuestEN[24737] = { title = "Super Sticky", description = "I'm always looking for a quick way to earn a gold, {name}. If you help me with my newest idea, I'll let you in on a little of the profit. How does that sound to you?\n\nI thought so!\n\nWe're going to be making some glue. Head to the tar pits just north of here, and collect me some tar. Not just any tar, now, you'll need to get it from the beasts that live around the tar pits. As a bonus, if you use my tar scraper on their corpses, you'll keep your hands nice and clean.", objectives = "Collect 8 samples of Super Sticky Tar.", progress = "Tara's done it again -- this super sticky glue will be all the rage!", completion = "Yeah, this tar is pretty sticky, I guess.  I mean, it's sticky, but it's not \"make fistfuls of money\" sticky.  I guess I'll have to keep thinking." }
WordHunterWoW_QuestEN[24738] = { title = "Williden's Journal", description = "You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the central part of the Crater; according to the journal, he and his companions sought to take a more offensive stance once their refuge was attacked.Upon completion of this quest you will gain:", objectives = "Return the journal to Williden Marshal somewhere in Un'Goro Crater." }
WordHunterWoW_QuestEN[24739] = { title = "Expedition Salvation", description = "I'm Williden Marshal, and I lead a non-aligned expedition troupe.  Now that our camp is more centrally located, it will be much more convenient for us to do many things... such as retrieving some long-forgotten supplies.\n\nWe've left some old supplies at deserted base camps both northeast and southwest of here.  You look like you're capable enough - can you help us by getting them back?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater." }
WordHunterWoW_QuestEN[24740] = { title = "Volcanic Activity", description = "Welcome.  I'm Williden Marshal, and my sister and I run this expedition of explorers and scientists.  You have a moment?\n\nI don't like the look of those elementals on that volcano, {class}.  We have too much equipment, too many notes... one crazed elemental could streak its way through our camp and do terrible, terrible damage.\n\nShow them that their new neighbors aren't to be trifled with.  And bring back the ash that they leave behind... we might as well do a little science while we're at it.", objectives = "Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater.", progress = "Do you think the volcano is active?  I wonder why it didn't explode when the cataclysm hit.", completion = "I hope that did the trick.  I'll take the ash... this may come in handy sometime down the line." }
WordHunterWoW_QuestEN[24741] = { title = "Trading Up", description = "Hobart thinks he's going to feed us on those tiny clucker eggs? Bah! We're going to get some real eggs!\n\nI've already set up some traps on the Raptor Rise up the path to the east. Take this bunch of wild clucker eggs and lay them in the traps. The spiny raptors will go right after the clucker eggs, and then you'll get to trade up to their larger eggs.\n\nGenius!", objectives = "Gather 5 Spiny Raptor Eggs.", progress = "How many did you get? I can just taste the massive omelet we're going to cook up now!", completion = "Nice! Look at the size of those things!\n\nThere's no way that Grapplehammer's going to be able to top those!" }
WordHunterWoW_QuestEN[24742] = { title = "Finding the Source", description = "I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest lava flows.  It gives the measurements in degrees Kraklenheit!\n\nHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!\n\nHot spots usually take the form of a glowing, rocky pillar jutting out of the ground.  You'll find them around the base of Fire Plume Ridge... one trip around the perimeter will likely suffice.", objectives = "Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.\n\nWhenever you find a hot spot, use the thermometer to check the temperature. Keep looking until you find the hottest one.", progress = "I'd go there myself, but... I'm a little scared of the fire elementals there!", completion = "These results are astounding!  My boss will be pleased.  Thank you, kind <race>!" }
WordHunterWoW_QuestEN[24743] = { title = "Shadow's Edge", description = "", objectives = "Listen well, <class>. In accepting this weapon your fate is sealed.\n\nOvercome or succumb.\n\nI have placed your feet upon this path. You are therefore my personal responsibility. Should you failter, I am duty-bound to deliver you from this life.\n\nRemember my words, <race>, and do not fail." }
WordHunterWoW_QuestEN[24744] = { title = "The Biggest Egg Ever", description = "Bamm Megabomb? Who does he think he is? His spiny raptor eggs are no match for what we are about to recover!\n\nAs you well know, each Town-In-A-Box is equipped with a micro mechachicken for just such a dietary emergency. Luckily for us, my keen intellect was able to deduce the location that our prodigious, pre-programmed poultry ran off to.\n\nHead north to the Scorched Gully. But beware, its circuit boards are fried and I imagine it's not so micro any longer!", objectives = "Recover the Biggest Egg Ever.", progress = "Just think about the accolades that will rain down upon me... us, when the Biggest Egg Ever is returned!", completion = "Eureka! My genius saves the day yet again! Take that Bamm Megabomb!\n\nAnd now, to reap the benefits!" }
WordHunterWoW_QuestEN[24745] = { title = "Something is in the Air (and it Ain't Love)", description = "The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!", objectives = "Bring the Faded Lovely Greeting Card to Inspector Snip Snagglebolt in Stormwind.", progress = "Did you take care of those no-good scheming villains?", completion = "What've you got there?\n\nOh hey, this is big. Real big. Most of the crazy details in one little package. Thanks - you really helped us reel this all in. Good working with ya." }
WordHunterWoW_QuestEN[24746] = { title = "REUSE", description = "", objectives = "" }
WordHunterWoW_QuestEN[24747] = { title = "Sabotage!", description = "These dwarven artillery shells have a built-in airburst timer. This is easy! Just sabotage one of the artillery shells in the loading bay and then hoist it up into the magazine. Boom, baby. BOOM!\n\nYou'll find the shells in one of two loading bays behind the main garage on this level. It's right around the corner.\n\nOnce you've rigged the artillery shell... Run! Run like the wind, {name}! Then report to Gann back at camp. I'll be right behind you.", objectives = "Sabotage a Dwarven Artillery Shell and then flee from Bael'Dun before it explodes.", progress = "<Gann only opens his eyes after you prod him. His breathing is little more than a series of shallow gasps.>", completion = "Bael'dun? Destroyed?\n\n<Wincing in pain, Gann twists his head to peer behind him, where plumes of smoke darken the skyline.>\n\n<name>, my friend. You have avenged Taurajo and avenged the Tauren people. The invaders will not soon recover from that blow. Thank you." }
WordHunterWoW_QuestEN[24748] = { title = "The Lich King's Last Stand", description = "Shadowmourne; a newly forged weapon already steeped in this world's history, reborn into an unrivaled destiny.\n\nWith this weapon you bear a solemn responsibility, and the time to carry out that charge is at hand.\n\nTake this weapon of myth and legend and march on the enemy. Avenge the countless heroes lost in his merciless campaign. Bring rest to their tortured souls.\n\nSteel yourself, {class}, and guide Shadowmourne to fulfill the purpose of its creation.", objectives = "Highlord Darion Mograine in Icecrown Citadel wants you to kill the Lich King.", completion = "So, at last it is done.\n\nMay the people of Azeroth remember our deeds here forevermore. May the sacrifices of so many burn in their hearts eternally. May they never fail to risk mortal peril in the face of great evil." }
WordHunterWoW_QuestEN[24749] = { title = "Unholy Infusion", description = "Before your weapon can reach its full potential it must be endowed with its signature powers. First among them is unholiness.\n\nYou must seek out and defeat the one called Professor Putricide, but his death is not your only goal. You must use his resources against him.\n\nFind a way to absorb his mutated slime. Use the foul substance to infuse your weapon with the power of the unholy. Only when this has been done shall I reveal your next task.", objectives = "Highlord Darion Mograine wants you to infuse Shadow's Edge with Unholy power and slay Professor Putricide.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", progress = "Is it done, <race>?", completion = "Well done, <class>.\n\nThe completion of our work draws near." }
WordHunterWoW_QuestEN[24750] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Soratha to the east.", objectives = "Meet with Soratha in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have an intense look about ya though. Fiery eyes. You might have the makings of a real <class>.\n\nLets not waste anymore time 'den." }
WordHunterWoW_QuestEN[24751] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the arcane arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", objectives = "Destroy 6 Tiki Targets.", completion = "Not bad, mon. Ya have a natural flow to ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go." }
WordHunterWoW_QuestEN[24752] = { title = "The Arts of a Mage", description = "As ya' develop ya' powah, ya' gonna start to tink of new spells, new ways to use ya' arcane talents. \n\nGo now, grow ya' skills, and 'den come back an' show me what 'cha figure out.", objectives = "Reach level 3 to learn Frost Nova. Practice using it 2 times against a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya." }
WordHunterWoW_QuestEN[24753] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese." }
WordHunterWoW_QuestEN[24754] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day." }
WordHunterWoW_QuestEN[24755] = { title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", objectives = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear." }
WordHunterWoW_QuestEN[24756] = { title = "Blood Infusion", description = "Your weapon is ready to be endowed with the power of blood.\n\nYou must face Queen Lana'thel in battle and subject yourself to her Blood Mirror. This will cause Shadow's Edge to drink the blood of the nearest living being. That being would be you, {race}.\n\nOnce the blade has been thus awakened, allow the Queen's Frenzied Bloodthirst to take hold of you, feed the blade thrice to sate it, and then give the queen an ignominious death.\n\nMay her screams pierce the ears of the Lich King as he awaits his fate.", objectives = "Highlord Darion Mograine wants you to infuse Shadow's Edge with blood and defeat Queen Lana'thel.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", completion = "Well done, <class>.\n\nShadowmourne is nearly within reach." }
WordHunterWoW_QuestEN[24757] = { title = "Frost Infusion", description = "Shadow's Edge is prepared to receive its final infusion of power.\n\nSindragosa, the enemy's own mount, must fall. But before she is brought down, you must sustain four of her frozen breath attacks without tasting death.\n\nWithout his dragon, nothing shall stand between you and the Lich King.", objectives = "Highlord Darion Mograine has instructed you to slay Sindragosa after subjecting yourself to 4 of her breath attacks while wielding Shadow's Edge.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", completion = "The axe has drunk its fill, <race>, and the forge is nearly ready for the creation of Shadowmourne..." }
WordHunterWoW_QuestEN[24758] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Nekali to the east.", objectives = "Meet with Nekali in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have a weathered look about ya though. Wise eyes. You might have the makings of a real <class>.\n\nLets not waste anymore time 'den." }
WordHunterWoW_QuestEN[24759] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the natural arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", objectives = "Destroy 6 Tiki Targets.", progress = "Power isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. Everytin has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go." }
WordHunterWoW_QuestEN[24760] = { title = "The Arts of a Shaman", description = "As ya grow in powah, you begin ta discovah the voices of da ancestahs speakin' to ya, teachin' you dere secrets.\n\nTha first of 'dese is to focus tha power of da elements into yer weapon. It allows ya to unleash a quick, vicious attack on your enemies. Dis should be easy enough for ya to make a lot of use of it.\n\nTry it out. Let me know when ya tink you have it down.", objectives = "Reach Level 3 to learn Primal Strike, and then use Primal Strike 3 times against a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya." }
WordHunterWoW_QuestEN[24761] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese." }
WordHunterWoW_QuestEN[24762] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day." }
WordHunterWoW_QuestEN[24763] = { title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", objectives = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear." }
WordHunterWoW_QuestEN[24764] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Zen'Tabra to the east.", objectives = "Meet with Zen'Tabra in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have a wild look about ya though. Fierce eyes. You might have the makings of a real <class>.\n\nLets not waste anymore time 'den." }
WordHunterWoW_QuestEN[24765] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the druidic arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", objectives = "Destroy 6 Tiki Targets.", progress = "Strength isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. This'll become more apparent as ya learn animal forms, but it holds true even now. Everytin' has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya casts - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go." }
WordHunterWoW_QuestEN[24766] = { title = "The Arts of a Druid", description = "As ya grow in powah, ya ability to call on nature gets strongah, too. Ya wanna see?\n\nGo get some experience and show me what ya' learn.", objectives = "Reach level 3 to learn Moonfire. Practice using it on a Tiki target in the Darkspear Training Grounds.", completion = "Good work, mon! Dis stuff come easy to ya." }
WordHunterWoW_QuestEN[24767] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese." }
WordHunterWoW_QuestEN[24768] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day." }
