WordHunterWoW_QuestEN[24777] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta use dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", objectives = "Destroy 6 Tiki Targets.", progress = "Aim isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. Everytin has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya attacks - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go." }
WordHunterWoW_QuestEN[24778] = { title = "The Arts of a Hunter", description = "As ya' start to get da hang of tings, ya gonna figure out how ta do new tricks.\n\nOne of da' first ya gonna learn is to keep a steady hand between shots, or else ya gonna find yaself exhausted and not really managin' to kill much.\n\nGo get some more experience 'till ya figure it out, 'den come back and try it out. Let me know when ya tink you have it down.", objectives = "Reach level 3 to learn Steady Shot. Use Steady Shot 5 times on a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya." }
WordHunterWoW_QuestEN[24779] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese." }
