WordHunterWoW_QuestEN[24784] = { title = "Learnin' tha Word", description = "As ya get more skill out there in tha' world, you'll start to discovah' new powahs.\n\nWhy dontcha go out an' go get yaself stronger, and come back when ya learn sometin' new. You can show me what ya learn.", objectives = "Reach level 3 to learn Shadow Word: Pain. Use it 5 times on 5 Tiki training dummies.", completion = "Good work, mon! Dis stuff come easy to ya." }
