WordHunterWoW_QuestEN[24792] = { title = "Man on the Inside", description = "You look like you're fit enough to take on the mastermind behind this operation. The ledger says he's holed up in Shadowfang Keep, so that's where I'm sending you.\n\nWe have a man there already but he's not fit to take down an operation by himself. Head on in; the investigator will meet you there. And bring friends.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Report to Investigator Fezzen Brasstacks in Shadowfang Keep.You look like you're fit enough to take on the mastermind behind this operation. The ledger says he's holed up in Shadowfang Keep, so that's where I'm sending you.\n\nWe have a man there already but he's not fit to take down an operation by himself. Head on in; the investigator will meet you there. And bring friends.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[24793] = { title = "Man on the Inside", description = "You look like you're fit enough to take on the mastermind behind this operation. The ledger says he's holed up in Shadowfang Keep, so that's where I'm sending you.\n\nWe have a man there already but he's not fit to take down an operation by himself. Head on in; the investigator will meet you there. And bring friends.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Report to Investigator Fezzen Brasstacks in Shadowfang Keep.You look like you're fit enough to take on the mastermind behind this operation. The ledger says he's holed up in Shadowfang Keep, so that's where I'm sending you.\n\nWe have a man there already but he's not fit to take down an operation by himself. Head on in; the investigator will meet you there. And bring friends.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[24794] = { title = "Speak With Spraggle", description = "My good friend Spraggle has been fretting about something for some time now.  I'd help her, but as you can see, I'm pretty comfortable right now.\n\nCould you check in with her and see what she needs?", objectives = "Speak to Spraggle Frock in Marshal's Stand.", completion = "What?  Krakle sent you?" }
WordHunterWoW_QuestEN[24795] = { title = "A Victory For The Silver Covenant", description = "In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, {name}. Long have we dreamt of reclaiming Quel'Delar.\n\nThe Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude.\n\nAs a {class}, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? Perhaps the Argent Crusade can find one. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Silver Covenant.", objectives = "Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.", progress = "Is it true that you have restored Quel'Delar?", completion = "That a weapon of such power has been redeemed from the clutches of evil is a great omen in these times, <name>. With Quel'Delar and staunch Silver Covenant allies at our side, the Lich King will have good reason to fear.\n\nThe crusade maintains an arsenal of exceptional weapons for our strongest allies. Allow me to offer you your choice from among them in return for entrusting us with the care of Quel'Delar." }
WordHunterWoW_QuestEN[24796] = { title = "A Victory For The Silver Covenant", description = "In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, {name}. Long have we dreamt of reclaiming Quel'Delar.\n\nThe Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude.\n\nVereesa Windrunner, the leader of the Silver Covenant, asked to see you after you returned from the Sunwell. Take Quel'Delar with you and go to Dalaran's Violet Citadel where she waits, {name}.", objectives = "Bring the Restored Quel'Delar to Vereesa Windrunner at the Violet Citadel in Dalaran.", progress = "Is it true that you have restored Quel'Delar?", completion = "This is nothing short of an amazing accomplishment, <name>. The day that Thalorien and Anasterian fell, the same day that Quel'Delar was lost, was one of the darkest of my life. To see Quel'Delar restored... it is beyond words.\n\nWithout a doubt, you are meant to be the true bearer of the blade. Quel'Delar's magic is already adapting the blade to your skills and your strengths." }
WordHunterWoW_QuestEN[24797] = { title = "REUSE", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[24798] = { title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei!\n\nAll of Silvermoon will celebrate you as a hero, {name}.\n\nAs a {class}, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? No worthy sin'dorei has come forward. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.", objectives = "Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.", progress = "Is it true that you have restored Quel'Delar?", completion = "That a weapon of such power has been redeemed from the clutches of evil is a great omen in these times, <name>. With Quel'Delar and staunch Sunreaver allies at our side, the Lich King will have good reason to fear.\n\nThe crusade maintains an arsenal of exceptional weapons for our strongest allies. Allow me to offer you your choice from among them in return for entrusting us with the care of Quel'Delar." }
WordHunterWoW_QuestEN[24799] = { title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers!\n\nAll the Horde will celebrate you as a hero, {name}.\n\nAs a {class}, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? I will not conceal my disappointment; I had hoped it would be a worthy sin'dorei. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.", objectives = "Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.", progress = "Is it true that you have restored Quel'Delar?", completion = "That a weapon of such power has been redeemed from the clutches of evil is a great omen in these times, <name>. With Quel'Delar and staunch Sunreaver allies at our side, the Lich King will have good reason to fear.\n\nThe crusade maintains an arsenal of exceptional weapons for our strongest allies. Allow me to offer you your choice from among them in return for entrusting us with the care of Quel'Delar." }
WordHunterWoW_QuestEN[24800] = { title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei! All of Silvermoon will proclaim you a hero, as will all of the Horde.\n\nArchmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, {name} and bring Quel'Delar with you. The archmage wishes to congratulate you personally!", objectives = "Bring the Restored Quel'Delar to Archmage Aethas Sunreaver at the Violet Citadel in Dalaran.", progress = "Is it true that you have restored Quel'Delar?", completion = "Quel'Delar rises again, as we sin'dorei have risen from the ashes of defeat and betrayal. The heart and the weapon of Thalorien Dawnseeker are both with you, <name>.\n\nI see the blade has already started adapting itself to your strengths, <name>. Hold your head high and always keep Quel'Delar at your side." }
WordHunterWoW_QuestEN[24801] = { title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers and the Horde! This is a blessing for our efforts against the Lich King.\n\nArchmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, {name} and bring Quel'Delar with you. The archmage wishes to congratulate you personally!", objectives = "Bring the Restored Quel'Delar to Archmage Aethas Sunreaver at the Violet Citadel in Dalaran.", progress = "Is it true that you have restored Quel'Delar?", completion = "Quel'Delar rises again, as the sin'dorei have risen from the ashes of defeat and betrayal. Yet, somehow, the weapon of Thalorien Dawnseeker has chosen to serve an outsider.\n\nBe at ease, <name>. I do not mean to diminish your accomplishment, for you have done what none of my brothers could, although I do not know why. You are clearly meant to be its bearer; the blade is already adapting itself to your abilities. Wield Quel'Delar proudly against our common foes." }
WordHunterWoW_QuestEN[24802] = { title = "Wrath of the Lich King", description = "It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?\n\nMany questions remain, but you need to find Sylvanas and escape the Lich King while there's still time.", objectives = "Find Lady Sylvanas Windrunner and escape the Halls of Reflection.", completion = "Yet again, vengeance slips through my grasp. It's hard to believe how much stronger he's gotten.\n\nIt was foolish of you to come for me, but it's good to know that there are still some champions of the Horde that aren't useless cowards.\n\nThe information Uther gave us may well be key to finally killing Arthas, though it is becoming more and more clear that the Horde will not be able to accomplish this on their own.\n\nGo, <class>. I expect your prowess may be needed again very soon." }
WordHunterWoW_QuestEN[24803] = { title = "Kalu'ak Fishing Derby", description = "", objectives = "The Kalu'ak have a long tradition of honing our fishing skills by putting them to the test every week.\n\nThe first person to catch and bring a blacktip shark to me will be rewarded handsomely, and be known as the greatest fisherman of the north... for a couple of days at least.\n\nThe blacktip shark's favorite food is the pygmy suckerfish. Try fishing for the blacktip wherever you would normally catch the suckerfish.", progress = "The Kalu'ak have a long tradition of honing our fishing skills by putting them to the test every week.\n\nThe first person to catch and bring a blacktip shark to me will be rewarded handsomely, and be known as the greatest fisherman of the north... for a couple of days at least.\n\nThe blacktip shark's favorite food is the pygmy suckerfish. Try fishing for the blacktip wherever you would normally catch the suckerfish.", completion = "Don't just stand there! Give me the shark and I'll declare you the winner!" }
WordHunterWoW_QuestEN[24804] = { title = "Uncommon Scents", description = "Something's not right about this Crown Chemical Company. Steamwheedle's got eyes on 'em, and we could use a few more.\n\nHead to Stormwind if you're interested in helping us out. Inspector Snip Snagglebolt is heading up the investigation there, and he can use all the help he can get.", objectives = "Report to Inspector Snip Snagglebolt in Stormwind.", completion = "Hey. You got some time on your hands? I could use someone like you." }
WordHunterWoW_QuestEN[24805] = { title = "Uncommon Scents", description = "Something's not right about this Crown Chemical Company. Steamwheedle's got eyes on 'em, and we could use a few more.\n\nHead to Orgrimmar if you're interested in helping us out. Detective Snap Snagglebolt is heading up the investigation there, and he can use all the help he can get.", objectives = "Report to Detective Snap Snagglebolt in Orgrimmar.", completion = "Hey. You got some time on your hands? I could use someone like you." }
WordHunterWoW_QuestEN[24806] = { title = "Better Luck Next Time", description = "", objectives = "I'm afraid we've already had a winner for today, young <name>.  However, if you bring a shark, I'll see that it's released back into the waters, and I might just have a little something for you...", progress = "I'm afraid we've already had a winner for today, young <name>.  However, if you bring a shark, I'll see that it's released back into the waters, and I might just have a little something for you...", completion = "I'm afraid we've already had a winner for today, young <name>. However, if you bring a shark, I'll see that it's released back into the waters, and I might just have a little something for you..." }
WordHunterWoW_QuestEN[24807] = { title = "Winnoa Pineforest", description = "While we've accomplished much here, it would be a tragedy if part of this corruption has escaped our notice.  The corridors of the Wailing Cavern stretch throughout the entire Barrens, and if another spot of wild energy has made its way to the surface...\n\nYou've done enough for me, though. I would simply ask that you let a fellow druid of mine know of what's happened here. You will find Winnoa Pineforest at Vendetta Point, southwest of here.", objectives = "Speak to Winnoa Pineforest at Vendetta Point in Southern Barrens.", completion = "I could feel what occured from here, <class>. It bristled every hair I have.\n\nI'm overjoyed to hear you succeeded in pushing those horrors back, and I'll be sure to scour the area for any stray deviate creatures." }
WordHunterWoW_QuestEN[24808] = { title = "Tank Ring Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[24809] = { title = "Healer Ring Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[24810] = { title = "Melee Ring Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[24811] = { title = "Caster Ring Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[24812] = { title = "No More Mercy", description = "Da naga have committed great atrocities on our people. Da time ta show dem mercy has long passed.\n\nEnter da cave and kill any naga you find dere. Every naga dead dis day is one less naga ta take us unawares later on. I trust ya will be thorough.", objectives = "Kill 12 Spitescale Naga.", completion = "Well fought, young <race>." }
WordHunterWoW_QuestEN[24813] = { title = "Territorial Fetish", description = "Dis is no casual counter-attack. We be fully intendin' ta slaughter every last naga here and do anything we can ta ensure that dey will have no desire ta return.\n\nI want ya ta place dese fetishes on any Spitescale banner ya be findin' inside their cave. It should prove a clear statement of what we think of their presence here. More dan dat, da magic in dese fetishes will be weakenin' any Spitescale dat approach, which should make dem second guess stayin' on our isle.", objectives = "Place 8 Territorial Fetishes on Spitescale flags.", completion = "Dat should keep dem at bay." }
WordHunterWoW_QuestEN[24814] = { title = "An Ancient Enemy", description = "Da Sea Witch is here, on top of dis very isle. We've been waitin' a long time for dis chance at revenge and ya will be havin' da privilege of seein' it through.\n\nMeet with Vol'jin, up da ramp to da northeast. Let him know when you are ready ta join da battle.", objectives = "Speak with Vol'jin in Spitescale Cove and aid him in killing Zar'jira, the Sea Witch.", completion = "Tha power d'at burst forth when tha Sea Witch died was immense. I can use d'is power ta enact a vision of places far away.\n\nObserve, youngblood. I want ya ta be here when I make contact wit' Thrall, perhaps it will be grantin' ya insight as well." }
WordHunterWoW_QuestEN[24815] = { title = "Choose Your Path", description = "", objectives = "To atone for the sins I committed as one of the Lich King's Death Knights, I've dedicated myself to creating rings of great power for our brothers and sisters to use in the struggle.\n\nYou've proven yourself as a valuable ally in the fight against the Scourge, <name>. As your dedication continues I can improve on the ring's original design.\n\nChoose your path carefully. A change of heart will come at a price." }
WordHunterWoW_QuestEN[24816] = { title = "Who's Top of the Food Chain Now?", description = "Fine, fine, perhaps the whole egg thing didn't quite pan out. Who's up for some shark meat?\n\nOnly one little problem. Well, a big problem, actually. A really BIG problem: The Hammer!\n\nOf course, I have a brilliant idea. Swim out into the Dire Strait to the west and get us some shark parts. Give them to my assistant, Greely. I'm too important to get my hands dirty with the small details.", objectives = "Collect 5 Shark Parts.", progress = "<name>, take it easy on Grapplehammer. He's a genius, but he's got a fragile ego.", completion = "These will do very nicely! We're going to combine the shark parts and the robotic remains of the Mechachicken into a submersible that should allow you to rid us of that nuisance, The Hammer!" }
WordHunterWoW_QuestEN[24817] = { title = "A Goblin in Shark's Clothing", description = "Combining the remains of the Mechachicken with these shark parts, we've assembled the greatest fighting submersible of all time: the Mechashark X-Steam!\n\nHobart and I want you to pilot it, {name}. Go west to the water and activate the Mechashark X-Steam Controller.\n\nYou must kill The Hammer if we're to have any hope of exploiting the natural resources of the Dire Strait to their fullest extent. It's for the good of the cartel!", objectives = "Activate a Mechashark X-Steam Controller and use the Mechashark X-Steam to slay The Hammer.", progress = "That monstrously humongous shark is not dead yet! Do I have to do everything myself?", completion = "Excellent work, my boy! The Town-In-A-Box is saved and the Bilgewater Cartel will be profitable once again thanks to my overwhelmingly unbelievable intellect and tinkering know-how." }
