WordHunterWoW_QuestEN[24829] = { title = "Path of Destruction", description = "You seek to continue down the path of destruction?", objectives = "You seek to continue down the path of destruction?", progress = "You seek to continue down the path of destruction?", completion = "You are a true champion of our cause, <name>.  None can claim to be more dedicated to the struggle than you.\n\nThe enemy speaks of your name only in whispers, for they know you're a force to be reckoned with.\n\nAccept this humble gift as a reward for your many triumphs." }
WordHunterWoW_QuestEN[24830] = { title = "Path of Wisdom", description = "You seek to continue down the path of wisdom?", objectives = "You seek to continue down the path of wisdom?", progress = "You seek to continue down the path of wisdom?", completion = "You continue to prove yourself, <name>.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
WordHunterWoW_QuestEN[24831] = { title = "Path of Wisdom", description = "You seek to continue down the path of wisdom?", objectives = "You seek to continue down the path of wisdom?", progress = "You seek to continue down the path of wisdom?", completion = "You are a true champion of our cause, <name>.  None can claim to be more dedicated to the struggle than you.\n\nYou are a bastion of wisdom and our allies speak of you with the greatest reverence.  Many of them owe you their own lives.\n\nAccept this humble gift as a reward for your many triumphs." }
WordHunterWoW_QuestEN[24832] = { title = "Path of Vengeance", description = "You seek to continue down the path of vengeance?", objectives = "You seek to continue down the path of vengeance?", progress = "You seek to continue down the path of vengeance?", completion = "You continue to prove yourself, <name>.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
WordHunterWoW_QuestEN[24833] = { title = "Path of Vengeance", description = "You seek to continue down the path of vengeance?", objectives = "You seek to continue down the path of vengeance?", progress = "You seek to continue down the path of vengeance?", completion = "You are a true champion of our cause, <name>.  None can claim to be more dedicated to the struggle than you.\n\nIt is rumored that the minions of the Scourge fear you more than they do the Lich King himself.  You are vengeance incarnate.\n\nAccept this humble gift as a reward for your many triumphs." }
WordHunterWoW_QuestEN[24834] = { title = "Path of Courage", description = "You seek to continue down the path of courage?\n", objectives = "You seek to continue down the path of courage?", progress = "You seek to continue down the path of courage?", completion = "You continue to prove yourself, <name>.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
WordHunterWoW_QuestEN[24835] = { title = "Path of Courage", description = "You seek to continue down the path of courage?\n", objectives = "You seek to continue down the path of courage?", progress = "You seek to continue down the path of courage?", completion = "You are a true champion of our cause, <name>.  None can claim to be more dedicated to the struggle than you.\n\nYou are a source of inspiration to our allies and your unshakeable valor gives pause to even the most seasoned of our enemy's generals.\n\nAccept this humble gift as a reward for your many triumphs." }
